struct N001 {
   long n;
   std::vector<long> parents;
   std::vector<long> numbers;
   N001(long n_) : n(n_), parents(n+1, -1), numbers(n+1, -1) {
   }
};
long find(N001& s, long x) {
   if( s.parents[x] == -1 ) return x;
   return s.parents[x] = find(s, s.parents[x]);
}
bool same(N001& s, long x, long y) {
   return find(s, x) == find(s, y);
}
void unite(N001& s, long x, long y) {
   long x2 = find(s, x);
   long y2 = find(s, y);
   if( x2 == y2 ) return;
   if( not ( s.numbers[x2] <= s.numbers[y2] ) )
      std::swap(x2, y2);
   s.parents[x2] = y2;
   s.numbers[y2] += s.numbers[x2];
}

template<typename W>
struct N003 {
   typedef std::vector<long> LI;
   typedef std::vector<W>    LW;
   long n, e;
   LI ss, ds;
   LW ws;
   std::vector<LI> iss;
   N003(long n_, const LI& ss_, const LI& ds_, const LW& ws_)
      : n(n_), e(ss_.size()), ss(ss_), ds(ds_), ws(ws_) {
      iss.resize(n+1);
      for(long i = 0; i < e; ++i) {
         iss[ss[i]].push_back(i);
      }
   }
};

template<typename W>
struct N007 {
   std::vector<long> xs;
   N007(const N003<W>& g) {
      std::vector<std::pair<W, long>> ys;
      for(long i = 0; i < g.e; ++i) {
         ys.emplace_back(std::make_pair(g.ws[i], i));
      }
      std::sort(ys.begin(), ys.end());
      N001 uf(g.n+1);
      for(auto y : ys) {
         long i = y.second;
         if( not same(uf, g.ss[i], g.ds[i]) ) {
            unite(uf, g.ss[i], g.ds[i]);
            xs.emplace_back(i);
         }
      }
   }
};

