class DisjointSet {
public:
    // rank璁板綍鏍戠殑楂樺害
    vector<int> rank, p;
    DisjointSet() {};
    DisjointSet(int size) {
        rank.resize(size, 0);
        p.resize(size, 0);
        for (int i = 0; i < size; i++)
            makeSet(i);
    }
    void makeSet(int i) {
        p[i] = i;
        rank[i] = 0;
    }

    bool same(int x, int y) {
        return findSet(x) == findSet(y);
    }

    void unite(int x, int y) {
        link(findSet(x), findSet(y));
    }

    void link(int x, int y) {
        // 鍖呭惈x鐨勬爲鐨勯珮搴︽洿楂橈紝鍒欏皢y鐨勬爲鍚堝苟鍒皒涓?
        if (rank[x] > rank[y])
            p[y] = x;
        else {
            p[x] = y;
            if (rank[x] == rank[y])
                rank[y]++;
        }
    }
    int findSet(int x) {
        if (x != p[x])
            p[x] = findSet(p[x]);
        return p[x];
    }
};

class Edge {
public:
    int source, target, cost;
    Edge(int source = 0, int target = 0, int cost = 0) :
        source(source), target(target), cost(cost) {}
    bool operator < (const Edge &e) const {
        return cost < e.cost;
    }
};


int kruskal(int n, vector<Edge> edges) {
    int totalCost = 0;
    sort(edges.begin(), edges.end());

    DisjointSet dset = DisjointSet(n + 1);
    for (int i = 0; i < n; i++)
        dset.makeSet(i);

    int len = edges.size();
    for (int i = 0; i < len; i++) {
        Edge e = edges[i];
        // 鍒ゆ柇鏄惁浼氭垚鐜?
        if (!dset.same(e.source, e.target)) {
            // 娣诲姞鏈€灏忕敓鎴愭爲鐨勮竟
            //MST.push_back(e);
            totalCost += e.cost;
            dset.unite(e.source, e.target);
        }
    }
    return totalCost;
}
