struct UnionFind {
    vi32 data;

    UnionFind(i32 sz) {
        data.assign(sz, -1);
    }

    i32 find(i32 k) {
        if (data[k] < 0) return k;
        return (data[k] = find(data[k]));
    }

    i32 size(i32 k) {
        return (-data[find(k)]);
    }

    bool unite(i32 x, i32 y) {
        x = find(x), y = find(y);
        if (x == y) return (false);
        if (data[x] > data[y]) x^=y^=x^=y;
        data[x] += data[y];
        data[y] = x;
        return (true);
    }
};
