class kruskal
{
  static const int MAX_V = 200010;

  int par[MAX_V];
  int rank_[MAX_V];

  inline int root(int x)
  {
    return par[x] == x ? x : par[x] = root(par[x]); //経路圧縮
  }

  inline bool same(int x, int y)
  {
    return root(x) == root(y);
  }

  void unite(int x, int y)
  {
    x = root(x);
    y = root(y);
    if (x == y)
      return;

    if (rank_[x] < rank_[y])
    {
      par[x] = y;
    }
    else
    {
      par[y] = x;
      if (rank_[x] == rank_[y])
        rank_[x]++;
    }
  }

  struct edge
  {
    ll u, v, cost;
  };

  vector<edge> E;

  static bool comp(edge &e1, edge &e2)
  {
    return e1.cost < e2.cost;
  }

public:
  kruskal(int n)
  {
    for (int i = 0; i < n; ++i)
      par[i] = i, rank_[i] = 0;
  }

  inline void setE(int s, int t, ll w)
  {
    E.push_back({s, t, w});
  }

  ll calc()
  {
    sort(E.begin(), E.end(), comp);
    ll res = 0;
    for (auto e : E)
    {
      if (!same(e.u, e.v))
      {
        unite(e.u, e.v);
        res += e.cost;
      }
    }
    return res;
  }
};

