    if(par[x] == x){
        return x;
    }
    return par[x] = find(par[x]);
}

void unite(int x, int y){
    x = find(x);
    y = find(y);

    if(x == y) return;

    if(rank_[x] < rank_[y]) par[x] = y;
    else{
        par[y] = x;
        if(rank_[x] == rank_[y]) rank_[x]++;
    }
}

