class Disjoint{
    public:

        vector<int> rank, p;

        Disjoint(){}
        Disjoint(int size){
            rank.resize(size, 0);
            p.resize(size,0);

            for(int i=0; i<size; i++){
                Makeset(i);
            }
        }

        void Makeset(int x){
            p[x] = x;
            rank[x] = 0;
        }

        bool same(int x, int y){
            return Findset(x) == Findset(y);
        }

        void unite(int x, int y){
            link(Findset(x), Findset(y));
        }

        void link(int x, int y){
            if(rank[x] > rank[y]){
                p[y] =x;
            }else{
                p[x] = y;
                if(rank[x] == rank[y]){
                    rank[y]++;
                }
            }
        }

        int Findset(int x){
            if(x != p[x]){
                p[x] = Findset(p[x]);
            }
            return p[x];
        }
};

