    Edge(int sou = 0, int tar = 0, int cost = 0):
    sou(sou), tar(tar), cost(cost){}

    bool operator < ( const Edge &e) const{
        return cost < e.cost;

    }

};


int Kruskal(int N, vector<Edge> edges){
    int acost = 0;
