const int MAX_SIZE = 1000000;
const int INF = INT_MAX;

int tree[MAX_SIZE * 2];
int size;
int L;
void Initialize();
void update(int x, int y);
int find(int index, int x, int y, int l, int r);

int main() {

	int n;
	cin >> size >> L;

	n = size;
	Initialize();

	for (int i = 0; i < n; ++i) {
		int value;
		cin >> value;
		update(i, value);
	}

	for (int i = 0; i < n - L + 1; ++i) {
		if (i != 0)
			cout << " ";
		cout << find(0, i, i + L, 0, size);
	}

	cout << endl;

	return 0;
}

void Initialize() {

	int n = size;
	size = 1;
	while (size < n)
		size *= 2;
	for (int i = 0; i < 2 * size - 1; ++i)
		tree[i] = INF;

}

void update(int x, int y) {

	int i = x + size - 1;
	tree[i] = y;

	while (i > 0) {
		i = (i - 1) / 2;
		tree[i] = min(tree[i * 2 + 1], tree[i * 2 + 2]);
	}

}

int find(int index, int x, int y, int l, int r) {

	if (r <= x || y <= l) {
		return INF;
	}
	else if (x <= l && r <= y) {
		return tree[index];
	}
	else {
		int leftValue = find(index * 2 + 1, x, y, l, (r + l) / 2);
		int rightValue = find(index * 2 + 2, x, y, (r + l) / 2, r);
		return min(leftValue, rightValue);
	}

}

