/**
 * UnionFind
 *
 * 検証用問題:
 *
 * * AOJ DSL-1-A
 *   http://judge.u-aizu.ac.jp/onlinejudge/description.jsp?id=DSL_1_A
 */
class UnionFind {
public:
    vector<i64> p;     // 親ノード。ただし根の場合 -(集合の要素数)
    i64         n_set; // 集合の個数

    explicit UnionFind(i64 n) : p(n, -1), n_set(n) {}

    i64 node_count() const { return SIZE(p); }

    // 集合の個数
    i64 set_count() const { return n_set; }

    // xが属する集合のサイズ
    i64 set_size(i64 x) { return -p[root(x)]; }

    bool is_root(i64 x) const { return p[x] < 0; }

    i64 root(i64 x) {
        return compress(x);
    }

    // x, y を併合する
    // 併合できた場合 true を返す(改造用。無改造の場合常に成功する)
    bool unite(i64 x, i64 y) {
        i64 rx = root(x);
        i64 ry = root(y);

        if(rx == ry) return false;

        // 要素数が大きい方を根とするため、必要ならswap処理
        if(set_size(rx) < set_size(ry)) {
            swap(rx, ry);
        }
        // rx を根とする
        p[rx] += p[ry]; // 要素数を加算
        p[ry]  = rx;    // rx を ry の親にする

        --n_set;

        return true;
    }

    // 同一集合に属するか
    bool same(i64 x, i64 y) {
        return root(x) == root(y);
    }

private:
    // 経路圧縮
    // xの根を返す
    i64 compress(i64 x) {
        if(is_root(x)) return x;

        i64 r = compress(p[x]);
        p[x] = r;
        return r;
    }
};

i64 N;
i64 M;

struct Edge {
    i64 from;
    i64 to;
    i64 cost;
    Edge(i64 f, i64 t, i64 c) : from(f), to(t), cost(c) {}
};

void solve() {
    vector<Edge> edges;
    edges.reserve(M);
    REP(_, M) {
        i64 from, to, cost; RD(from); RD(to); RD(cost);
        edges.emplace_back(from, to, cost);
    }
    ALL(sort, edges, [](const auto& lhs, const auto& rhs) {
        return lhs.cost < rhs.cost;
    });

    UnionFind uf(N);
    i64 ans = 0;
    for(const auto& e : edges) {
        if(uf.set_count() == 1) break;
        if(uf.root(e.from) != uf.root(e.to)) {
            uf.unite(e.from, e.to);
            ans += e.cost;
        }
    }

    PRINTLN(ans);
}

signed main(signed /*argc*/, char** /*argv*/) {
    RD(N);
    RD(M);



    solve();

    EXIT();
}

