struct UnionFind {
    i64 size_;
    vector<i64> ps_;

    explicit UnionFind(i64 n) : size_(n), ps_(n,-1) {}

    i64 size() const { return size_; }

    i64 root(i64 x) {
        i64 p = ps_[x];
        if(p < 0) return x;
        return ps_[x] = root(p);
    }

    void unite(i64 x, i64 y) {
        i64 rx = root(x);
        i64 ry = root(y);
        if(rx == ry) return;

        i64 kx = -ps_[rx];
        i64 ky = -ps_[ry];
        if(kx < ky) swap(rx, ry);
        ps_[rx] = -(kx + ky);
        ps_[ry] = rx;

        --size_;
    }
};

i64 graph_mst_boruvka(const vector<vector<pair<i64,i64>>>& g) {
    i64 n = SIZE(g);

    i64 res = 0;
    UnionFind uf(n);
    for(;;) {
        bool updated = false;

        // 連結成分に番号を振り直す
        vector<i64> idxs(n);
        {
            i64 idx = 0;
            REP(v, n) {
                if(uf.root(v) == v) {
                    idxs[v] = idx++;
                }
            }
            REP(v, n) {
                idxs[v] = idxs[uf.root(v)];
            }
            ASSERT(idx == SIZE(uf));
        }
        DBG(idxs);

        // 各連結成分から出ている安全な辺
        vector<tuple<i64,i64,i64>> es(SIZE(uf), make_tuple(INF,-1,-1));  // (cost,from,to)
        REP(v, n) {
            for(const auto& e : g[v]) {
                i64 to,cost; tie(to,cost) = e;
                i64 rfrom = uf.root(v);
                i64 rto   = uf.root(to);
                if(rfrom == rto) continue;
                chmin(es[idxs[rfrom]], make_tuple(cost, v, to));
                chmin(es[idxs[rto]],   make_tuple(cost, to, v));
            }
        }
        DBG(es);

        // 安全な辺をすべて採用
        for(const auto& e : es) {
            i64 cost,from,to; tie(cost,from,to) = e;
            if(from == -1) continue;
            // 2つの連結成分から出ている安全な辺が等しい場合にダブルカ
            // ウントされるのを防ぐため、このチェックが必要
            if(uf.root(from) == uf.root(to)) continue;
            res += cost;
            uf.unite(from, to);
            updated = true;
        }

        if(!updated) break;
    }

    return res;
}

void solve() {
    i64 N = RD();
    i64 M = RD();

    vector<vector<pair<i64,i64>>> G(N);
    REP(_, M) {
        i64 a = RD();
        i64 b = RD();
        i64 c = RD();
        G[a].emplace_back(b, c);
        G[b].emplace_back(a, c);
    }
    DBG(G);

    i64 ans = graph_mst_boruvka(G);

    PRINTLN(ans);
}

signed main() {


    solve();

    return 0;
}

