template<typename T>
struct Prim{
  struct edge{
    int to;
    T cost;
    bool operator < (const edge &e)const
    {
      return cost < e.cost;
    };
  };

  int V;
  std::vector<std::vector<edge>> Edges;
  Prim(int V):V(V), Edges(V){}

  void add_edge(int f, int t, T cost){
    Edges[f].push_back({t, -cost});
    Edges[t].push_back({f, -cost});
  }

  T execution(){
    std::priority_queue<edge>que;
    std::vector<bool>used(V,false);
    que.push({0, 0});
    T ret = 0;
    while(!que.empty()){
      T cost = que.top().cost;
      int v = que.top().to;
      que.pop();
      if(used[v])continue;
      used[v] = true;
      ret += cost;
      for(auto e:Edges[v]){
	que.push(e);
      }
    }
    return -ret;
  }
};
