struct UnionFind {
	std::vector<int> par;
	UnionFind() {}
	UnionFind(int N) : par(N) {
		for (int i = 0; i < N; i++) par[i] = i;
	}
	int root(int x) { // データxが属する木の根
		if (par[x] == x) return x;
		return par[x] = root(par[x]);
	}
	void unite(int x, int y) { // xとyの木を併合
		int rx = root(x);
		int ry = root(y);
		if (rx == ry) return;
		par[rx] = ry;
	}
	bool same(int x, int y) { // 2つのデータx, yが属する木が同じならtrueを返す
		int rx = root(x);
		int ry = root(y);
		return rx == ry;
	}
};
struct Kruskal {
	struct Edge{int u, v,cost;};

	UnionFind uf;
	std::vector<Edge> es;
	Kruskal(){}
	Kruskal(int N):uf(N){}
	void addedge(int s,int t,int w) {
		es.push_back({ s,t,w });
	}

	int kruskal() {
		sort(es.begin(),es.end(), [&](const Edge & e1, const Edge & e2) { return e1.cost < e2.cost; });
		int res = 0;
		for (int i = 0; i < es.size(); i++) {
			const Edge& e = es[i];
			if (!uf.same(e.u, e.v)) {
				uf.unite(e.u, e.v);
				res += e.cost;
			}
		}
		return res;
	}
};

