class DisjointSet {
 public:
  vi rank, p;

  DisjointSet() {}
  DisjointSet(int size) : rank(size, 0), p(size, 0) {
    REP(i, size) make_set(i);
  }

  void make_set(int x) {
    p[x] = x;
    rank[x] = 0;
  }

  bool same(int x, int y) { return find_set(x) == find_set(y); }

  void unite(int x, int y) { link(find_set(x), find_set(y)); }

  void link(int x, int y) {
    if (rank[x] > rank[y]) {
      p[y] = x;
    } else {
      p[x] = y;
      if (rank[x] == rank[y]) rank[y]++;
    }
  }

  int find_set(int x) {
    if (x != p[x]) {
      p[x] = find_set(p[x]);
    }
    return p[x];
  }
};

class Edge {
 public:
  int source, target, cost;
  Edge(int source = 0, int target = 0, int cost = 0)
      : source(source), target(target), cost(cost) {}
  bool operator<(const Edge &e) const { return cost < e.cost; }
};

int kruskal(int n, vector<Edge> &edges) {
  int total_cost = 0;
  sort(ALL(edges));
  auto dset = DisjointSet(n + 1);
  REP(i, n) { dset.make_set(i); }
  for (auto &&e : edges) {
    if (!dset.same(e.source, e.target)) {
      total_cost += e.cost;
      dset.unite(e.source, e.target);
    }
  }
  return total_cost;
}

