using namespace std;

class UnionFind {
	vector<int> data;
	int root(int a) {
		return data[a] < 0 ? a : data[a] = root(data[a]);
	}
public:
	UnionFind(int n) : data(n, -1) {}
	bool Find(int a, int b) {
		return root(a) == root(b);
	}
	void Union(int a, int b) {
		int ra = root(a), rb = root(b);
		if (ra == rb) return;
		if (data[ra] < data[rb]) {
			data[ra] += data[rb];
			data[rb] = a;
		}
		else {
			data[rb] += data[ra];
			data[ra] = b;
		}
	}
};

class MinimumSpanningTree {
	struct edge { int u, v, cost; };
	int V;
	vector<edge> es;
public:
	MinimumSpanningTree(int _V) : V(_V) {}

	void add(int a, int b, int c) {
		es.push_back((edge) { a, b, c });
	}

	int Kruskal() {
		int res = 0;
		UnionFind uf(V);
		sort(es.begin(), es.end(), [](const edge& e1, const edge& e2) { return e1.cost < e2.cost; });
		for (auto &e : es) {
			if (!uf.Find(e.u, e.v)) {
				uf.Union(e.u, e.v);
				res += e.cost;
			}
		}
		return res;
	}

};

