	vector<int> par, nume;
public:
	union_find(){
	}

	union_find(int x){
		par.resize(x);
		nume.resize(x);
		init();
	}

	~union_find(){
		//

	}

	void clear(){
		_setnum = 0;
		par.clear();
		nume.clear();
	}

	void init(){
		_setnum = par.size();
		for(int i = 0; i < par.size(); i++){
			par[i] = i;
			nume[i] = 1;
		}
	}

	void resize(int x){

		par.resize(x);
		nume.resize(x);
		init();
	}

	int find(int x){
		return par[x] == x ? x : par[x] = find(par[x]);
	}

	void unite(int x, int y){
		x = find(x);
		y = find(y);

		if(x == y)return;

		_setnum--;

		if(nume[x] > nume[y]) std::swap(x,y);

		par[x] = y;
		nume[y] += nume[x];
	}

	bool same(int x, int y){
		return find(x) == find(y);
	}

	int numel(int x){
		return nume[find(x)];
	}

	int size(){
		return par.size();
	}

	int setnum(){
		return _setnum;
	}
};

int kruskal(vector<pair<int,pair<int,int>>>& edge, int V){
	union_find uf(V);
	int res = 0, count = 0;

	sort(edge.begin(), edge.end());

	for(int i = 0; i < edge.size(); i++){
		if(!uf.same(edge[i].second.first, edge[i].second.second)){
			uf.unite(edge[i].second.first, edge[i].second.second);
			res += edge[i].first;
			count++;
		}
	}

	if(count == V-1) return res;
	return -1;
}

