//    }
    int sum = 0;
    vector<Edge>::iterator it;
    for (it = g.tree.begin(); it != g.tree.end(); ++it){
        sum += (*it).w;
//        printf("%d %d %d\n", (*it).s, (*it).t, (*it).w);
    }
    printf("%d\n", sum);
}
