struct UnionFind {
    vector<int> dat;

    UnionFind(int n) : dat(n, -1) { }
    void init(int n) { dat.assign(n, -1); }

    int root(int x) {
        if (dat[x] < 0) return x;
        else return dat[x] = root(dat[x]);
    }

    bool issame(int x, int y) {
        return root(x) == root(y);
    }

    bool unite(int x, int y) {
        x = root(x); y = root(y);
        if (x == y) return false;
        if (-dat[x] < -dat[y]) swap(x, y); // union by size
        dat[x] += dat[y];
        dat[y] = x;
        return true;
    }

    int size(int x) {
        return -dat[root(x)];
    }
};

// 辺 e = (u, v) を {l(e), {u, v}} で表す
typedef pair<int, pair<int,int> > Edge;

int main() {
    // 入力
    int N, M; // 頂点数と辺数
    cin >> N >> M;
    vector<Edge> edges(M);
    for (int i = 0; i < M; ++i) {
        int u, v, w; // w は重み
        cin >> u >> v >> w;
        edges[i] = Edge(w, make_pair(u, v));
    }

    // 辺の重みが小さい順にソート
    // pair はデフォルトで (第一要素, 第二要素) の辞書順比較
    sort(edges.begin(), edges.end());

    // Kruskal 法
    long long res = 0;
    UnionFind uf(N);
    for (int i = 0; i < M; ++i) {
        int w = edges[i].first;
        int u = edges[i].second.first;
        int v = edges[i].second.second;
        if (uf.issame(u, v)) continue;

        // 辺を採用
        res += w;
        uf.unite(u, v);
    }
    cout << res << endl;
}

