#define REP(i,n) FOR(i,0,n)
#define FOR(i,a,b) for(int i = (a); i < (b); i++)

const int MAX_NODE_NUM = 10005;
const int MAX_EDGE_NUM = 100005;
int node2edge[MAX_NODE_NUM];
bool isNodeSelected[MAX_NODE_NUM];
using EdgeType = tuple<int, int, int>;
EdgeType swt[MAX_EDGE_NUM * 2];
int main() {
	int n, m;
	cin >> n >> m;
	REP(i, m) {
		int w, s, t;
		cin >> s >> t >> w;
		swt[i] = tie(s,w,t);
		swt[i + m] = tie(t, w, s);
	}
	sort(swt, swt + (2 * m));
	int j = 0;
	REP(i, n) {
		for (; j < 2 * m; j++) {
			if (i <= get<0>(swt[j])) {
				node2edge[i] = j;
				break;
			}
		}
	}

	long long cost = 0;
	int nextSelect = 1;
	int selectNum = 0;
	priority_queue<EdgeType, vector<EdgeType>, greater<EdgeType>> q;
	do {
		for (int i = node2edge[nextSelect]; get<0>(swt[i]) == i; i++) {
				q.push(swt[i]);
		}
		cost += get<1>(swt[nextSelect]);
		isNodeSelected[nextSelect] = true;
		selectNum++;
		while (!q.empty()) {
			int ns = get<2>(q.top());
			q.pop();
			if (isNodeSelected[ns] == false) {
				nextSelect = ns;
				break;
			}
		}
	} while (selectNum < n-1);

	cout << selectNum << "," << cost << endl;

	return 0;
}

