        edges[i] = (Edge) { s, t, w };
    }
    sort(edges, edges + E);
    UnionFind uf = UnionFind();
    uf.init(V);
    int costSum = 0;
    for (Edge e: edges) {
        if (uf.equals(e.source, e.to)) {
            continue;
        }
        costSum += e.cost;
        if (uf.merge(e.source, e.to) == 1) {
            break;
        }
    }

    cout << costSum << endl;
}

