    if (conn1->node1 < conn2->node1) {
        return -1;
    } else if (conn1->node1 > conn2->node1) {
        return 1;
    } else {
        if (conn1->node2 <= conn2->node2) {
            return -1;
        } else {
            return 1;
        }
    }
