class UnionFind {
public:
    vector<int> par;
    vector<int> rnk;
    vector<int> sze;

    UnionFind(ll n): par(n), rnk(n, 0), sze(n, 1) {
        for (ll i = 0; i < n; ++i) par[i] = i;
    }

    void init(int n) {
        for (int i = 0; i < n; i++) {
            par.resize(n);
            rnk.assign(n, 0);
            sze.assign(n, 1);
        }
    }

    int find(int x) {
        if (par[x] == x) return x;
        else return par[x] = find(par[x]);
    }

    bool unite(int x, int y) {
        x = find(x);
        y = find(y);
        if (x == y) return 0;
        if (rnk[x] < rnk[y]) {
            sze[y] = sze[x] + sze[y];
            par[x] = y;
        }
        else {
            sze[x] = sze[x] + sze[y];
            par[y] = x;
            if (rnk[x] == rnk[y]) rnk[x]++;
        }
        return 1;
    }

    bool same(int x, int y) {
        return find(x) == find(y);
    }

    bool size(int x) {
        return sze[find(x)];
    }
};

pair<vector<Pii>, int> Kruscal(int v, pq U) {
    UnionFind uf(v);
    vector<Pii> mst;
    int cost = 0;
    while (!U.empty()) {
        Tiii q = U.top();
        U.pop();
        int c = get<0>(q), ti = get<1>(q), tj = get<2>(q);
        if (!uf.same(ti, tj)) {
            uf.unite(ti, tj);
            mst.emplace_back(ti, tj);
            cost += c;
        }
    }
    return pair<vector<Pii>, int>(mst, cost);
}

