class DisjointSet{
  public:
    vector<int> p, sizes;

    DisjointSet(){}
    DisjointSet(int size){
      p.resize(size);
      sizes.resize(size, 1);
      for(int i=0 ; i<size ; ++i) makeSet(i);
    }
    ~DisjointSet(){}

    void makeSet(int x){
      p[x] = x;
    }

    int findSet(int x){
      if(p[x] == x) return x;
      return p[x] = findSet(p[x]);
    }

    void unite(int x, int y){
      x = findSet(x);
      y = findSet(y);

      if(x != y){
        if(sizes[x] < sizes[y]) swap(x, y);
        sizes[x] += sizes[y];
        sizes[y] = 0;//
        p[y] = x;
      }

      return;
    }

    bool same(int x, int y){
      return findSet(x) == findSet(y);
    }

    int size(int x){
      return sizes[findSet(x)];
    }
};

