}

int craskal(const vector< Pp >& edges, int n)
{
    int count = 0, ans = 0;
    UnionFind UF(n);

    for(Pp e : edges)
    {
        if(!UF.same(e.first.first, e.first.second)){
            ans += e.second;
            UF.unite(e.first.first, e.first.second);
            ++count;
        }
        if(count >= n - 1) break;
    }
    return ans;
}

