template<typename Edge>
typename Edge::cost_type prim(const base_graph<Edge>& g)
{
    using Cost    = typename Edge::cost_type;
    const usize V = g.size();
    using P       = std::pair<Cost, usize>;
    Cost ans      = 0;
    std::vector<bool> used(V, false);
    std::priority_queue<P, std::vector<P>, std::greater<P>> Q;
    Q.push({0, 0});
    while (not Q.empty()) {
        const Cost c  = Q.top().first;
        const usize s = Q.top().second;
        Q.pop();
        if (used[s]) { continue; }
        used[s] = true, ans += c;
        for (const auto& e : g[s]) { Q.push({e.cost(), e.to()}); }
    }
    return ans;
}
