    int n;
    vector<vector<pair<int,T>>> G;
    vector<bool> used;
    Prim(int n):n(n),G(n),used(n,false){}
    void add_edge(int u,int v,T c){
        G[u].emplace_back(v,c);
        G[v].emplace_back(u,c);
    }
    T build(){
        T res=0;
        priority_queue<P,vector<P>,greater<P>> pq;
        pq.emplace(0,0);
