/////Union-Find
LL par[EMAX];
LL rnk[EMAX];

//n要素で初期化
void UNinit(LL n){
    for(LL i=0;i<=n;i++){
        par[i]=i;
        rnk[i]=0;
    }
}

//木の根を求める
LL UNfind(LL x){
    if(par[x]==x){
        return x;
    }else{
        return par[x]=UNfind(par[x]);
    }
}

//xとyの属する集合を併合
void UNunite(LL x,LL y){
    x=UNfind(x);
    y=UNfind(y);
    if(x==y) return;
    if(rnk[x]<rnk[y]){
        par[x]=y;
    }else{
        par[y]=x;
        if(rnk[x]==rnk[y]) rnk[x]++;
    }
}

//xとyが同じ集合に属するか否か
bool UNsame(LL x,LL y){
    return UNfind(x)==UNfind(y);
}

