class UnionFindTree{
private:
	vll par, rank, size;
public:
	UnionFindTree(ll num): par(num), rank(num), size(num, 1){
		REP(i, num) par[i] = i;
	}
	bool Same(ll x, ll y) { return Root(x) == Root(y); }
	ll Root(ll x) { return (par[x] == x) ? x : par[x]=Root(par[x]); }
	ll Size(ll x){ return size[Root(x)]; }
	void Unite(ll x, ll y){
		x = Root(x);
		y = Root(y);
		if (x == y) return;
		if (rank[x] < rank[y]) par[x] = y;
		else                   par[y] = x;
		if (rank[x] == rank[y]) rank[x]++;
		size[x] = size[y] = size[x] + size[y];
	}
};



void solve()
{
	ll V, E;  cin >> V >> E;
	vector<tuple<ll, ll, ll>> stw = cinv3<ll, ll, ll>(E);
	sort(stw.begin(), stw.end(),
		[](auto &a, auto &b){
			return get<2>(a) < get<2>(b);
		}
	);

	UnionFindTree uft(V);
	ll sum=0, count=0;
	REP(i, E){
		ll s; ll t; ll w;  tie(s, t, w) = stw[i];
		if (uft.Same(s, t)) continue;
		uft.Unite(s, t);
		sum += w;
		count++;
		if (count == V-1) break;
	}
	cout << sum << '\n';
}


int main(){
	solve();
	return 0;
}

