	int V, E; cin >> V >> E;
	for(int i = 0; i < E; i++){
		int s, t, w; cin >> s >> t >> w;
		edge e = {s, t, w};
		g.push_back(e);
	}

	UnionFindTree<10000> uf;
	sort(begin(g), end(g), comp);
	ll res = 0;
	for(int i = 0; i < E; i++){
		int a = g[i].from, b = g[i].to;
		if(not uf.same(a, b)){
			uf.unite(a, b); res+= (ll) g[i].cost;
		}
	}

	cout << res << '\n';

	return 0;
}

