struct DisjointSet {
  std::vector<int> rank, p;
  DisjointSet() = default;
  DisjointSet(const int n) {
    rank.resize(n, 0);
    p.resize(n, 0);
    for (int i = 0; i < n; ++i) makeSet(i);
  }

  void makeSet(int i) {
    p[i] = i;
    rank[i] = 0;
  }

  int findSet(int x) {
    if (x != p[x]) {
      p[x] = findSet(p[x]);
    }
    return p[x];
  }

  bool same(int x, int y) { return findSet(x) == findSet(y); }

  void unite(int x, int y) {
    auto rep_x = findSet(x), rep_y = findSet(y);
    if (rank[rep_x] < rank[rep_y])
      p[rep_x] = rep_y;
    else if (rank[rep_x] > rank[rep_y])
      p[rep_y] = rep_x;
    else {
      p[rep_x] = rep_y;
      rank[rep_y]++;
    }
  }
};

struct Edge {
  int source;
  int target;
  int weight;

  Edge() = default;
  Edge(int s, int t, int w) : source(s), target(t), weight(w){};
};

int MST(std::vector<Edge> edges, int V) {
  std::sort(edges.begin(), edges.end(),
            [](Edge x, Edge y) { return x.weight < y.weight; });
  std::vector<Edge> K;

  DisjointSet djs(V);

  for (auto edge : edges) {
    if (!djs.same(edge.source, edge.target)) {
      djs.unite(edge.source, edge.target);
      K.push_back(edge);
    }
  }

  auto sum_weight = 0;
  for (auto edge : K) sum_weight += edge.weight;

  return sum_weight;
}

