class uf{
public:
  vector<int> r;
  uf(int n):r(n,-1){};
  int find(int x,int y){
    // cout << root(x) << " " << root(y) << endl;
    if(root(x)==root(y))return 0;
    if(root(x)<root(y))return -1;
    if(root(x)>root(y))return 1;
  }
  int root(int x){
    if(r[x]==-1)return x;
    else return r[x]=root(r[x]);
  }
  void join(int x,int y){
    x=root(x);y=root(y);
    if(x!=y){
      r[x]=y;
    }
  }
};

class graph{
public:
  int vnum;
  vector<edge> E;
  uf u;
  graph(int n):vnum(n),u(n){};
  int kraskal(){
    int res=0;
    sort(E.begin(),E.end());
    for(int i=0,c=0;i<E.size()&&c<vnum-1;i++){
      // cout << E[i].c << endl;
      if(u.find(E[i].f,E[i].t)){
        u.join(E[i].f,E[i].t);
        // cout << E[i].f << " " << E[i].t << endl;
        res+=E[i].c;
        c++;
      }
    }
    return res;
  }
};

