ll V;
ll d[MAX_N] = {};
struct edge { ll to, cost; };
typedef pair<ll, ll> P;
vector<edge> G[MAX_N];
priority_queue <P, vector<P>, greater<P>> que;
bool mst[MAX_N];

ll cost = 0;
void prim(ll s) {
	fill(d, d + V, INF);
	d[s] = 0;
	que.push(P(0, s));

	while (!que.empty()) {
		P p = que.top(); que.pop();
		ll v = p.second;
		if (mst[v])continue;

		cost += p.first;
		mst[v] = true;

		bool complete = true;
		rep(i, 0, G[v].size()) {
			edge e = G[v][i];
			//if (!mst[e.to]) {
			if (!mst[e.to] && d[e.to] > d[v] + e.cost) {
				d[e.to] = d[v] + e.cost;
				que.push(P(e.cost, e.to));
				complete = false;
			}
		}
		if (complete)break;
	}
}

