// プリム法: 最小全域木のコストの合計値を返す O(|E|log|V|)

int prim() {
  priority_queue<P, vector<P>, greater<P>> pq;
  for (int i = 0; i < V; ++i) {
    mincost[i] = INF;
    used[i] = false;
  }
  mincost[0] = 0;
  pq.push(P(0,0));
  int res = 0;
  while (!pq.empty()) {
    P p = pq.top(); pq.pop();
    int v = p.second;
    if (used[v]) continue;
    used[v] = 1;
    res += p.first;
    for (edge e : g[v]) {
      pq.push(P(e.cost, e.to));
    }
  }
  return res;
}

