class UFT{
public:
	UFT():parent(this){};
	UFT *&find(){
		if (parent == this){
			return parent;
		}else{
			return (parent = parent->find());
		}
	}
	void set_union(UFT &new_parent){
		find()->set_parent(new_parent.find());
	}
	bool operator==(UFT &other){
		return (find() == other.find());
	}
private:
	UFT *parent;
	void set_parent(UFT *new_parent){parent = new_parent;}
};
class Edge{
public:
	int s, t, w;
	Edge(int start = 0, int to = 0, int weight = 0):s(start), t(to), w(weight){};
	bool operator<=(const Edge &e) const {return w >= e.w;}
	bool operator<(const Edge &e) const {return w > e.w;}
	bool operator>=(const Edge &e) const {return w <= e.w;}
	bool operator>(const Edge &e) const {return w < e.w;}
	bool operator==(const Edge &e) const {return w == e.w;}
};
int main(){
	int v, e;
	std::scanf("%d %d", &v, &e);
	std::priority_queue<Edge> queue;
	std::vector<UFT> node(v);
	for (auto i = 0; i < e; ++i){
		int s, t, w;
		std::scanf("%d %d %d", &s, &t, &w);
		queue.push(Edge(s, t, w));
	}
	int sum = 0;
	while (queue.size() > 0){
		if (node.at(queue.top().s) == node.at(queue.top().t)){
			queue.pop();
		}else{
			sum += queue.top().w;
			node.at(queue.top().s).set_union(node.at(queue.top().t));
			queue.pop();
		}
	}
	std::printf("%d\n", sum);
}

#include <iostream>
#include <algorithm>
#define MAX_V 10000
#define MAX_E 100000

using namespace std;

struct edge{
  int from,to,cost;
  edge(int f = -1,int t = -1,int c = -1) : from(f) ,to(t) ,cost(c) {}
};

int V,E;
int par[MAX_V],rank[MAX_V];
edge es[MAX_E];

bool cmp(const edge &e1,const edge &e2){
  return e1.cost < e2.cost;
}

void init(int n){
  for(int i = 0 ; i < n ; i++){
    par[i] = i;
    rank[i] = 0;
  }
}

int find(int x){
  if(par[x] == x){
    return x;
  }
  return par[x] = find(par[x]);
}

void unite(int x,int y){
  x = find(x);
  y = find(y);

  if(x == y) return;
  if(rank[x] < rank[y]){
    par[x] = y;
  }else{
    par[y] = x;
    if(rank[x] == rank[y]) rank[x]++;
  }
}

bool same(int x,int y){
  return find(x) == find(y);
}

int kruskal(){
  sort(es, es+E, cmp);
  init(V);

  int res = 0;
  for(int i = 0 ; i < E ; i++){
    edge e = es[i];
    if(!same(e.from,e.to)){
      unite(e.from,e.to);
      res += e.cost;
    }
  }

  return res;
}

int main(){
  cin >> V >> E;
  for(int i = 0 ; i < E ; i++){
    cin >> es[i].from >> es[i].to >> es[i].cost;
  }
  cout << kruskal() << endl;

  return 0;
}

