class DisjointSet {
public:
  vector <int> rank, p;
  DisjointSet() {}
  DisjointSet(int size) {
    rank.resize(size, 0);
    p.resize(size, 0);
    for (int i = 0; i < size; i++) makeSet(i);
  }
  void makeSet(int x) {
    p[x] = x;
    rank[x] = 0;
  }
  bool same(int x, int y) {
    return findSet(x) == findSet(y);
  }
  void unite(int x, int y) {
    link(findSet(x), findSet(y));
  }
  void link(int x, int y) {
    if (rank[x] > rank[y]) {
      p[y] = x;
    }else {
      p[x] = y;
      if (rank[x] == rank[y]) {
	rank[y]++;
      }
    }
  }
  int findSet(int x) {
    if (x != p[x]) {
      p[x] = findSet(p[x]);
    }
    return p[x];
  }
};

class edge {
public:
  int from, to, cost;
  edge(int from = 0, int to = 0, int cost = 0): from(from), to(to), cost(cost) {}
  bool operator < (const edge &e) const {
    return cost < e.cost;
  }
};

edge es[MAX_E];
int V, E;

int kruskal() {
  sort(es, es+E);
  DisjointSet ds = DisjointSet(V);
  int ret = 0;
  for (int i = 0; i < E; i++) {
    edge e = es[i];
    if (!ds.same(e.from, e.to)) {
      ds.unite(e.from, e.to);
      ret += e.cost;
    }
  }
  return ret;
}

