	int ans = 0;
	sort( edge.begin(), edge.end() );
	UnionFind uf( V );
	for( int i = 0; i < E; i++ ) {
		int s, t, w;
		tie( w, s, t ) = edge[i];
		if( uf.findSet( s, t ) ) continue;
		uf.unionSet( s, t );
		ans += w;
	}

	cout << ans << endl;
}

