class union_find{
public:
    union_find(int N){
        parent = new int[N];
        rank = new int[N];
        for(int i = 0; i < N; i++){
            parent[i] = i;
            rank[i] = 0;
        }
    }

    int root(int x){
        if(parent[x] == x){
            return x;
        }else{
            return parent[x] = root(parent[x]);
        }
    }

    void unite(int x, int y);
    bool same(int x, int y){
        return root(x) == root(y);
    }
private:
    int *parent;
    int *rank;
};


void union_find::unite(int x, int y){
    x = root(x);
    y = root(y);

    if(x == y) return;

    if(rank[x] < rank[y]){
        parent[x] = y;
    }else{
        parent[y] = x;
        if(rank[x] == rank[y]){
            rank[x]++;
        }
    }
}

