    cin>>V>>E;
    Graph g(V);
    for(int i=0;i<E;i++){
        int s,t;
        Weight w;
        cin>>s>>t>>w;
        g[s].push_back(Edge(s,t,w));
    }
    cout<<prim(g)<<endl;
    return 0;
}

