class DisjointSet {
public:
    VI rank, p;

    DisjointSet() {}
    DisjointSet(int size) {
        rank.resize(size, 0);
        p.resize(size, 0);
        REP(i, size) p[i] = i;
    }

    void makeSet(int x) {
        p[x] = x;
        rank[x] = 0;
    }

    bool same(int x, int y) { return _findSet(x) == _findSet(y); }

    void unite(int x, int y) { _link(_findSet(x), _findSet(y)); }

private:
    void _link(int x, int y) {
        if (rank[x] > rank[y]) {
            p[y] = x;
        } else {
            p[x] = y;
            if (rank[x] == rank[y]) {
                rank[y]++;
            }
        }
    }

    int _findSet(int x) {
        if (x != p[x]) {
            p[x] = _findSet(p[x]);
        }
        return p[x];
    }
};

class Edge {
public:
    int source, target, cost;
    Edge(int source = 0, int target = 0, int cost = 0)
        : source(source), target(target), cost(cost) {}
    bool operator<(const Edge &e) const { return cost < e.cost; }
};

int kruskal(int N, vector<Edge> edges) {
    int totalCost = 0;
    sort(edges.begin(), edges.end());
    DisjointSet dset = DisjointSet(N + 1);

    REP(i, N) dset.makeSet(i);

    REP(i, edges.size()) {
        Edge e = edges[i];
        if (!dset.same(e.source, e.target)) {
            totalCost += e.cost;
            dset.unite(e.source, e.target);
        }
    }
    return totalCost;
}

