// ------ disjoint set ------ //
struct UnionFind {
    vector<int> data;
    int __size;
    UnionFind(int size) : data(size, -1), __size(size) { }
    bool unionSet(int x, int y) {
        if ((x = root(x)) != (y = root(y))) {
            if (data[y] < data[x]) swap(x, y);  // par -> child とは限らない
            data[x] += data[y]; data[y] = x; __size--;
        }
        return x != y;
    }
    bool findSet(int x, int y) { return root(x) == root(y); }
    int root(int x) { return data[x] < 0 ? x : data[x] = root(data[x]); }
    int size(int x) { return -data[root(x)]; }
    int size() { return __size; }
};

// ------ minimumSpanningForest ------ //
pair<Weight, Edges> kruskal(Graph &g) {
    int n = g.size();
    UnionFind uf(n);
    priority_queue<Edge> PQ;
    for (int u = 0; u < n; u++) for (Edge &e : g[u]) {
        if (u < e.dst) PQ.push(e);
    }
    Weight total = 0;
    Edges F;
    while (F.size() < n-1 && !PQ.empty()) {
        Edge e = PQ.top(); PQ.pop();
        if (uf.unionSet(e.src, e.dst)) {
            F.push_back(e);
            total += e.weight;
        }
    }
    return pair<Weight, Edges>(total, F);
}

