struct UnionFind{

    vector<int> par;     //par[i] := iの親の番号

    //最初は全てが寝であるとして初期化
    UnionFind(int n) : par(n){
        for(int i = 0; i < n; i++) par[i] = i;
    }

    //データ x が属する木の根を再帰で得る : root(x) = {x の木の根}
    int root(int x){
        if(par[x] == x) return x;
        return root(par[x]);
    }

    //x と y の木を併合
    void unite(int x, int y){
        int rx = root(x);
        int ry = root(y);
        if(rx == ry) return;
        par[rx] = ry;
    }

    //x と y のが属する木が同じか
    bool same(int x, int y){
        return root(x) == root(y);
    }
};

struct info{
    int s, t, w;
    info(){}
    info(int s, int t, int w):s(s),t(t),w(w){}
    bool operator<(const info &a) const{
        return w < a.w;
    }
    bool operator>(const info &a) const{
        return w > a.w;
    }
};

int main(){

    int v, e; cin >> v >> e;
    UnionFind unionfind(v);
    vector<info> edge;
    for(int i = 0; i < e; i++){
        int s, t, w; cin >> s >> t >> w;
        edge.push_back(info(s, t, w));
    }

    sort(edge.begin(), edge.end());

    int ans = 0;
    for(auto x : edge){
        if(!unionfind.same(x.s, x.t)){
            ans += x.w;
            unionfind.unite(x.s, x.t);
        }
    }

    cout << ans << endl;
    return 0;
}

