class UnionFind {
private:
	class Node {
	public:
		int parent;

		Node(int parent) {
			this->parent = parent;
		}
	};

	int root(int x) {
		int base = x;
		while (x != node[x].parent) {
			x = node[x].parent;
		}
		node[base].parent = x;
		return x;
	}

	vector<Node> node;
public:
	UnionFind(int size) {
		for (int i = 0; i < size; i++) {
			node.push_back(Node(i));
		}
	}

	void unite(int x, int y) {
		node[root(x)].parent = root(y);
	}

	bool same(int x, int y) {
		return root(x) == root(y);
	}
};

