int build_mst() {
	int mst_edge_count = 0;
	int sum = 0;
	for (int mst_edge_count = 0; mst_edge_count < v_ - 1; ++mst_edge_count) {
		//cout << "mst_edge_count = " << mst_edge_count << endl;
		for (auto s : visited_nodes) {
			//cout << "s = " << s << endl;
			auto l = adjacency_list[s];
			while (!l.empty()) {
				auto e = l[l.size() - 1];
				//cout << "current edge: " << e.s_ << " " << e.t_ << " " << e.w_ << endl;
				if (visited_nodes.count(e.t_) == 0) {
					//cout << "not visited, adding to the queue." << endl;
					candidate_edge_queue.emplace(e);
				}

				//cout << "vector size before: " << l.size() << endl;
				l.pop_back();
				//cout << "vector size after: " << l.size() << endl;
				adjacency_list[s] = l;
			}
		}

		if (!candidate_edge_queue.empty()) {
			WeightedEdge next_edge = candidate_edge_queue.top();
			//cout << "next edge: " << next_edge.s_ << " " << next_edge.t_ << " " << next_edge.w_ << endl;
			visited_nodes.insert(next_edge.t_); // results[current.activityId].push_back(current.executionTime);
			candidate_edge_queue.pop();
			sum += next_edge.w_;
		}
	}

	return sum;
}

