	int v = V - 1;
	while (v) {
		Edge edge = eq.top();
		if (!same(edge.vx_a, edge.vx_b)) {
			unite(edge.vx_a, edge.vx_b);
			cost += edge.w;
			v--;
		}
		eq.pop();
	}
	return cost;
}

