	scanf("%d%d", &V, &E);
	init();
	for (int i = 0; i < E; i++) {
		int s, t, w;
		scanf("%d%d%d", &s, &t, &w);
		eq.push({ s, t, w });
	}
	printf("%d\n", mst_cost());

	return 0;
}

