    union_find(int n) { init(n); }

    void init(int n) {
        size = n;
        count_group = n;
        parent.resize(size);
        rank.assign(size, 0);
        gs.assign(size, 1);
        for (int i = 0; i < size; ++i) parent[i] = i;
    }

    int find(int x) {
        if (parent[x] == x)
            return x;
        else
            return parent[x] = find(parent[x]);
    }

    void unite(int x, int y) {
        x = find(x);
        y = find(y);
        if (x == y) return;
        if (rank[x] < rank[y]) {
            parent[x] = y;
            gs[y] += gs[x];
        } else {
            parent[y] = x;
            gs[x] += gs[y];
            if (rank[x] == rank[y]) ++rank[x];
        }
        --count_group;
    }

    bool is_same_group(int x, int y) {
        return find(x) == find(y);
    }

    int group_size(int x) {
        return gs[find(x)];
    };
};

void solve() {
    //constexpr i64 mod = 1'000'000'007;
    i64 V,E;
    cin >> V >> E;

    vector<tuple<i64,i64,i64>> edges;
    rep(i,0,E){
        i64 s,t,w;
        cin >> s >> t >> w;
        edges.emplace_back(make_tuple(w,s,t));
    }

    sort(begin(edges),end(edges));

    i64 ans=0;
    union_find uf(V);
    for(const auto& e:edges){
        i64 s,t,w;
        tie(w,s,t)=e;
        if(uf.is_same_group(s,t)) continue;
        uf.unite(s,t);
        ans+=w;
    }

    cout << ans << endl;
}

int main() {
    std::cin.tie(0);
    std::ios::sync_with_stdio(false);
    cout.setf(ios::fixed);
    cout.precision(16);
    solve();
    return 0;
}

