class MSTree
{
public:
  int nv;
  vector<vector<pair<int,int>>> adj;
  vector<bool> visited;
  MSTree(){}
  MSTree( int n ) : nv(n) { adj.resize( n ); visited.resize( n, false ); }
  void setAdj( int u, int v, int w );
  int prim();
};

void MSTree::setAdj( int u, int v, int w )
{
  adj[u].push_back( make_pair(v, w) );
  adj[v].push_back( make_pair(u, w) );
}

int MSTree::prim()
{
  if ( nv == 1 ) return 0;

  visited[0] = true;

  int l = 0;

  bool fin = false;

  while ( ! fin )
    {
      fin = true;
      int mw = 2000000000;
      int mv = 0;

      for ( auto i = 0; i < nv; ++i )
        {
          if ( ! visited[i] )
            {
              fin = false;
              for ( auto it = adj[i].begin(); it != adj[i].end(); ++it )
                {
                  int v = (*it).first;
                  int w = (*it).second;
                  if ( visited[v] && mw > w )
                    {
                      mw = w;
                      mv = i;
                    }
                }
            }
        }

      if ( ! fin )
        {
          l += mw;
          visited[mv] = true;
        }
    }

  return l;
}

