class DisjointSet {
  vector<int> p;
  vector<int> r;

public:
  DisjointSet(int n) {
    for (int i = 0; i < n; i++) {
      p.push_back(i);
      r.push_back(0);
    }
  }

  int findRoot(int u) {
    while (u != p[u]) {
      p[u] = p[p[u]];
      u = p[u];
    }
    return p[u];
  }

  bool isSame(int u, int v) {
    return (findRoot(u) == findRoot(v));
  }

  void link(int u, int v) {
    int u_root = findRoot(u);
    int v_root = findRoot(v);

    if (r[u_root] < r[v_root]) {
      p[u_root] = v_root;
    } else {
      p[v_root] = u_root;
      if (r[u_root] == r[v_root]) r[u_root]++;
    }
  }
};

