struct union_find{
    vector<int> par, size;

    union_find(int sz){
        par.resize(sz, -1);
        size.resize(sz, 1);
    }

    int find(int a){
        if(par[a] == -1){
            return a;
        }
        return par[a] = find(par[a]);
    }

    void unite(int a, int b){
        int root_a = find(a), root_b = find(b);
        if(root_a == root_b){
            return;
        }
        if(size[root_a] < size[root_b]){
            swap(a, b);
            swap(root_a, root_b);
        }
        par[root_b] = root_a;
        size[root_a] += size[root_b];
    }

    bool is_group(int a, int b){
        return find(a) == find(b);
    }
};

