class UnionFind{
public:
    vector<ll> par;
    vector<ll> siz;

    UnionFind(ll k):par(k), siz(k,1LL){
        for(int i = 0; i < k; i++) par[i] = i;
    }

    ll root(ll k){
        if(par[k] == k) return k;
        else return par[k] = root(par[k]);
    }

    bool unite(ll x, ll y){
        x = root(x);
        y = root(y);
        if(x==y) return false;

        if(siz[x] < siz[y]) swap(x, y);
        par[y] = x;
        siz[x] += siz[y];
        return true;
    }

    bool same(ll x, ll y){
        return root(x) == root(y);
    }

    ll size(ll x){
        return siz[root(x)];
    }
};

