using namespace std;

struct UnionFind {
    vector<int> par;
    vector<int> rank;
    vector<int> num;
    UnionFind(int N) : par(N), rank(N), num(N) {
        for(int i = 0; i < N; i++) {
            par[i] = i;
            rank[i] = 0;
            num[i] = 1;
        }
    }

    int root(int x) {
        if (par[x] == x) return x;
        return par[x] = root(par[x]);
    }

    bool unite(int x, int y) {
        x = root(x); y = root(y);
        if (x == y) return false;
        if (rank[x] < rank[y]) swap(x, y);
        if (rank[x] == rank[y]) rank[x]++;
        par[y] = x;
        num[x] += num[y];
        num[y] = 0;
        return true;
    }

    bool same(int x, int y) {
        return root(x) == root(y);
    }
};

struct edge {
    int s, t, weight;
};

bool comp_edge(edge &a, edge &b) {
    return a.weight < b.weight;
}

int main(int argc, const char * argv[]) {

    ios::sync_with_stdio(false);
    cin.tie(0);

    int V, E; cin >> V >> E;

    vector<edge> es(E);
    for (int i = 0; i < E; i++) {
        int s, t, w; cin >> s >> t >> w;
        es[i] = {s, t, w};
    }

    sort(es.begin(), es.end(), comp_edge);

    int ans = 0;
    UnionFind tree(V);
    for (int i = 0; i < E; i++) {
        int s = es[i].s, t = es[i].t, w = es[i].weight;
        if (tree.same(s, t)) continue;
        tree.unite(s, t);
        ans += w;
    }

    cout << ans << endl;

    return 0;
}

