struct UnionFind{
    vector<int> par, siz;
    void init(int n){
        par.resize(n);
        siz.resize(n);
        for(int i = 0; i < n; i++){
            par[i] = i;
            siz[i] = 1;
        }
    }

    int root(int i){
        if(par[i] == i) return i;
        else return par[i] = root(par[i]);
    }

    bool same(int a, int b){
        return root(a) == root(b);
    }

    int size(int i){
        return siz[root(i)];
    }

    void unite(int a, int b){
        a = root(a);
        b = root(b);
        if(a == b) return;
        if(size(a) < size(b)) swap(a, b);
        siz[a] += siz[b];
        par[b] = a;
    }
};
struct edge{
    int from;
    int to;
    int cost;
};
bool comp(const edge &e1, const edge &e2){
    return e1.cost < e2.cost;
}
