int search_root(int *parent, int v)
{

  if(parent[v] != v) 
    {
      parent[v] = search_root(parent, parent[v]);
      return parent[v];
    }
  else
    return v;

}

int unite(int *parent, int v1, int v2)
{
  int r1 = search_root(parent, v1);
  int r2 = search_root(parent, v2);

  if(r1 != r2)
    {
      parent[r1] = r2;
      return true;
    }

  else
    return false;
}

