            for (ll i = 0; i < size; ++i)
            {
                parents.push_back(i);
                ranks.push_back(0);
            }
        }

        ll find(ll x){
            if(parents[x] == x){
                return x;
            }else{
                //???????????????????????£?????´???????????´??\??????????????´????????????
                //pass compression(????????§???)
                return parents[x] = find(parents[x]);
            }
