class UnionFind {
public:
    vector<int> m_parent;
    vector<int> m_rank;

public:
    UnionFind( int n ) {
	Init( n );
    }
    ~UnionFind( ) { 
	m_parent.clear( );
	m_rank.clear( );
    }

    void Init( int n ) {

	m_parent.resize( n );
	m_rank.resize( n );

	for ( int i=0; i<n; ++i ) {
	    m_parent[i] = i;
	    m_rank[i] = 0;
	}
    }

    int Find( int i ) {
	if ( m_parent[i] == i ) return i;
	return m_parent[i] = Find( m_parent[i] );
    }

    void Unite( int i, int j ) {

	i = Find( i );
	j = Find( j );
	if ( i == j ) return;

	if ( m_rank[i] < m_rank[j] ) m_parent[i] = j;
	else {
	    m_parent[j] = i;
	    if ( m_rank[i] == m_rank[j] ) ++m_rank[i];
	}
    }

    bool Same( int i, int j ) { return Find( i ) == Find( j ); }

};

template <typename T>
class Edge {
public:
    int m_b, m_e;
    T m_c;
public:
    Edge() {}
    Edge(int b, int e, const T& c) : m_b(b), m_e(e), m_c(c) {  }
    void Set(int b, int e, const T& c) { m_b = b; m_e = e; m_c = c; }

    bool operator > (const Edge& edge) const { return m_c > edge.m_c; }
    bool operator < (const Edge& edge) const { return m_c < edge.m_c; }
};

//無向グラフ
int Kruskal( int nNode, int nEdge, const vector< Edge<int> >& aEdge ) {

    UnionFind uni( nNode );

    int res = 0;
    for ( int i=0; i<nEdge; ++i ) {

	const Edge< int >& e = aEdge[i];

	if ( !uni.Same( e.m_b, e.m_e ) ) {
	    uni.Unite( e.m_b, e.m_e );
	    res += e.m_c;
	}

    }

    return res;
}

