void solve() {
    ll v, e;
    std::cin >> v >> e;

    std::vector<std::vector<edge>> graph(v);

    auto prim = [&]() {
        ll res = 0;
        vll dist(v, 1e9); dist[0] = 0;
        std::priority_queue<pll, vpll, std::greater<pll>> que;
        que.push({ 0, 0 });

        while (!que.empty()) {
            pll p = que.top(); que.pop();
            ll cost = p.first, v = p.second;
            if (dist[v] < cost) continue;
            res += cost, dist[v] = -1e9;
            for (edge e : graph[v])
                if (chmin(e.cost, dist[e.to]))
                    que.push({ dist[e.to], e.to });
        }

        return res;
    };

    for (ll i = 0; i < e; i++) {
        ll s, t, w; std::cin >> s >> t >> w;
        graph[s].push_back(edge(t, w));
        graph[t].push_back(edge(s, w));
    }

    std::cout << prim() << '\n';
}

