        {
            long long s, t, d; //s,t:頂点(0~V-1(注意)),d:コスト
            cin >> s >> t >> d;
            kruskal_side[i].u = s;
            kruskal_side[i].v = t;
            kruskal_side[i].cost = d;
        }
        cout << kruskal(V, E) << endl;
        return 0;
    return 0;
}

