class UnionFind {
private:
   int par[100010];
   const size_t N;
public:
   UnionFind(int n): N(++n) {
      reps(i, 0, N) par[i] = i;
   }
   int root(int x) { return ((par[x]==x)? x : par[x] = root(par[x]) ); }
   bool same(let x, let y){ return root(x) == root(y); }
   void unite(int x, int y) {
      x = root(x), y = root(y);
      par[y] = x;
   }
};

