struct node {
	bool done;
	vi to, dist;
	int id, from;
	ll d;
	bool operator<(const node & another) const {
		return !(d != another.d ? d < another.d : id < another.id);
	}
};

void prim(vector<node> nodes, int n) {
	priority_queue<node> pq;
	nodes[0].d = 0;
	pq.push(nodes[0]);
	while (pq.size()) {
		node focus = pq.top(); pq.pop();
		if (nodes[focus.id].done) continue;
		Loop(i, focus.to.size()) {
			if (!nodes[focus.to[i]].done && focus.dist[i] < nodes[focus.to[i]].d) {
				nodes[focus.to[i]].d = focus.dist[i];
				nodes[focus.to[i]].from = focus.id;
				pq.push(nodes[focus.to[i]]);
			}
		}
		nodes[focus.id].done = true;
	}
	ll ans = 0;
	Loop(i, n) {
		ans += nodes[i].d;
	}
	cout << ans << endl;
	return;
}

int main() {
	int v, e; cin >> v >> e;
	vector<node> nodes(v);
	Loop(i, v) nodes[i] = { false,{},{}, i, -1, INFLL };
	Loop(i, e) {
		int s, t, d; cin >> s >> t >> d;
		nodes[s].to.push_back(t);
		nodes[s].dist.push_back(d);
		nodes[t].to.push_back(s);
		nodes[t].dist.push_back(d);
	}
	prim(nodes, v);
}

