    int v, e;
    cin >> v >> e;
    auto es = vector<Edge>();
    int s, t, w;
    for(int i = 0; i < e; ++i){
        cin >> s >> t >> w;
        es.push_back(Edge(s, t, w));
    }
    cout << kruskal(v, es) << endl;
}

