int Kruscal(vector<Edge> &edges, int V){
    int res = 0;
    vector<int> connect(V);
    for (int i=0;i<V;i++){
        connect[i] = i;
    }
    sort(edges.begin(), edges.end());
    for(int i=0;i<edges.size();i++){
        Edge e = edges[i];
        if (connect[e.s] != connect[e.t]){
            res += e.weight;
            for (int j=0;j<V;j++){
                if (connect[j] == connect[e.t]){
                    connect[j] = connect[e.s];
                }
            }
        }
    }
    return res;
}

