//互质集合
class DisjointSet {
		vector<int> rank,p;
	public:
		DisjointSet(int n) {
			rank.resize(n,0);
			p.resize(n,0);
			for (int i=0; i<n; i++) {
				makeSet(i);
			}
		}
		void makeSet(int x) {
			p[x] = x;
			rank[x] = 0;
		}

		int findSet(int x) {
			if (x != p[x]) {
				p[x] = findSet(p[x]); //路径压缩
			}
			return p[x];
		}

		bool same(int x,int y) {
			return findSet(x) == findSet(y);
		}

		void link(int x,int y) {
			if (rank[x] > rank[y]) {
				p[y] = x;
			} else {
				p[x] = y;
				if (rank[x] == rank[y]) {
					rank[y]++;
				}
			}
		}
		void unite(int x,int y) {
			link(findSet(x),findSet(y));
		}
};
