const int INF = 1e9;

struct UF {
    int n;
    vector<int> parent;
    vector<int> size;

    UF(int n): n(n) {
        size.assign(n + 1, 1);
        parent.assign(n + 1, 0);
        for (int i = 0; i <= n; i++) {
            parent[i] = i;
        }
    }

    void unite(int u, int v) {
        int i = findRoot(u);
        int j = findRoot(v);
        if (size[i] < size[j]) {
            parent[i] = j;
            size[j] += size[i];
        }
        else {
            parent[j] = i;
            size[i] += size[j];
        }
    }

    bool find(int u, int v) {
        return findRoot(u) == findRoot(v);
    }

    int findRoot(int u) {
        //Can add path compression here
        while (u != parent[u]) {
            u = parent[u];
        }
        return u;
    }

};


struct Node {
