    T root(T x);
    bool unite(T x, T y);
    bool same(T x, T y);
};
#endif

template<typename T>
UnionFind<T>::UnionFind(T n):parents(n),rank(n,0){
        for (T i=0;i<n;i++){
            parents[i] = i;
        }
    }


template<typename T>
T UnionFind<T>::root(T x){
        //再帰的に根をつけなおす//rootを返す
        return parents[x] == x ? x: parents[x] = root(parents[x]);
}

template<typename T>
bool UnionFind<T>::unite(T x, T y){
        if (x==y) return false;
        x = root(x); y = root(y);
        if (x == y) return false;
        if (rank[x] < rank[y]) swap(x, y);
        if (rank[x] == rank[y]) ++rank[x];
        parents[y] = x;
        return true;
}

template<typename T>
bool UnionFind<T>::same(T x, T y){
        if (x==y) return true;
        return root(x) == root(y);
}
