struct UnionFind {
    vector<int> v;
    int groups;
    UnionFind() {}
    UnionFind(int n): groups(n) {
        v.resize(n+1);
        FORR(i, 1, n+1) v[i] = i;
    }
    int find(int p) {
        if (v[p] == p) return p;
        return v[p] = find(v[p]);
