  uf u(V);
  lli res = 0;
  for (lli i = 0; i < es.size(); i++) {
    edge &e = es[i];
    if(not u.same(e.from, e.to)){
      u.unite(e.from, e.to);
      used[i] = true;
      res += e.cost;
    }
  }
  return res;
}

void dfs(vector<vector<edge> > &g, vector<vector<lli> > &mat, vector<bool> &used, int s, int v){
  used[v] = true;
  for (int i = 0; i < g[v].size(); i++) {
    edge &e = g[v][i];
    if(used[e.to] == true)continue;
    mat[s][e.to] = max(mat[s][e.to], e.cost);
    mat[e.to][s] = max(mat[e.to][s], e.cost);
    dfs(g, mat, used, s, e.to);
  }
}


