        return w < e.w;
    }
};


struct DisjointSet{
    vector<int> rank, p;

    DisjointSet(){}
    DisjointSet(int size){
        rank.resize(size, 0);
        p.resize(size, 0);
        rep(i, size) makeSet(i);
    }

    void makeSet(int x){
        rank[x] = 0;
        p[x] = x;
    }

    bool same(int x, int y){
        return findSet(x) == findSet(y);
    }

    int findSet(int x){
        if(p[x] == x) return x;
        p[x] = findSet(p[x]);        
        return p[x];
    }

    void unite(int x, int y){
        link(findSet(x), findSet(y));
    }

    void link(int x, int y){
        if(rank[x] > rank[y]){
            p[y] = x;
        } else {
            p[x] = y;
            if(rank[x] == rank[y]) rank[y]++;
        }
    }
};



