class UnionFindTree {
public:
    UnionFindTree(int n) : ps {vector<int>()}, rs {vector<int>(n, 0)} {
        for(int i = 0; i < n; ++i){
            ps.push_back(i);
        }
    };
    void unite(int x, int y){
        int px = find(x);
        int py = find(y);
        if(px == py){
            return;
        }
        if(rs[x] < rs[y]){
            ps[px] = py;
        } else if(rs[y] < rs[x]){
            ps[py] = px;
        } else {
            ps[px] = py;
            ++rs[py];
        }
    };
    int find(int x){
        return (x == ps[x]) ? x : (ps[x] = find(ps[x]));
    };
private:
    vector<int> ps;
    vector<int> rs;
};
int kruskal(int v, vector<Edge> es){
    auto uft = UnionFindTree(v);
    sort(es.begin(), es.end(), [](Edge a, Edge b){
            return a.w < b.w;
         });
    int n = 0;
    int sum = 0;
    for(auto it = es.begin(); it != es.end(); ++it){
        Edge e = *it;
        if(uft.find(e.s) == uft.find(e.t)){
            continue;
        }
        uft.unite(e.s, e.t);
        sum += e.w;
        ++n;
        if(n == v){
            break;
        }
    }
    return sum;
}

