using namespace std;

class Vertex;

class Adjacent{
  double weight;
  Vertex* vertex;
public:
  Adjacent(double w,Vertex* v):weight(w),vertex(v){};
  bool operator>(const Adjacent &x)const{ return (weight>x.weight);}
  friend class Graph;
  friend class Vertex;
};

class Vertex{
  int value;
  bool flag;
  bool infinity;
  list<Adjacent> adj_list;
  Vertex():value(0),flag(false),infinity(true){}
  friend class Graph;
};

class Graph{
  vector<Vertex*> graph;
public:
  Graph(int size){
    graph.resize(size);
    for(int i=0;i<size;i++){
      graph[i]=new Vertex();
    }
  }

  ~Graph(){
    for(int i=0;i<(int)graph.size();i++){
      delete graph[i];
    }
  }

  void addEdge(int from,int to,int w){
    graph[from]->adj_list.push_back(Adjacent(w,graph[to]));
    graph[to]->adj_list.push_back(Adjacent(w,graph[from]));
  }

  void prim(){
    Vertex *v=graph[0];
    int n=0;
    bool check=false;
    priority_queue<Adjacent,vector<Adjacent>,greater<Adjacent> > pq;
    int min=0;

    while(true){
      v->flag=true;
      n++;
      if(n==(int)graph.size())
	break;
      for(list<Adjacent>::iterator it=v->adj_list.begin();it!=v->adj_list.end();it++){
	Vertex* w=it->vertex;
	if(!w->flag){
	  if(w->infinity || w->value > it->weight){
	    w->infinity=false;
	    w->value = it->weight;
	    pq.push(Adjacent(w->value,w));
	  }
	}
      }

      while(true){
	if(pq.empty()){
	  check=true;
	  break;
	}
	v=pq.top().vertex;
	pq.pop();
	if(!v->flag) break;
      }

      if(check) break;
      min+=v->value;
    }
    cout<<min<<endl;
  }

};

int main(){
  int v=0;
  int e=0;
  cin>>v>>e;
  Graph graph(v);
  for(int i=0;i<e;i++){
    int from,to,w;
    cin>>from>>to>>w;
    graph.addEdge(from,to,w);
  }
  graph.prim();
  return 0;
}

