struct union_find{
    vector<int> par;
    vector<int> rank;
    union_find(int sz){
        par.resize(sz);
        rank.assign(sz,0);
        for(int i = 0;i < sz;++i) par[i]=i;
    }
    int find(int a){
        if(par[a]==a) return a;
        else return par[a] = find(par[a]);
    }
    void unite(int a,int b){
        int root_a,root_b;
        root_a = find(a),root_b = find(b);
        if(rank[root_a]>rank[root_b]){
            par[root_b] = root_a;
        }else if(rank[root_a]<rank[root_b]){
            par[root_a] = root_b;
        }else{
            rank[root_a]++;
            par[root_b] = root_a;
        }
    }
    bool same(int a,int b){return find(a)==find(b);}
};

typedef int Weight;
struct Edge {  
  int src, dst;
  Weight weight;
  Edge(int src, int dst, Weight weight) :
    src(src), dst(dst), weight(weight) { }
};
bool operator < (const Edge &e, const Edge &f) {
  return e.weight != f.weight ? e.weight > f.weight : 
    e.src != f.src ? e.src < f.src : e.dst < f.dst;
}
typedef vector<Edge> Edges;
typedef vector<Edges> Graph;

pair<Weight,Edges> kruskal(const Graph &g) {
  int n = g.size();
  union_find tree(n);
  priority_queue<Edge> Q;
  for(int u=0;u<n;u++){
    for(auto e : g[u]){
      if (u < e.dst) Q.push(e);
    }
  }
  Weight total = 0;
  Edges F;
  while ((int)F.size() < n-1 && !Q.empty()) {
    Edge e = Q.top(); Q.pop();
    if (!tree.same(e.src, e.dst)) {
      F.push_back(e);
      total += e.weight;
      tree.unite(e.src, e.dst);
    }
  }
  return pair<Weight, Edges>(total, F);
}

