// ==========================プリム法==========================
// 実質ダイクストラっぽく見えるやつ。頂点より辺の数の方が多い時はこっち。
// とある頂点を選んで、そこから一番近い頂点を選んでいく。重み付きグラフが必要。
template <typename T>
T prim(WeightedGraph<T> &g) {
  using Pi = pair<T, int>;

  T total = 0;
  vector<bool> used(g.size(), false);
  priority_queue<Pi, vector<Pi>, greater<Pi>> que;  // 小さい順に出てくる
  que.emplace(0, 0);
  while (!que.empty()) {
    auto p = que.top();
    que.pop();
    if (used[p.second]) continue;
    used[p.second] = true;
    total += p.first;
    for (auto &e : g[p.second]) {
      que.emplace(e.cost, e.to);
    }
  }
  return total;
}

