    vector<vector<Pll>> E;

    Prim(int n): n(n), used(n, false), E(n) {};

    void add_edge(int s, int t, ll w) {
        // Undirected link
        E[s].eb(t, w);
        E[t].eb(s, w);
    }

    ll operator()() {
        used.assign(n, false);

        // {cost, node}
        priority_queue<Pll, vector<Pll>, greater<Pll>> q;
        q.emplace(0, 0);

        ll ret = 0;
        while(!q.empty()) {
