class union_find{
  private:
    ll N; //要素数
    vll par; // iの親
    vll rank; // 木の深さ

  public:
    // 要素の初期化
    union_find(ll n){
      N = n;
      par.resize(N); rank.resize(N);
      for(ll i=0;i<N;i++){
        par[i] = i; rank[i] = 0;
      }
    }

    // 木の根を求める
    ll root(ll x){
      if(par[x] == x) return x;
      else{
        ll r = root(par[x]);
        return par[x] = r;
      }
    }

    // 木の併合(rank基準) (wはxとyの重みの差 w = w(y) - w(x))
    void unite(ll x, ll y){
      x = root(x);
      y = root(y);
      if(x == y) return;

      if(rank[x] < rank[y]){
        par[x] = y;
      }
      else{
        par[y] = x;
        if(rank[x] == rank[y]) rank[x]++;
      }
    }

    // xとyが同じ集合に属するかどうか
    bool same(ll x, ll y){
      return root(x) == root(y);
    }
};

struct edge{
  ll from, to, cost;
  bool operator < (const edge &e){
    return cost < e.cost;
  }
};

ll kruskal(ll n, vector<edge> &edges){
  ll res = 0;
  sort(ALL(edges));
  union_find uf(n);

  for(ll i=0;i<edges.size();i++){
    edge e = edges[i];
    if(!uf.same(e.from, e.to)){
      res += e.cost;
      uf.unite(e.from, e.to);
    }
  }
  return res;
}
