class DisjointSet {
    public:
        int parent[N];
        int rank[N];
        DisjointSet() {}
        DisjointSet(int n) {
            for (int i = 0; i < n; i++) {
                makeSet(i);
            }
        }

    void makeSet(int x) {
        parent[x] = x;
        rank[x] = 0;
    }

    int findSet(int x) {
        if (x != parent[x]) {
            return findSet(parent[x]);
        }

        return parent[x];
    }

    void unite(int x, int y) {
        link(findSet(x), findSet(y));
    }

    void link(int x, int y) {
        if (rank[x] < rank[y]) {
            parent[x] = y;
        } else if (rank[y] < rank[x]) {
            parent[y] = x;
        } else {
            parent[x] = y;
            rank[y] = rank[x] + 1;
        }
    }
};

class Edge {
    public:
        int v1, v2, w;
        Edge() {}
        Edge(int v1, int v2, int w): v1(v1), v2(v2), w(w) {}
        bool operator < (const Edge &e) const {
            return w < e.w;
        }
};

vector<Edge> edges;

int main() {
    int v, e;
    cin >> v >> e;
    DisjointSet G = DisjointSet(v);

    int v1, v2, w;
    for (int i = 0; i < e; i++) {
        cin >> v1 >> v2 >> w;
        edges.push_back(Edge(v1, v2, w));
    }

    sort(edges.begin(), edges.end());

    int totalW = 0;
    for (int i = 0; i < edges.size(); i++) {
        Edge edge = edges[i];
        v1 = edge.v1;
        v2 = edge.v2;
        if (G.findSet(v1) != G.findSet(v2)) {
            G.unite(v1, v2);
            totalW += edge.w;
        }
    }

    cout << totalW << endl;

    return 0;

}

