using namespace std;

const int MAX_E = 1e5 + 1;

class KRUSKAL {

   public: 
      int par[MAX_E];
      int UFTrank[MAX_E];
      struct edge { int u, v, cost; };
      edge es[MAX_E * 2];
      int E, V;

      bool comp(const edge& e1, const edge& e2) {
         return e1.cost < e2.cost;
      }

      void init(int e, int v) {
         E = e;
         V = v;
         // sort(es, es + E, comp);
         sort(es, es + E, [this] (edge& e1, edge& e2) { return  comp(e1, e2); } );
         for (int i = 0; i < V; i++) {
            par[i] = i;
            UFTrank[i] = 0;
         }
      }

      int find(int x) {
         if (par[x] == x) {
            return x;
         } else {
            return par[x] = find(par[x]);
         }
      }

      void unite(int x, int y) {
         x = find(x);
         y = find(y);
         if (x == y) return;

         if (UFTrank[x] < UFTrank[y]) {
            par[x] = y;
         } else {
            par[y] = x;
            if (UFTrank[x] == UFTrank[y]) UFTrank[x]++;
         }
      }

      bool same(int x, int y) {
         return find(x) == find(y);
      }       

      int getmin() {
         int ans = 0;
         for (int i = 0; i < E; i++) {
            edge e = es[i];
            if (!same(e.u, e.v)) {
               unite(e.u, e.v);
               ans += e.cost;
            }
         }
         return ans;
      }
};



int main() {
   int V, E;
   cin >> V >> E;
   KRUSKAL mst;
   int s, t, w;
   for (int i = 0; i < E; i++) {
      cin >> s >> t >> w;
      mst.es[i].u = s;
      mst.es[i].v = t;
      mst.es[i].cost = w;
   }
   mst.init(E, V);
   int ans = mst.getmin();
   cout << ans << endl;
   return 0;
}

