//{{{ Edges kruskal(g)
Edges kruskal(const Graph& g){
  const int V = g.size();
  int E = 0;
  for (const auto& v : g) E += v.size();
  Edges es;
  es.reserve(E);
  for (const auto& v : g){
    for (const auto& e : v){
      es.emplace_back(e);
    }
  }
  sort(es);
  revs(es);
  UF uf(V);
  Edges result;
  for (const auto& e : es){
    if (uf.same(e.from, e.to)) continue;
    uf.merge(e.from, e.to);
    result.emplace_back(e);
  }
  return result;
}
//}}}

