int prim() {
	rep(i, 0, V) {
		mincost[i] = INF;
		used[i] = false;
	}

	mincost[0] = 0;
	int res = 0;
	while(true) {
		int v = -1;
		rep(u, 0, V) {
			if(!used[u] && (v == -1 || mincost[u] < mincost[v])) v = u;
		}

		if(v == -1) break;
		used[v] = true;
		res += mincost[v];
		rep(u, 0, V) mincost[u] = min(mincost[u], cost[v][u]);
	}
	return res;
}

int kruskall() {
	sort(es, es + E, comp);
	uft.init(V);
	int res = 0;
	rep(i, 0, E) {
		edge e = es[i];
		if(!uft.same(e.u, e.v)) {
			uft.unite(e.u, e.v);
			res += e.cost;
		}
	}
	return res;
}


