class UnionFind{

    vector<int> par;
    int groupcount;

public:
// UnionFind uf(n)でn要素のUF木uf
    UnionFind(int n=0){
        init(n);
    }

    //n要素で初期化
    void init(int n=0){
        par.resize(n);
        fill(par.begin(),par.end(),-1);
        groupcount=n;
        return;
    }

    //xが属する集合の根を求める
    int root(int x){
        if(par[x]<0){
            return x;
        }
        return par[x]=root(par[x]);
    }

    //xとyが同じ集合に属するかどうか調べる
    bool same(int x,int y){
        return root(x)==root(y);
    }

    //xが属する集合の大きさを求める
    int size(int x){                
        return -par[root(x)];
    }

    //xが属する集合とyが属する集合を繋ぐ
    //既に繋がっていたらfalseが返る
    bool unite(int x,int y){
        x=root(x);
        y=root(y);
        if(x==y){
            return false;
        }
        if(par[y]<par[x]){ 
            swap(x,y);
        }
        par[x]+=par[y];     
        par[y]=x;
        --groupcount;
        return true;        
    }

    //UF内にある集合の個数を求める
    int size(void){
        return groupcount;
    }
};

class edge{
    public:
    int source,target,cost;
    edge(int source=0,int target=0,int cost=0):
    source(source),target(target),cost(cost) {}
    bool operator < (const edge &e) const{
        return cost < e.cost;
    }
};

int kruskal(int n,vector<edge> edges){
    int totalcost=0;
    sort(edges.begin(),edges.end());//コストが小さい順に辺をソートする

    UnionFind uf(n);              //unionfindの初期化

    for(auto e:edges){
        if(!uf.same(e.source,e.target)){
            //MST.push_back(e);
            totalcost+=e.cost;
            uf.unite(e.source,e.target);
        }
    }
    return totalcost;
}

