using namespace std;

ll par[10000], rk[10000];

ll bitFind(ll x){
  if(x == par[x])
    return x;
  return par[x] = bitFind(par[x]);
}

ll bitSame(ll x, ll y){
  return bitFind(x) == bitFind(y);
}

void bitMerge(ll x, ll y){
  x = bitFind(x);
  y = bitFind(y);
  if(rk[x] < rk[y]){
    par[x] = y;
  }else if(rk[x] > rk[y]){
    par[y] = x;
  }else{
    par[x] = y;
    rk[y]++;
