long long prim(const vector<vert>& verts) {
    priority_queue<pair<int, int>, vector<pair<int, int>>, greater<>> pq;
    set<int> s;
    long long res = 0;
    pq.push(make_pair(0, 0));
    while (!pq.empty() && s.size() < verts.size()) {
        auto info = pq.top(); pq.pop();
        int cost = info.first;
        int idx = info.second;
        if (s.find(idx) != s.end()) continue;
