int V;
vector<edge> G[MAX_V];
int d[MAX_V];

int prim(){
	int res = 0;
	priority_queue<P, vector<P>, greater<P> > que;
	fill(d, d + V, INF);
	for(int s = 0;s < V; ++s) {
		if(d[s] != INF) continue;
		assert(res == 0);
		d[s] = 0;
		que.push(P(0, s));
		while(!que.empty()){
			P p = que.top(); que.pop();
			int v = p.second;
			if(d[v] < p.first) continue;
			res += p.first;
			for(int i=0;i<G[v].size();i++){
				edge e = G[v][i];
				if(d[e.to] > e.cost){
					d[e.to] = e.cost;
					que.push(P(e.cost, e.to));
				}
			}
		}
	}
	return res;
}

