using TUP = tuple<int, int, int>;

class UnionFind {
private:
	// parents[i] >= 0 なら i の親
	// parents[i] < 0 で、根。abs(parents[i])がその木に属する頂点数
	vector<int> parents;
	int n_root;

public:
	UnionFind();
	UnionFind(int n) {
		parents.assign(n, -1);
		n_root = n;
	}
	~UnionFind() {
		parents.clear();
	};

	int find(int x) {
		if (parents[x] < 0) {
			return x;
		} else {
			return parents[x] = find(parents[x]);
		}
	}

	void unite(int x, int y) {
		x = find(x);
		y = find(y);

		if (x == y) {
			return;
		}

		if (size(x) < size(y)) {
			swap(x, y);
		}

		parents[x] += parents[y];
		parents[y] = x;
		n_root--;
		return ;
	}

	bool same(int x, int y) {
		return find(x) == find(y);
	}

	// xが属する集団のサイズ
	int size(int x) {
		return -parents[find(x)];
	}

	// いくつの集団があるか
	int get_n_root() {
		return n_root;
	}
};

int main() {
	int nv, ne;
	cin >> nv >> ne;

	vector<vector<PII>> connect(nv);

	priority_queue<TUP, vector<TUP>, greater<TUP>> que;

	int s, t, w;
	for (int i = 0; i < ne; i++) {
		cin >> s >> t >> w;
		que.emplace(w, s, t);
	}

	UnionFind uf(nv);
	int ans = 0;
	while (!que.empty() || uf.get_n_root() > 1) {
		tie(w, s, t) = que.top();
		que.pop();

		if (uf.same(s, t)) {
			continue;
		}

		uf.unite(s, t);
		ans += w;
	}
	cout << ans << endl;
	return 0;
}

