typedef uint32_t u32;

template<u32 N_>
class UnionFindTree {
private:
  u32 par[N_];
  u32 rank[N_];
public:
  UnionFindTree(u32 n) {
    assert(n < N_);
    for(u32 i = 0; i < n; ++i) {
      par[i] = i;
      rank[i] = 0;
    }
    return;
  }
  int find(u32 x) {
    if( par[x] == x ) return x;
    return par[x] = find(par[x]);
  }
  void unite(u32 x, u32 y) {
    x = find(x);
    y = find(y);
    if( x == y ) return;
    if( rank[x] < rank[y] ) {
      par[x] = y;
      return;
    }
    par[y] = x;
    if( rank[x] == rank[y] ) rank[x] += 1;
    return;
  }  
};

template<typename Tw>
class Edge {
private:
  u32 begin_, end_;
  Tw  weight_;
public:
  Edge() {}
  Edge(u32 begin, u32 end, Tw weight) : begin_(begin), end_(end), weight_(weight) {}
  const u32& begin()  const { return begin_;  }
  const u32& end()    const { return end_;    }
  const u32& weight() const { return weight_; }
  static bool comp_be(const Edge<Tw>& left, const Edge<Tw>& right) {
    if( left.begin() != right.begin() ) return left.begin() < right.begin();
    if( left.end()   != right.end()   ) return left.end()   < right.end();
    return false;
  }
  static bool comp_w(const Edge<Tw>& left, const Edge<Tw>& right) {
    return left.weight() < right.weight();
  }
};

