  sort(es.begin(), es.end());
  init_union_find(V);
  int min_cost = 0;
  REP(i, V){
    if(!same(es[i].f, es[i].t)){
      min_cost += es[i].c;
      merge(es[i].f, es[i].t);
    }
  }
  return min_cost;
}

