#include<bits/stdc++.h>
using namespace std;
typedef long long ll;

class UnionFind{
    public:
    //親の番号を格納する。親だった場合は-(その集合のサイズ)
    vector<int> parent;

    //-1で初期化
    //最初はすべてバラバラ
    UnionFind(int N){
        parent = vector<int>(N,-1);
    }

    //Aがどのグループに属しているか(Aの根)を調べる
    int root(int A){
        if(parent[A] < 0) return A;
        return parent[A]=root(parent[A]);
    }

    //自分のいるグループの頂点数を調べる
    int size(int A){
        return -parent[root(A)];
    }

    //AとBをくっつける
    bool connect(int A, int B) {
    //AとBを直接つなぐのではなく、root(A)にroot(B)をくっつける
        A = root(A);
        B = root(B);
        //既にくっついているからくっつけない
        if(A == B) return false; 

        //大きいほう(A)に小さいほう(B)をくっつける
        //大証が逆ならひっくり返す
        if(size(A) < size(B)) swap(A,B);

        //Aのサイズを更新する
        parent[A] += parent[B];
        //Bの親をAに変更する
        parent[B] = A;

        return true;
    }

    //AとBが同じグループならtrueを返す
    bool same(int A, int B){
        return root(A)==root(B);
    } 
};

struct edge{
    ll from;
    ll to;
    ll cost;

    edge(ll a, ll b, ll c){
        from = a;
        to = b;
        cost = c;
    }
    bool operator < (const edge &another) const{
        return cost < another.cost;
    }
};



int main(){
    ios::sync_with_stdio(false);
	cin.tie(0);

    ll n,m;
    cin>>n>>m;
    vector<edge> v;
    for(int i=0;i<m;i++){
        ll f,t,c;
        cin>>f>>t>>c;

        v.push_back(edge(f,t,c));
    }
    sort(v.begin(), v.end());

    UnionFind uni(n);
    ll ans=0;
    for(int i=0;i<m;i++){
        if(!uni.same(v[i].from, v[i].to)){
            ans+=v[i].cost;
            uni.connect(v[i].to, v[i].from);
        }
    }
