struct UnionFind {
  vector<int> par; // par[i]:iの親の番号 (例) par[3] = 2 : 3の親が2
  vector<int>
      sizes; // sizes[i]:根iの木に含まれるデータの数、根でない場合は無意味な値となる

  UnionFind(int N) : par(N), sizes(N, 1) { //最初は全てが根であるとして初期化
    for(int i = 0; i < N; i++)
      par[i] = i;
  }

  int root(int x) { // データxが属する木の根を再帰で得る：root(x) = {xの木の根}
    if(par[x] == x) return x;
    return par[x] = root(par[x]);
  }

  void unite(int x, int y) { // xとyの木を併合
    int rx = root(x);        // xの根をrx
    int ry = root(y);        // yの根をry
    if(rx == ry) return; // xとyの根が同じ(=同じ木にある)時はそのまま
    if(sizes[rx] < sizes[ry]) swap(rx, ry); // xの木 > yの木にする
    par[ry] =
        rx; // xとyの根が同じでない(=同じ木にない)時：yの根ryをxの根rxにつける
    sizes[rx] += sizes[ry];
    sizes[ry] = 0; // 一応0にしておく
  }

  bool same(int x, int y) { // 2つのデータx, yが属する木が同じならtrueを返す
    int rx = root(x);
    int ry = root(y);
    return rx == ry;
  }

  int size(int x) { // データxが含まれる木の大きさを返す
    return sizes[root(x)];
  }
};

struct Edge {
  ll from, to, cost;
};

