class unionfind {
private:
	int* parent;
public:
	unionfind(int nodes) {
		parent = new int[nodes];
		for(int i = 0;i < nodes;i++) parent[i] = -1;
	}
	~unionfind() {
		delete parent;
	}
	int root(int n) {
		if(parent[n] == -1) return n;
		int res = root(parent[n]);
		parent[n] = res;
		return res;
	}
	bool same(int a,int b) {
		return root(a) == root(b);
	}
	void merge(int a,int b) {
		parent[root(a)] = root(b);
	}
};

