int kruskal (int N, vector<Edge> edges){
    int totalCost = 0;
    sort(edges.begin(), edges.end());
    DisjointSet dset = DisjointSet(N+1);

    for (int i=0;i<N;i++){
        dset.makeSet(i);
    }
    int source, target;
    for (int i=0;i<edges.size();i++){
        Edge e = edges[i];
