//union-findのクラス
class unionfind {
    vector<int> par, rank, size_;//速度ではなくメモリ効率を考えるならrankのかわりにsizeを使う
public:
    unionfind(int n) :par(n), rank(n), size_(n, 1) {
        iota(par.begin(),par.end(), 0);
    }
    int find(int x) {
        if (par[x] == x)return x;
        return par[x] = find(par[x]);
    }
    void unite(int x, int y) {
        x = find(x), y = find(y);
        if (x == y)return;
        if (rank[x] < rank[y])swap(x, y);
        par[y] = x;
        size_[x] += size_[y];
        if (rank[x] == rank[y])rank[x]++;
    }
    bool same(int x, int y) {
        return find(x) == find(y);
    }
    int size(int x) {
        return size_[find(x)];
    }
};


template<class T>
auto Kruskal(const vector<vector<pair<T,T>>>&edge){
  T res = 0;
  using tp = tuple<T,T,T>;
  vector<tp>g;
  for(T i = 0; i < edge.size(); ++i){
    for(auto p : edge[i]){
      T j,cost;
      tie(j,cost) = p;
      g.emplace_back(cost,i,j);
    }
  }
  sort(g.begin(),g.end());
  auto uf =  unionfind(edge.size() + 1);
  for(auto tup : g){
    T cost,s,t;
    tie(cost,s,t) = tup;
    if(uf.same(s,t))continue;
    uf.unite(s,t);
    res += cost;
  }
  return res;
}
