class UnionFind {
public:

	vector<int> numbers;
	vector<int> rank;

	UnionFind(int n) {

		for (int i = 0; i < n; ++i) {
			numbers.push_back(i);
			rank.push_back(0);
		}

	}

	int FindParent(int n) {

		if (numbers[n] == n)
			return n;

		return numbers[n] = FindParent(numbers[n]);

	}

	bool isSame(int a, int b) {

		return FindParent(a) == FindParent(b);

	}

	void Union(int a, int b) {

		int a_parent = FindParent(a);
		int b_parent = FindParent(b);

		if (rank[a_parent] < rank[b_parent]) {
			swap(a_parent, b_parent);
		}
		else if (rank[a_parent] == rank[b_parent]) {
			rank[a_parent]++;
		}

		numbers[b_parent] = a_parent;
	}

};

