class DSU {
  private: vector<int> p, rank;
  public:
    DSU(int n) {
      p = vector<int>(n, -1);
      rank = vector<int>(n, 0);
    }
    int root(int x) {
      if (p[x] == -1) {
        return x;
      }
      return (p[x] = root(p[x]));
    }
    bool sameSet(int x, int y) {
      return root(x) == root(y);
    }
    void connect(int x, int y) {
      x = root(x);
      y = root(y);
      if (x != y) {
        if (rank[x] > rank[y]) {
          p[y] = x;
        } else {
          p[x] = y;
          rank[y] += (rank[x] == rank[y]);
        }
      }
    }
};

