	unionFind(int n) {
		par = vector<int>(n);
		rank = vector<int>(n);
		rep(i,0,n){
			par[i] = i;
			rank[i] = 1;
		}
	}

	int find(int x){
		if(par[x] == x){
			return x;
		}
		return par[x] = find(par[x]);
	}

	bool same(int x, int y){
		return find(x) == find(y);
	}

