};

vector<Edge> kruskal(int n, vector<Edge>& edges) {
    sort(edges.begin(), edges.end());

    DisjointSet<int> dset(n + 1);
    vector<Edge> K;

    for (auto e : edges) {
        // Append e only if e connects different parts of the graph.
        if (dset.find_set(e.s) != dset.find_set(e.t)) {
            dset.unite(e.s, e.t);
            K.push_back(e);
        }
    }
    return K;
}

