class UnionFind {
public:
    vector<ll> par;
    void init(ll n) {
        rep(i, 0, n) {
            //par[i] == iのとき、iの親はiとなるから初期化では全て根であるとする。
            par.push_back(i);
        }
    }

    ll root(ll x) {
        if (par[x] == x) {
            return x;
        } else {
            return par[x] = root(par[x]);
        }
    }

    // これは併合するために使う
    bool unite(ll x, ll y) {
        x = root(x);
        y = root(y);
        // 併合済ならばfalse
        if (x == y) return false;

        par[y] = x;
        return true;
    }

    bool isSame(ll x, ll y) {
        return root(x) == root(y);
    }
};
int main() {
    int V, E;;
    cin >> V >> E;
    UnionFind T;
    vector<tuple<int, int, int> > edges;
    rep(i, 0, E) {
        int s, t, w;
        cin >> s >> t >> w;
        tuple<int, int, int> tp = make_tuple(w, s, t); 
        edges.push_back(tp);
    }

    sort(edges.begin(), edges.end());
    T.init(V);
    int res = 0;
    rep(i, 0, edges.size()) {
        int s = get<1>(edges[i]);
        int t = get<2>(edges[i]);
        if (!T.isSame(s, t)) {
            res += get<0>(edges[i]);
            T.unite(s, t);
        }
    }
    cout << res << endl;
    return 0;
}

