struct UnionFind{
    int root[10010];
    int w[10010];

    UnionFind(){
        for(int i = 0; i < 10010; i++){
            root[i] = i;
            w[i] = 0;
        }
    }

    int getRoot(int n){
        if(root[n] == n) return n;
        else return (root[n] = getRoot(root[n]));
    }

    void merge(int x, int y, int aw){
        if(w[x] < w[y]) swap(x,y);
        int ry = getRoot(y);
        int rx = getRoot(x);
        root[ry] = rx;
        w[rx] += w[ry];
        w[rx] += aw;
    }

    bool isSame(int x, int y){
        if(getRoot(x) == getRoot(y)){
            return true;
        }
        return false;
    }

    int getWeight(int n){
        int rn = getRoot(n);
        return w[rn];
    }
};

