using namespace std;
typedef map<int, vector<int>> Graph;
typedef map<int, map<int, int>> WGraph;
typedef pair<int, int> Edge;
typedef pair<int, int> PII;
typedef pair<int, Edge> PIE;

vector<Edge> prim(WGraph &g)
{
    vector<Edge> ret;
    map<int, bool> mp;
    priority_queue<PIE, vector<PIE>, greater<PIE>> pq;
    mp[0] = true;
    for (auto x : g[0])
    {
        pq.push({x.second, {0, x.first}});
    }
    while (!pq.empty())
    {
        auto t = pq.top();
        auto next = t.second.second;
        pq.pop();
        if (mp[next] == true)
        {
            continue;
        }
        mp[next] = true;
        ret.push_back(t.second);
        for (auto x : g[next])
        {
            pq.push({x.second, {next, x.first}});
        }
    }
    return ret;
}

