class Union_Find {
private:
    std::vector<int> par;
    std::vector<int> rank;

public:
    Union_Find(int n) { // ?????????: O(n)
	par = rank = std::vector<int>(n);
	for(int i=0; i<n; i++) {
	    par[i]  = i;
	    rank[0] = 0;
	}
    }

    int root(int x) { // ??¨??????????±???????: O(?±(n)) 
	if(par[x] == x) return x;
	return par[x] = root(par[x]); // ??????????????????????????????????????????
    }

    void unite(int x, int y) { // x,y????????????????????????: O(?±(n)) 
	x = root(x); y = root(y);
	if( x == y ) return;

	if( rank[x] < rank[y] ) par[x] = y;
	else {
	    par[y] = x;
	    if( rank[x] == rank[y] ) rank[x]++;
	}
    }

    bool same(int x, int y) { //x,y??????????????????????????????????????????: O(?±(n)) 
	return root(x) == root(y);
    }
};


struct Edge {
    int s;
    int t;
    int w;
    bool operator < (const Edge& tgt) const {
	return w > tgt.w;
    }
};
inline int Prim(const vector<vector<Edge>>& g) {
    const int V = g.size();
    priority_queue<Edge> pq;
    set<int> used;
    used.insert(0);
    for(auto& e : g[0]) {
	pq.push( e );
    }
    int ans = 0;
    while( used.size() != V and pq.size()>0 ) {
	auto e = pq.top(); pq.pop();
	if( used.find(e.s) != used.end() and  used.find(e.t) != used.end() ) continue;
	ans += e.w;
	used.insert(e.s);
	used.insert(e.t);
	for(auto& ne : g[e.s])
	    pq.push(ne);
	for(auto& ne : g[e.t])
	    pq.push(ne);
    }
    return ans;
}

inline int Kruskal(const vector<vector<Edge>>& g){
    const int V = g.size();
    vector<Edge> edges;
    for(auto& v : g) {
	for(auto& e : v) {
	    edges.push_back(e);
	}
    }
    sort(edges.begin(), edges.end());
    reverse(edges.begin(), edges.end());

    Union_Find uf(V);
    int ans = 0;
    for(auto& e : edges) {
	if( uf.same(e.s,e.t) ) continue;
	ans += e.w;
	uf.unite(e.s,e.t);
    }
    return ans;
}


