class DisjointSet {
public:
    vector<int> rank, p;

    DisjointSet() {};
    DisjointSet(int s) {
        rank.resize(s, 0);
        p.resize(s, 0);
        for (int i = 0; i < s; i++) makeSet(i);
    }

    void makeSet(int x) {
        p[x] = x;
        rank[x] = 0;
    }

    bool same(int x, int y) {
        return findSet(x) == findSet(y);
    }

    void unite(int x, int y) {
        link(findSet(x), findSet(y));
    }

    void link(int x, int y) {
        if (rank[x] > rank[y]) {
            p[y] = x;
        } else {
            p[x] = y;
            if (rank[x] == rank[y]) {
                rank[y]++;
            }
        }
    }

    int findSet(int x) {
        while (x != p[x]) {
            x = p[x];
        }
        return x;
    }
};

class Edge {
public:
    int source, target, cost;

    Edge(int source = 0, int target = 0, int cost = 0):
        source(source), target(target), cost(cost) {}

    bool operator < (const Edge &e) const {
        return cost < e.cost;
    }
};

vector<Edge> edges;

int kruskal(int V) {
    int totalCost = 0;
    sort(edges.begin(), edges.end());
    DisjointSet ds = DisjointSet(V);

    for (auto i = 0; i < edges.size(); i++) {
        Edge e = edges[i];
        if (!ds.same(e.source, e.target)) {
            totalCost += e.cost;
            ds.unite(e.source, e.target);
        }
    }
    return totalCost;
}

