    UnionFind uf = UnionFind(V);
    int res = 0;
    for(int i = 0; i < E; i++){
        Edge e = edges[i];
        if(!uf.isSame(e.u, e.v)){
            uf.unite(e.u, e.v);
            res += e.cost;
        }
    }
    return res;
}

