        return d[x] = find(d[x]); // メモ化再帰
    }

    bool unite(int x, int y) {
        x = find(x); 
        y = find(y);
        if(x == y){
            return false;
        }
        if(size(x) < size(y)){
            swap(x,y);
        } 
        d[x] += d[y];
        d[y] = x;
        return true;
    }

    bool same(int x, int y) { 
        return find(x) == find(y);
    }

    int size(int x) { 
        return -d[find(x)];
    }
};

