struct UnionFindTree {
  vector<int> R;
  UnionFindTree(int N) : R(N) {
    for (int i = 0; i < N; ++i) R[i] = i;
  }

  bool same(int s, int t) { return (root(s) == root(t)); }

  int root(int x) {
    if (x == R[x]) return x;
    return R[x] = root(R[x]);
  }

  void unite(int x, int y) {
    int rx = root(x);
    int ry = root(y);
    if (rx == ry) return;
    R[ry] = rx;
  }
};

