class UnionFind {
private:
  vector< int > rank, p;
  void link(int x, int y) {
    if(rank[x] > rank[y]) swap( x, y);
    p[x] = y;
    if(rank[x] == rank[y]) rank[y]++;
  }
public:
  UnionFind(int n) : rank(n), p(n) {
    for(int i = 0; i < n; i++) p[i] = i, rank[i] = 0;
  }
  void Union(int x, int y) {
    if(Find(x) != Find(y)) link( Find(x), Find(y));
  }
  int Find(int x) {
    return(x != p[x] ? p[x] = Find(p[x]) : p[x]);
  }
  bool Same(int x, int y) {
    return(Find(x) == Find(y));
  }
};
template< class T >
class SGraph{
protected:
  struct edge {
    int u, v;
    T cost;
    bool operator<(const edge& hoge) const {
      return cost < hoge.cost;
    }
  };
  typedef vector< edge > Edges;
  Edges edges;
public:
  SGraph< T >(){};
  void add_edge( int u, int v, T cost) {
    edges.push_back((edge){ u, v, cost});
  }
};

template< class T >
class MinimumSpanningTree : public UnionFind, public SGraph< T >{
public:
  MinimumSpanningTree(int n):SGraph< T >(), UnionFind(n){};
  T run(){
    sort( SGraph< T >::edges.begin(), SGraph< T >::edges.end());
    T ret = 0;
    ForEach(it, SGraph< T >::edges){
      if(!Same( it -> u, it -> v)){
        Union( it -> u, it -> v);
        ret += it -> cost;
      }
    }
    return ret;
  }
};
