ll gcd(ll a, ll b)
{
	return b ? gcd(b, a % b) : a;
}

ll my_exp(ll a, ll b, ll MOD = numeric_limits<ll>::max())
{
	a %= MOD;
	if (b == 0)
	{
		return 1;
	}
	else
	{
		return ((b % 2 == 1 ? a : 1) * my_exp(a * a, b / 2, MOD)) % MOD;
	}
}

bool is_prime(ll n)	// O(sqrt(n)) implementation check for 0 and 1 separately
{
	if (n != 2 && n % 2 == 0)
	{
		return false;
	}
	else
	{
		for (int i = 3; (i*i) <= n; i += 2)
		{
			if (n%i == 0)
				return false;
		}
		return true;
	}
}

// Program classes and structs
class graph
{
public:
	ll n, m;
	vector<list<pll>> adj;
	vb visited;
	vll parent;
	vll dij;
	void add_edge(ll node1, ll node2, ll weight = 1)
	{
		adj[node1].push_back(mp(node2, weight));
		adj[node2].push_back(mp(node1, weight));
		++m;
	}
	ll mst_prim()
	{
		visited.clear(); visited = vb(n, false);
		map<ll, pll> pool;
		visited[0] = true;
		tr(adj[0], it)	if (!visited[it->first]) pool[it->second] = mp(0, it->first);
		list<pair<pll, ll>> edges;
		while (!pool.empty())
		{
			pair<ll, pll> curr = *pool.begin(); pool.erase(pool.begin());
			if (visited[curr.second.second]) continue; else visited[curr.second.second] = true;
			edges.push_back(mp(curr.second, curr.first));
			tr(adj[curr.second.second], it)	if (!visited[it->first]) pool[it->second] = mp(curr.second.second, it->first);
		}
		adj.clear(); adj = vector<list<pll>>(n);
		ll ret = 0; m = 0;
		tr(edges, it)
		{
			add_edge(it->first.first, it->first.second, it->second); ++m;
			ret += it->second;
		}
		return ret;
	}
	graph(ll a)
	{
		n = a;
		m = 0;
		adj = vector<list<pll>>(n);
		visited = vb(n, false);
		dij = vll(n, numeric_limits<ll>::max());
		parent = vll(n, -1);
	}
};

