template <class T>
vector<T> dijkstra(vector<vector<tuple<int, T>>> g, int start) {
    T inf = numeric_limits<T>::max() / 3;
    vector<T> dist((int)g.size(), inf);
    priority_queue<tuple<T, int>, vector<tuple<T, int>>, greater<tuple<T, int>>>
        pri;
    pri.push(make_tuple(0, start));
    while (pri.size() != 0) {
        T d;
        int idx;
        tie(d, idx) = pri.top();
        pri.pop();
        if (dist[idx] == inf) {
            dist[idx] = d;
            for (tuple<int, T> temp : g[idx]) {
                int j;
                T d2;
                tie(j, d2) = temp;
                if (dist[j] == inf) { pri.push(make_tuple(d + d2, j)); }
            }
        }
    }
    return dist;
}

struct unionfind {  // size:要素数,tree：unionfind木
    int n;
    vector<int> tree_root;
    vector<int> tree_depth;
    unionfind(int temp) {
        n = temp;
        tree_root.assign(n, 0);
        tree_depth.assign(n, 1);
        for (int i = 0; i < n; i++) { tree_root[i] = i; }
    }

    // rootを探す
    int root(int index) {
        vector<int> temp_list(0);
        int temp = tree_root[index];
        while (index != temp) {
            temp_list.push_back(index);
            index = temp;
            temp = tree_root[index];
        }
        for (int i : temp_list) { tree_root[i] = index; }
        return index;
    }
    //結合
    void unite(int index1, int index2) {
        int r1 = root(index1);
        int r2 = root(index2);
        if (r1 != r2) {
            int d1 = tree_depth[r1];
            int d2 = tree_depth[r2];
            if (d1 <= d2) {
                tree_root[r1] = r2;
                tree_depth[r2] = max(d1 + 1, d2);
            } else {
                tree_root[r2] = r1;
                tree_depth[r1] = max(d2 + 1, d1);
            }
        }
    }
    //同じか判定
    bool same(int index1, int index2) {
        int r1 = root(index1);
        int r2 = root(index2);
        return r1 == r2;
    }
    //連結成分の個数
    int component() {
        set<int> s;
        for (int i : tree_root) { s.insert(i); }
        return (int)s.size();
    }
};

// unionfindも呼び出す必要あり
// n:サイズ、abc:a→bで重みcの辺（0-indexed）
template <class T>
auto Kruskal(int n, vector<tuple<int, int, T>> abc) {
    unionfind uf(n);
    vector<tuple<int, int>> ret(0);
    int weight_sum = 0;
    sort(abc.begin(), abc.end(),
         [](const auto& x, const auto& y) { return get<2>(x) < get<2>(y); });
    for (tuple<int, int, T> temp : abc) {
        int a, b;
        T c;
        tie(a, b, c) = temp;
        if (uf.same(a, b) == false) {
            ret.push_back(make_tuple(a, b));
            weight_sum += c;
            uf.unite(a, b);
        }
    }
    // return ret; // 最小全域木自体を出力する
    return weight_sum;
}

