class union_find {
  std::vector<intmax_t> tree;

public:
  union_find(size_t n): tree(n, -1) {}

  size_t find(size_t v) {
    if (tree[v] < 0)
      return v;

    return (tree[v] = find(tree[v]));
  }

  bool unite(size_t u, size_t v) {
    u = find(u);
    v = find(v);
    if (u == v)
      return false;

    if (-tree[u] >= -tree[v])
      std::swap(u, v);

    tree[v] += tree[u];
    tree[u] = v;
    return true;
  }

  bool connected(size_t u, size_t v) {
    return (find(u) == find(v));
  }

  size_t size(size_t v) {
    return -tree[find(v)];
  }
};

template <class Weight>
struct edge {
  using value_type = Weight;
  size_t src, dst;
  value_type cost;

  edge(size_t src, size_t dst, value_type cost=1):
    src(src), dst(dst), cost(cost)
  {}

  bool operator <(const edge<value_type> &rhs) const {
    if (cost != rhs.cost) return cost < rhs.cost;
    if (src != rhs.src) return src < rhs.src;
    return dst < rhs.dst;
  }
};

template <class Weight>
struct graph: public std::vector<std::vector<edge<Weight>>> {
  using value_type = Weight;
  graph(size_t n): std::vector<std::vector<edge<value_type>>>(n) {}

  void connect_with(size_t src, size_t dst, value_type cost=1) {
    (*this)[src].emplace_back(src, dst, cost);
    (*this)[dst].emplace_back(dst, src, cost);
  }
};

template <class Tp>
constexpr Tp inf = Tp(1) << (8*sizeof(Tp)-3);

template <class Weight>
Weight min_spanning_tree(const graph<Weight>& g) {
  // based on Boruvka algorithm
  size_t v = g.size();

  intmax_t res = 0;
  union_find uf(v);
  while (uf.size(0) < v) {
    std::vector<std::pair<size_t, size_t>> min(v, {-1, -1});
    for (size_t i = 0; i < v; ++i)
      for (size_t j = 0; j < g[i].size(); ++j) {
        const auto& e = g[i][j];
        if (uf.connected(e.src, e.dst)) continue;
        size_t s = uf.find(e.src);
        size_t u0, u1;
        std::tie(u0, u1) = min[s];
        if (u0+1 == 0 || g[u0][u1].cost > e.cost) min[s] = {i, j};
      }

    for (size_t i = 0; i < v; ++i) {
      size_t u0, u1;
      std::tie(u0, u1) = min[i];
      if (u0+1 == 0) continue;
      const auto& e = g[u0][u1];
      if (uf.connected(e.src, e.dst)) continue;
      uf.unite(e.src, e.dst);
      res += e.cost;
    }
  }
  return res;
}

