typedef vector<vector<Edge> > Graph;

int prim(Graph& G){

	  priority_queue<Edge, vector<Edge>, greater<Edge> > q;
	  vector<int> used(G.size(),0);
	  int num_used=0, ans=0;

	  for(Edge e : G[0])	q.push(e);
	  used[0] = 1; num_used++;

	  while(q.size()){
			Edge e = q.top(); q.pop();
			if(used[e.t] == 1) continue;
			used[e.t] = 1; num_used++; ans += e.w;
			if(num_used == G.size()) break;
			for(Edge ne : G[e.t])
				  if(used[ne.t] != 1)
						q.push(ne);
	  }
	  return ans;
}


