template<typename T>
T kruskal(Edges<T> &edges, int V){
    sort(edges.begin(), edges.end(), [](const edge<T> &a, const edge<T> &b){return a.cost < b.cost;});
    UnionFindTree tree(V);

    T ret = 0;
    for(auto &e: edges){
        if(not tree.isSame(e.src, e.to)){
            ret += e.cost;
            tree.unite(e.src, e.to);
        }
    }

    return ret;
}

