class disjointSet
{
public:
	vector<int> rank;
	vector<int> par;

	disjointSet() {}
	disjointSet(int size)
	{
		rank.resize(size, 0);
		par.resize(size, 0);
		for (int i = 0; i < size; ++i)
		{
			par[i] = i;
			rank[i] = 0;
		}
	}

	int find(int x)
	{
		if (x != par[x])
			par[x] = find(par[x]);

		return par[x];
	}

	void unite(int x, int y)
	{
		x = find(x);
		y = find(y);
		if (x == y)
			return;

		if (rank[x] < rank[y])
			par[x] = y;
		else
		{
			par[y] = x;
			if (rank[x] == rank[y])
				rank[x]++;
		}
	}

	bool same(int x, int y)
	{
		return find(x) == find(y);
	}
};

