//（素集合データ構造）
//https://atcoder.jp/contests/atc001/tasks/unionfind_a
class UnionFind
{
	vector<int> pr, rank;
public:
	UnionFind(int n) {
		pr.resize(n);
		rank.resize(n, 0);	//rank	子どもの深さ
		for (int i = 0; i < n; ++i) pr[i] = i;	//頂点iの親を格納する
	}
	int root(int x) {
		if (x == pr[x]) return x;
		else return pr[x] = root(pr[x]);	//経路圧縮
	}
	bool same(int x, int y) {
		return root(x) == root(y);
	}
	bool unite(int x, int y) {
		x = root(x);
		y = root(y);
		if (x == y) return false;
		if (rank[x] < rank[y]) {
			pr[x] = y;	//子どもを深く持つ方を親にする
		}
		else {
			pr[y] = x;
			if (rank[x] == rank[y]) ++rank[x];
		}
		return true;
	}
};

//最小全域木
//http://judge.u-aizu.ac.jp/onlinejudge/description.jsp?id=GRL_2_A&lang=jp
namespace MinTree
{
	struct Edge {
		int from, to, cost;
		Edge() {};
		Edge(int f, int t, ll c) {
			from = f; to = t; cost = c;
		}
	};
	//引数：辺(fromとtoがある)、頂点数
	//コストの小さい辺から順につないでいく。
	//閉路ができないように、UnionFindでデータを管理する
	ll kruskal(vector<Edge>& edges, int vnum) {
		sort(edges.begin(), edges.end(), [](Edge a, Edge b) {
			return a.cost < b.cost;
			});
		UnionFind uf = UnionFind(vnum);
		ll cmin = 0;
		for (Edge e : edges) {
			if (uf.unite(e.from, e.to)) {
				cmin += e.cost;
			}
		}
		return cmin;
	}
	//ある頂点から順に探索する
	//※dijkstraの場合は、ある地点sから、地点tへの移動の最小コストを見る。pqは累積コストで管理する。
	ll prim(vector<vector<Edge>>& graph, int start)
	{
		using CostPair = pair<ll, int>;
		vector<bool> used(graph.size(), false);
		priority_queue<CostPair, vector<CostPair>, greater<CostPair>> pq;
		pq.push(CostPair(0, start));
		ll sumcost = 0;
		while (!pq.empty()) {
			CostPair cp = pq.top(); pq.pop();
			ll c = cp.first; int v = cp.second;
			if (used[v]) continue;	//探索済みの点は省略
			used[v] = true;
			sumcost += c;
			for (Edge e : graph[v]) {
				if (used[e.to]) continue;
				pq.push(CostPair(e.cost, e.to));	//pqはその辺のコストで管理
			}
		}
		return sumcost;
	}
	void exec1()
	{
		int V, E; cin >> V >> E;
		vector<Edge> es(E);
		rep(i, E) cin >> es[i].from >> es[i].to >> es[i].cost;
		cout << kruskal(es, V) << endl;
	}
	void exec2()
	{
		int V, E; cin >> V >> E;
		vector<vector<Edge>> graph(V);
		rep(i, E) {
			int from, to, cost; cin >> from >> to >> cost;
			graph[from].push_back(Edge(-1, to, cost));
			graph[to].push_back(Edge(-1, from, cost));
		}
		cout << prim(graph, 0) << endl;
	}
}


int main()
{
	MinTree::exec1();
	return 0;
}

