#include <bits/stdc++.h>
using namespace std;

#define pinf 0x7FFFFFFF

struct Edge {
  int dst;
  int wgt;
  Edge(int idst, int iwgt) : dst(idst), wgt(iwgt) {}
};

class Graph {
private:
  int V;
  int E;
  vector <vector <Edge>> adj;
public:
  Graph(int n, int m);
  void addEdge(int src, int dst, int wgt);
  int prims();
};

Graph::Graph(int n, int m) {
  this->V = n;
  this->E = m;
  adj.resize(n);
}

void Graph::addEdge(int src, int dst, int wgt) {
  Edge a(dst, wgt);
  Edge b(src, wgt);
  adj[src].push_back(a);
  adj[dst].push_back(b);
}

int Graph::prims() {
  priority_queue <pair <int, int>, vector <pair <int, int>>, greater<pair <int, int>>> pq;
  vector <int> dist(V, pinf);
  vector <bool> mstset(V, false);

  //..starting at node 0
  int src = 0;
  dist[src] = 0;
  pq.emplace(0, src);

  while (!pq.empty()) {
    pair <int, int> pr = pq.top(); pq.pop();      
    int u = pr.second;
    mstset[u] = true;

    for (Edge &e : adj[u]) {
      int v = e.dst;
      if (!mstset[v] && e.wgt < dist[v]) {
        dist[v] = e.wgt;
        pq.emplace(dist[v], v);
      }
    }
  }

  int cost = 0;
  for (int i = 0; i < V; i++) {
    cost += dist[i];
  } 
  return cost;
}

