int dsjof(int x) {
  vector<int> updates;
  while (dsj[x] != x) {
    updates.push_back(x);
    x = dsj[x];
  }
  for (int i : updates) {
    dsj[i] = x;
  }
  return x;
}

void merge(int a, int b) {
  int p1 = dsjof(a);
  int p2 = dsjof(b);
  if (p1 < p2) {
    dsj[p1] = p2;
  } else {
    dsj[p2] = p1;
  }
}

