struct UnionFind
{
    vector<int> par; //par[i]:iの親の番号
    vector<int> siz; //葉の値を持つ

    UnionFind(int n) : par(n), siz(n, 1) //初期化
    {
        for (int i = 0; i < n; i++)
            par[i] = i;
    }

    int root(int x) //データxが属する木の根を再帰で得る
    {
        if (par[x] == x)
            return x;
        else
            return par[x] = root(par[x]);
    }

    int size(int x) { return siz[root(x)]; }

    bool same(int x, int y) { return root(x) == root(y); }

    bool unite(int x, int y) //xとyの木を併合
    {
        if ((x = root(x)) == (y = root(y))) //xとyの根が同じ時はそのまま
            return false;
        if (siz[y] > siz[x])
            swap(x, y);
        siz[x] += siz[y];
        par[y] = x; //yの根にxをつける
        return true;
    }
};

