class graph
{
public:
	ll n, m;
	vector<list<pll>> adj;
	vb visited;
	vll parent;
	vll dij;
	void add_edge(ll node1, ll node2, ll weight = 1)
	{
		adj[node1].push_back(mp(node2, weight));
		adj[node2].push_back(mp(node1, weight));
		++m;
