struct UnionFind{
    vector<ll> par;

    UnionFind(ll N) : par(N){
        rep(i,N){
            par[i]=i;
        }
    }

    ll root(ll x){
        if(par[x] == x) return x;
        return par[x] = root(par[x]);
    }

