class UnionFind {
public:
    vector <ll> par; // 各元の親を表す配列
    vector <ll> siz; // 素集合のサイズを表す配列(1 で初期化)
    // Constructor
    UnionFind(ll sz_): par(sz_), siz(sz_, 1LL) {
        for (ll i = 0; i < sz_; ++i) par[i] = i; // 初期では親は自分自身
    }
    void init(ll sz_) {
        par.resize(sz_);
        siz.assign(sz_, 1LL);  // resize だとなぜか初期化されなかった
        for (ll i = 0; i < sz_; ++i) par[i] = i; // 初期では親は自分自身
    }
    // Member Function
    // Find
    ll root(ll x) { // 根の検索
        while (par[x] != x) {
            x = par[x] = par[par[x]]; // x の親の親を x の親とする
        }
        return x;
    }
    // Union(Unite, Merge)
    bool unite(ll x, ll y) {
        x = root(x);
        y = root(y);
        if (x == y) return false;
        // merge technique（データ構造をマージするテク．小を大にくっつける）
        if (siz[x] < siz[y]) swap(x, y);
        siz[x] += siz[y];
        par[y] = x;
        return true;
    }
    bool same(ll x, ll y) { // 連結判定
        return root(x) == root(y);
    }
    ll size(ll x) { // 素集合のサイズ
        return siz[root(x)];
    }
};
// 頂点a, bをつなぐコストcostの（無向）辺
struct Edge{
    int a, b, cost;
// コストの大小で順序定義
    bool operator<(const Edge& o) const {
        return cost < o.cost;
    }
};
// 頂点数と辺集合の組として定義したグラフ
struct Graph
{
    int n;  // 頂点数
    vector<Edge> es;  // 辺集合
    // クラスカル法で無向最小全域木のコストの和を計算する
    // グラフが非連結のときは最小全域森のコストの和となる
    int kruskal() {
        // コストが小さい順にソート
        sort(es.begin(), es.end());
        UnionFind uf(n);
        int min_cost = 0;
        REP(ei, es.size()) {
            Edge& e = es[ei];
            if (!uf.same(e.a, e.b)) {
            // 辺を追加しても閉路ができないなら、その辺を採用する
            min_cost += e.cost;
            uf.unite(e.a, e.b);
            }
        }
        return min_cost;
    }
};
Graph input_graph() {
    Graph g;
    int m;
    cin >> g.n >> m;
    REP(i, m) {
        Edge e;
        cin >> e.a >> e.b >> e.cost;
        g.es.push_back(e);
    }
    return g;
}
//-----------------------------------------
int main(void){
    Graph G=input_graph();
    cout<<G.kruskal()<<"\n";
}

