    priority_queue<edge> que;
    rep(i, g[0].size()){
        que.push(g[0][i]);
    }
    while(!que.empty()){
        edge now = que.top();
        que.pop();
        if(done[now.to]){
            continue;
        }
        done[now.to] = true;
        ans += now.cost;
        rep(i, g[now.to].size()){
            if(!done[g[now.to][i].to]){
                que.push(g[now.to][i]);
            }
        }
    }
    cout << ans << endl;
    return 0;
}

