class Disjoint {
public:
	vector<int> rank, p;

	Disjoint() {}
	Disjoint(int size) {
		rank.resize(size, 0);
		p.resize(size, 0);

		for (int i = 0; i < size; i++) {
			Makeset(i);
		}
	}

	void Makeset(int x) {
		p[x] = x;
		rank[x] = 0;
	}

	bool same(int x, int y) {
		return Findset(x) == Findset(y);
	}

	void unite(int x, int y) {
		link(Findset(x), Findset(y));
	}

	void link(int x, int y) {
		if (rank[x] > rank[y]) {
			p[y] = x;
		}
		else {
			p[x] = y;
			if (rank[x] == rank[y]) {
				rank[y]++;
			}
		}
	}

	int Findset(int x) {
		if (x != p[x]) {
			p[x] = Findset(p[x]);
		}
		return p[x];
	}
};

class Edge {
public:
	int sou, tar, cost;
	Edge(int sou = 0, int tar = 0, int cost = 0) :
		sou(sou), tar(tar), cost(cost) {}

	bool operator < (const Edge& e) const {
		return cost < e.cost;
	}
};

int Kruskal(int N, vector < Edge> edges){
	int acost = 0;
	sort(edges.begin(), edges.end());

	Disjoint dset = Disjoint(N + 1);

	for (int i = 0; i < N; i++) {
		dset.Makeset(i);
	}

	int sou, tar;

	for (int i = 0; i < edges.size(); i++) {
		Edge e = edges[i];

		if (!dset.same(e.sou, e.tar)) {
			acost += e.cost;
			dset.unite(e.sou, e.tar);
		}
	}
	return acost;
}

