struct Union{
	vector<int> par;
	vector<int> size;


	Union(int n) : par(n), size(n,1){
	    for(int i=0; i < n; i++){
			size[i] = 1;
			par[i] = i;
		}
	}

	int find(int x){
		if (x == par[x]) return x;
		return par[x] = find(par[x]);  
	}

	void unite(int x, int y){
		x = find(x);
		y = find(y);

		if(x == y) return;

		if(size[x] < size[y]) swap(x, y);

