/* Union-Find-Tree */
/* 必ず要素数をコンストラクタに入れること */
template <class T = long long>
class Union_Find {
  using size_type = std::size_t;
  using _Tp = T;
public:

  vector<_Tp> par;
  vector<_Tp> rnk;

  // 親の根を返す。値の変更は認めない。
  const _Tp & operator[] (size_type child) {
    find(child);
    return par[child];
  }

  Union_Find (size_type n) {
    par.resize(n), rnk.resize(n);
    for (int i = 0; i < n; ++i) {
      par[i] = i;
      rnk[i] = 0;
    }
  }

  // 木の根を求める
  _Tp find(_Tp x) {
    if (par[x] == x)
      return x;
    else
      return par[x] = find(par[x]);
  }

  // xとyの属する集合を併合
  void merge(_Tp x, _Tp y) {
    x = find(x);
    y = find(y);
    if (x == y) return;

    if (rnk[x] < rnk[y]) {
      par[x] = y;
    } else {
      par[y] = x;
      if (rnk[x] == rnk[y]) rnk[x]++;
    }
  }

  // xとyが同じ集合に属するか否か
  bool same(_Tp x, _Tp y) {
    return find(x) == find(y);
  }
};

struct Edge {
  int a, b, cost;
  bool operator<(const Edge& o) const { return cost < o.cost; }
  bool operator>(const Edge& o) const { return cost > o.cost; }
};

int Kruskal(vector<Edge>& graph, int graphNodeNum) {
  int totalCost = 0;
  sort(graph.begin(), graph.end()); // const だとgraphをsortできない。
  Union_Find<long long> uf(graphNodeNum);
  for (auto edge : graph) {
    if (!uf.same(edge.a, edge.b)) {
      totalCost += edge.cost;
      uf.merge(edge.a, edge.b);
    }
  }
  return totalCost;
}

