class disjoint_set {
  public:
  vector<int> rank, prt;
  disjoint_set (int size) {
    rank.resize(size, 0);
    prt.resize(size, 0);
    for (int i = 0; i < size; i++) {
      prt[i] = i;
      rank[i] = 0;
    }
  }
  int find (int x) {
    return (x == prt[x] ? x : prt[x] = find(prt[x]));
  }
  bool is_equiv (int x, int y) {
    return find(x) == find(y);
  }
  bool unite (int x, int y) {
    x = find(x);
    y = find(y);
    if (x == y) {
      return false;
    }
    if (rank[x] > rank[y]) {
      swap(x, y);
    }
    prt[x] = y;
    if (rank[x] == rank[y]) {
      rank[y]++;
    }
    return true;
  }
};
