int getMinDist(int V)
{
    int min = MAX; int mi = 0;
    for(int i=1; i<=V; i++)
    {
        if(!visited[i] && min >= dist[i])
        {
            min = dist[i];
            mi = i;
        }
    }
    return mi;
}

void PrimsMST(int V)
{
    for(int i=1; i<=V-1; i++)
    {
        int v = getMinDist(V);
        visited[v] = true;
        for(int i=1; i<=V; i++)
        {
            if(!visited[i] && mat[v][i] != -1 && dist[i] > mat[v][i])
            {
                dist[i] = mat[v][i];
            }
        }
    }
}

