class DisjointSet {
private:
	vector<int> rank, p;
public:
	DisjointSet() {}
	DisjointSet(int n) {
		rank.assign(n, 0);
		p.assign(n, 0);
		for (int i = 0; i < n; i++) p[i] = i;
	}

	bool same(int x, int y) {
		return root(x) == root(y);
	}

	void unite(int x, int y) {
		x = root(x), y = root(y);
		if (x == y) return;
		if (rank[x] > rank[y]) {
			p[y] = x;
		} else {
			p[x] = y;
			if (rank[x] == rank[y]) rank[y]++;
		}
	}

	int root(int x) {
		return p[x] == x ? x : p[x] = root(p[x]);
	}
};

template <typename T>
T kruskal(int V, vector<edge<T> > G) {
	sort(G.begin(), G.end(), cmp<T>);
	DisjointSet ds(V);
	T cost = 0;
	for (edge<T> e : G) {
		if (!ds.same(e.from, e.to)) {
			cost += e.cost;
			ds.unite(e.from, e.to);
		}
	}
	return cost;
}
