//{{{ Edges kruskal(g)
Edges kruskal(const Graph& g){
  const int V = g.size();
  int E = 0;
  for (const auto& v : g) E += v.size();
  Edges es;
  es.reserve(E);
  for (const auto& v : g){
    for (const auto& e : v){
      es.emplace_back(e);
    }
  }
  sort(es);
  revs(es);
  UF uf(V);
  Edges result;
  for (const auto& e : es){
    if (uf.same(e.from, e.to)) continue;
    uf.merge(e.from, e.to);
    result.emplace_back(e);
  }
  return result;
}
//}}}
//{{{ Edges prim(g, s)
Edges prim(const Graph& g, int s=0){
  const int V = g.size();
  vector<bool> visited(V, false);
  priority_queue<Edge> pq;
  Edges result;
  for (pq.push(Edge(-2, s, 0)); !pq.empty(); pq.pop()){
    Edge c = pq.top();
    if (visited[c.to]) continue;
    visited[c.to] = true;
    result.emplace_back(c);
    for (const auto& e : g[c.to]){
      if (!visited[e.to]) pq.push(e);
    }
  }
  return result;
}
