template <class TCost = double>
struct Edge
{
	int from;
	int to;
	TCost cost;
	bool operator < (const Edge &rhs) const { return cost < rhs.cost; }
	bool operator > (const Edge &rhs) const { return cost > rhs.cost; }
};

template <class TCost = double>
struct PrimResult
{
	TCost totalCost;
	vector<int> parentNodeId;
};

// Prim法 //
template <class TCost>
PrimResult<TCost> Prim(const vevector<Edge<TCost>> &g)
{
	int N = g.size();

	vector<int> parent(N, -1);
	TCost totalCost = 0;

	typedef Edge<TCost> E;
	priority_queue<E, vector<E>, greater<E>> q;
	q.push({ 0, 0, 0 });

	while (!q.empty())
	{
		E cur = q.top(); q.pop();
		int i = cur.to;
		if (parent[i] != -1) continue;
		parent[i] = cur.from;
		totalCost += cur.cost;
		for(E e : g[i])
		{
			if (parent[e.to] == -1)
			{
				q.push(E{ e.from, e.to, e.cost });
			}
		}
	}
	return PrimResult<TCost>{ totalCost, parent };
}

