    edges.push_back((edge){ u, v, cost});
  }
};

template< class T >
class MinimumSpanningTree : public UnionFind, public SGraph< T >{
public:
  MinimumSpanningTree(int n):SGraph< T >(), UnionFind(n){};
  MinimumSpanningTree(Graph< T > g):SGraph< T >(g), UnionFind(g.g.size()){};
  T run(){
    sort( SGraph< T >::edges.begin(), SGraph< T >::edges.end());
    T ret = 0;
    ForEach(it, SGraph< T >::edges){
      if(!Same( it -> u, it -> v)){
        Union( it -> u, it -> v);
        ret += it -> cost;
      }
    }
    return ret;
  }
};

