void init_union_find(int v) {
  for(int i = 0; i < v; i++) {
    par[i] = i;
    r[i] = 0;
  }
}

int find(int x) {
  if(par[x] == x) return x;
  else return par[x] = find(par[x]);
}

void unite(int x, int y) {
  x = find(x);
  y = find(y);
  if(x == y) return ;

  if(r[x] < r[y]) {
    par[x] = y;
  } else {
    par[y] = x;
    if(r[x] == r[y]) r[x]++;
  }
}

bool same(int x, int y) {
  return find(x) == find(y);
}

bool comp(const edge& e1, const edge& e2) {
  return e1.cost < e2.cost;
}

