            if(parents[x] == parents[y]){
                return true;
            }else{
                return false;
            }
        }

        void unite(int x, int y){
            int root_x = find(x);
            int root_y = find(y);
            if (ranks[root_x] > ranks[root_y])
            {
                parents[root_y] = root_x;
            }else if(ranks[root_x] < ranks[root_y]){
                parents[root_x] = root_y;
