// Union-Findの実装
const int MAX_N = 10000; // 今回の場合、頂点の数の最大値

struct UnionFind
{
  // par[i]:要素iが属する木の親の番号、i==par[i]のときは要素iが木の根となる
  int par[MAX_N];

  // rank[i]:根が要素iの木の高さ(ランク)
  int rank[MAX_N];

  // コンストラクタ
  // 各要素iが要素iを根とする高さ0の木に存在するものとして初期化を行う
  UnionFind(int n){
    for(int i = 0; i < n; i++){
      par[i] = i;
      rank[i] = 0;
    }
  }

  // 要素xが属する木の根を得るメソッド
  int find(int x){
    if(par[x] == x) return x;
    else return par[x] = find(par[x]);
  }

  // 2つの要素xとyが属する木を併合するメソッド
  void unite(int x, int y){
    x = find(x);
    y = find(y);

    // 既に同じ木に属している場合
    if(x == y) return;

    // 効率化の工夫としてランクが低いものから高いものへ辺を張る
    if(rank[x] < rank[y]) par[x] = y;
    else{
      par[y] = x;
      if(rank[x] == rank[y]) rank[x]++; // ランクが等しい場合
    }
  }

  // 2つの要素xとyが属する木の根が同じならtrueを返すメソッド
  bool same(int x, int y){
    return find(x) == find(y);
  }
};

// 辺の情報を表す構造体
struct Edge{
  int u, w, cost;
};

// Edgeをコストの小さい順にソートするための比較関数
bool comp(const Edge &e1, const Edge &e2)
{
  return e1.cost < e2.cost;
}

const int MAX_E = 100000; // 辺の数の最大値
Edge es[MAX_E]; // グラフ上の辺を保存する配列
int v, e; // 頂点の数と辺の数


int kruskal()
{
  sort(es, es + e, comp); // 辺をコストの小さい順にソート
  UnionFind uf(v); // Union-Findの準備
  int ans = 0; // 最小全域木(森)の辺の総コスト

  // 全域木に辺を追加していく
  for(int i = 0; i < e; i++){
    // コストの小さい辺から調べる
    Edge et = es[i];

    // もし辺の両端の頂点が同じ連結成分属していないならば
    if(!uf.same(et.u, et.w)){
      uf.unite(et.u, et.w); // 同じ連結成分に属させる
      ans += et.cost; // その辺を全域木に追加
    }
  }

  return ans;
}


