class union_find {
public:
    vector<int> parent, rnk;

    union_find(int n){
        parent.resize(n);
        rnk.resize(n, 0);
        rep(i, n){
            parent[i] = i;
        }
    }

    int root(int x){
        if (parent[x] == x) {
            return x;
        }
        else{
            return root(parent[x]);
        }
    }

    void unite(int x, int y){
        x = root(x);
        y = root(y);
        if (x == y) {
            return;
        }
        if (rnk[x] < rnk[y]) {
            parent[x] = y;
        }
        else{
            parent[y] = x;
            if (rnk[x] == rnk[y]) {
                rnk[x]++;
            }
        }
    }

    bool same(int x, int y){
        return root(x) == root(y);
    }
};

