struct UnionFind {
    vector<int> par; // par[i]: iの親の番号

    UnionFind(int N) : par(N) { // 最初はすべてが根であるとして初期化
        REP(i, N) par[i] = i;
    }

    int root(int x) { // データxが属する木の根を再帰で得る: root(x) = {xの木の根}
        if (par[x] == x) return x;
        return par[x] = root(par[x]);
    }

    void unite(int x, int y) { // xとyの木を併合
        int rx = root(x);
        int ry = root(y);
        if (rx == ry) return;
        par[rx] = ry;
    }

    bool same(int x, int y) {
        int rx = root(x);
        int ry = root(y);
        return rx == ry;
    }
};

