class DisjointSets {
private:
    vector<int> rank;
    vector<int> parent;

public:
    DisjointSets() {}

    DisjointSets(int size)
    {
        rank.resize(size, 0);
        parent.resize(size, 0);
        for (int i = 0; i < size; i++)
            makeSet(i);
    }

    void makeSet(int x)
    {
        rank[x] = 0;
        parent[x] = x;
    }

    int findSet(int x)
    {
        if (x != parent[x])
            parent[x] = findSet(parent[x]);
        return parent[x];
    }

    void unite(int x, int y)
    {
        link(findSet(x), findSet(y));
    }

    void link(int rep1, int rep2)
    {
        if (rank[rep1] < rank[rep2])
            parent[rep1] = rep2;
        else
        {
            parent[rep2] = rep1;
            if (rank[rep1] == rank[rep2])
                rank[rep1]++;
        }
    }

    bool same(int x, int y)
    {
        return findSet(x) == findSet(y);
    }
};

class MinimumSpanningTree {
private:
    DisjointSets S;
    vector<Edge> edges;

public:
    MinimumSpanningTree(int vertex_num, int edge_num)
    {
        S = DisjointSets(vertex_num);

        int s, t, w;
        for(int e = 0; e < edge_num; e++)
        {
            cin >> s >> t >> w;
            edges.push_back(Edge(s, t, w));
        }
    }

    void kruscal()
    {
        vector<Edge> K;
        sort(edges.begin(), edges.end());

        for(Edge edge : edges)
        {
            if(!S.same(edge.source, edge.target))
            {
                S.unite(edge.source, edge.target);
                K.push_back(edge);
            }
        }

        int sum = 0;
        for(Edge edge : K)
            sum += edge.weight;
        cout << sum << endl;
    }
};

