  int res = 0;
  QU qu(n);
  sort(g.begin(), g.end(), [](edge a, edge b) { return a.w < b.w; });
  for (auto&& e : g) {
    if (!qu.same(e.from, e.to)) {
      qu.unite(e.from, e.to);
      res += e.w;
    }
  }
  return res;
}

