const int MAX_V = 10010;

class UnionFindTree {
public:
  vector<int> par;
  UnionFindTree(int V=0){
    par.clear(); par.resize(V);
    for(int i=0;i<V;i++) par[i] = i;
  }

  int find(int x) {
    if( x == par[x] ) return x;
    return par[x] = find(par[x]);
  }

  void unit(int x,int y) {
    x = find(x), y = find(y);
    if( x != y ) par[x] = y;
  }

};

struct Edge {
  int src,dst,weight;
  bool operator < ( const Edge &edge ) const {
    if( weight != edge.weight ) return weight < edge.weight;
    return ( ( src != edge.src ) ? src < edge.src : dst < edge.dst );
  }
};

int V,E;

int kruskal(vector<Edge> edges){
  int ret = 0;
  sort(edges.begin(),edges.end());
  UnionFindTree uf(V);
  for(int i=0;i<edges.size();i++){
    int p1 = edges[i].src, p2 = edges[i].dst;
    if( uf.find(p1) != uf.find(p2) ) {
      uf.unit(p1,p2);
      ret += edges[i].weight;
    }
  }
  return ret;
}

