template <class T> class UnionFind {
public:
	void Connect(Node<T>* a, Node<T>* b) {
		Vertex(a)->parent = Vertex(b);
	};
	bool Same(Node<T>* a, Node<T>* b) {
		return Vertex(a) == Vertex(b);
	};
private:
	Node<T>* Vertex(Node<T>* _obj) {
		if (_obj->parent == 0) {
			return _obj;
		}
		else {
			return _obj->parent = Vertex(_obj->parent);
		}
	};
};

