using namespace std;

class Edge{
    int v, u, weight;
public:
    Edge(int s=0, int t=0, int w=0) : v(s), u(t), weight(w) {}

    int get_weight() const { return weight; }

    int node1() const{ return v; }
    int node2() const{ return u; }

    bool operator<(const Edge& e){
        return weight < e.get_weight();
    }
};

bool operator<(const Edge& e1, const Edge& e2){
    return e1.get_weight() < e2.get_weight();
}

class UnionFind{
    vector<int> parent, rank;
public:
    UnionFind(int N){
        parent.resize(N);
        rank.resize(N);
        for(int i=0;i<N;i++){
            parent[i] = i;
        }
    }

    int find(int x){
        if(parent[x] != x){
            parent[x] = find(parent[x]);
        }
        return parent[x];
    }

    bool same(int x, int y){
        return find(x) == find(y);
    }

    void unite(int x, int y){
        int root_x = find(x);
        int root_y = find(y);
        if(rank[root_x] > rank[root_y]){
            parent[root_y] = root_x;
        }
        else{
            if(rank[root_x] == rank[root_y]){
                rank[root_y]++;
            }
            parent[root_x] = root_y;
        }
    }
};

int Kruskal(UnionFind& uf, vector<Edge>& edges){
    int cost = 0;
    for(int i=0;i<edges.size();i++){
        if(!uf.same(edges[i].node1(), edges[i].node2())){
            cost += edges[i].get_weight();
            uf.unite(edges[i].node1(), edges[i].node2());
        }
    }
    return cost;
}

int main()
{
    int N, M, s, t, w;
    cin >> N >> M;
    vector<Edge> edges(M);
    UnionFind uf(N);

    for(int i=0;i<M;i++){
        cin >> s >> t >> w;
        edges.at(i) = Edge(s, t, w);
    }

    sort(edges.begin(), edges.end());

    cout << Kruskal(uf, edges) << endl;
}

