pair<Weight,Edges>prim(const Graph &g,int s){
    int n=g.size();
    Edges tree;
    Weight total=0;
    vector<int>visited(n,0);
    priority_queue<Edge>q;
    q.emplace(-1,s,0);
    while(!q.empty()){
        Edge e=q.top();q.pop();
        if(visited[e.dst])continue;
        tree.push_back(e);
        total+=e.weight;
        visited[e.dst]=true;
        for(auto f:g[e.dst]){
            if(!visited[f.dst])q.push(f);
        }
    }
    return pair<Weight,Edges>(total,tree);
}

