class UnionFind{
private:
    vector<int> par,rank,sizes;
    int tree;

public:
    explicit UnionFind(const int n) : tree(n){
        par.resize(n+1);
        rank.resize(n+1);
        sizes.resize(n+1);
        rep(i,n){
            par[i] = i;
            sizes[i] = 1;
        }
    }

    ~UnionFind() = default;

    int root(int x){
        if(par[x] == x) return x;
        else return par[x] = root(par[x]);
    }

    int find(int x){ return root(x);}

    void unite(int x, int y) {
        x = root(x);
        y = root(y);
        if (x == y) return;

        if (rank[x] < rank[y]) swap(x, y);
        par[y] = x;
        tree--;
        sizes[x] += sizes[y];
        if (rank[x] == rank[y]) rank[x]++;
    }

    bool same(int x, int y){
        return root(x) == root(y);
    }

    int size(int x){
        return sizes[x];
    }

    int sumTree(){
        return tree;
    }
};

bool operator < (const Edge &e, const Edge &f) {
    return e.weight != f.weight ? e.weight < f.weight : //辺は重さが重いものを"小さい"と定義する
           e.src != f.src ? e.src < f.src : e.dst < f.dst;
}

int main(){
    int n,m; cin >> n >> m;
    UnionFind uf(n);

    ll ans = 0;

    Edges e(m);
    rep(i,m){
        int a,b,c;
        cin >> a >> b >> c;

        e[i].src = a;
        e[i].dst = b;
        e[i].weight = c;
    }

    sort(e.begin(),e.end());

    rep(i,m){
        int ts = e[i].src;
        int td = e[i].dst;
        int cost = e[i].weight;

        if(!uf.same(ts,td)){
            ans += cost;
        }

        uf.unite(ts,td);
    }

    cout << ans << endl;
}

