template <class TCost = double>
struct PrimResult
{
	TCost totalCost;
	vector<int> parentNodeId;
};

// Prim法 //
template <class TCost>
PrimResult<TCost> Prim(const vevector<TCost> &g)
{
	int N = g.size();

	vector<int> parent(N, -1);
	TCost totalCost = 0;

	typedef Edge<TCost> E;
	priority_queue<E, vector<E>, greater<E>> q;
	q.push({ 0, 0, 0 });

	while (!q.empty())
	{
		E cur = q.top(); q.pop();
		int i = cur.to;
		if (parent[i] != -1) continue;
		parent[i] = cur.from;
		totalCost += cur.cost;
		REP(j, N)
		{
			if (parent[j] == -1)
			{
				if (g[i][j] != inf<TCost>())
				{
					q.push(E{ i, j, g[i][j] });
				}
			}
		}
	}
	return PrimResult<TCost>{ totalCost, parent };
}

