typedef long long ll;

class UF
{
  public:
  int s;//木の頂点数
  vector<int> par;//親
  vector<int> rank;//木の深さ
  vector<int> size;//木の直径
  //コンストラクタ
  //n要素で初期化
  UF(int n)
  {
    s=n;
    par.resize(s);
    rank.resize(s);
    size.resize(s);
    for(int i=0;i<n;i++)
    {
      par[i]=i;
      rank[i]=0;
      size[i]=1;
    }
  }
  //木の根を求める
  int find(int x)
  {
    if(par[x]==x)
      return x;
    else
      return par[x]=find(par[x]);
  }
  //xとyの属する集合を併合
  void unite(int x,int y)
  {
    x=find(x);
    y=find(y);
    if(x==y)
      return;

    if(rank[x]<rank[y])
    {
      par[x]=y;
      size[y]+=size[x];
    }else{
      par[y]=x;
      size[x]+=size[y];
      if(rank[x]==rank[y])
        rank[x]++;
    }
  }
  //xとyが同じ集合に属するか否か
  bool same(int x,int y)
  {
    return find(x)==find(y);
  }
  //xが属する集合の大きさを求める
  int getsize(int x)
  {
    return size[find(x)];
  }
};

