class djs {
public:
	vector<int> rank;
	int p[10000];
	djs(int size) {
		rank.resize(size, 0);
		for (int i = 0; i < size; i++) p[i] = i;
	}
	int findset(int k) {
		if (p[k] != k) {
			p[k] = findset(p[k]);
		}
		return p[k];
	}
	bool same(int x, int y) { return findset(x) == findset(y); }
	void merge(int x, int y) {
		int a = findset(x);
		int b = findset(y);
		if (rank[a] > rank[b]) {
			p[b] = a;
		}
		else {
			p[a] = b;
			if (rank[a] == rank[b]) rank[b]++;
		}
	}
};
