        if(rank[x] < rank[y])par[x] = y;
        else{
            par[y] = x;
            if(rank[x] == rank[y])rank[x]++;
        }
    }
    bool same(int x,int y){
        return find(x) == find(y);
    }
};

template<class T> class Graph{
public:
    struct edge{
        int to;
        T cost;
        edge(int to,T cost):to(to),cost(cost){}
    };
    int N,M;
    vector<vector<edge>> g;
    Graph(int N,int M):N(N),g(N),M(M){}
    void add_edge(int a,int b,T cost = 1){
       g[a].emplace_back(b,cost);
    }
    void input(bool undirected = true,bool unweighted = true){
        for(int i = 0;i < M;i++){
            int a,b;
            T c = 1;
            cin >> a >> b;
            //a--,b--; // 1-indexed!!
            if(!unweighted) cin >> c;
            g[a].emplace_back(b,c);
            if(undirected) g[b].emplace_back(a,c);
        }
    }

};

template<class T> class MST : public Graph<T>,public UnionFind{
public:
    struct E{
        int from, to; T cost;
        E(int f,int t,T c):from(f),to(t),cost(c){}
    };
    static bool comp(const E& e1,const E& e2){
        return e1.cost < e2.cost;
    }
    int N,M;
    vector<E> es;

    vector<E> used; // edge of minimum spanning tree!
    MST(int N,int M):N(N),M(M),Graph<T>(N,M),UnionFind(N+1){}
    void add_edge(int a,int b,T c){
        Graph<T>::add_edge(a,b,c);
    }
    T kruskal();
};
template<class T>
T MST<T>::kruskal() {
    for(int i = 0;i < N;i++){
        for(auto e : Graph<T>::g[i]) es.emplace_back(i,e.to,e.cost);
    }
    sort(es.begin(),es.end(),comp);
    T res = 0;
    for(int i = 0;i < es.size();i++){
       auto e = es[i];
       if(!UnionFind::same(e.from,e.to)){
           UnionFind::unite(e.from,e.to);
           used.emplace_back(e);
           res += e.cost;
       }
    }
    return res;
}

int main(void){
    cin.tie(0);
    ios::sync_with_stdio(false);

    int n,m;cin >> n >> m;
    MST<int64_t> G(n,m);
    G.input(true,false);
    cout << G.kruskal() << '\n';
}

