class UFT{
public:
	UFT():parent(this){};
	UFT *&find(){
		if (parent == this){
			return parent;
		}else{
			return (parent = parent->find());
		}
	}
	void set_union(UFT &new_parent){
		find()->set_parent(new_parent.find());
	}
	bool &&operator==(UFT &other){
		return (find() == other.find());
	}
private:
	UFT *parent;
	void set_parent(UFT *new_parent){parent = new_parent;}
};
class Edge{
public:
	int s, t, w;
	Edge(int start = 0, int to = 0, int weight = 0):s(start), t(to), w(weight){};
	bool &&operator<=(const Edge &e) const {return w >= e.w;}
	bool &&operator<(const Edge &e) const {return w > e.w;}
	bool &&operator>=(const Edge &e) const {return w <= e.w;}
	bool &&operator>(const Edge &e) const {return w < e.w;}
	bool &&operator==(const Edge &e) const {return w == e.w;}
};
