LL prim(vector<PL> adjList[], int n) {
  LL ans = 0;

  vector<bool> visited; visited.assign(n, false);
  priority_queue<PL,vector<PL>,greater<PL>> pq; 

  pq.push({0, 0});
  while (!pq.empty()) {
    int u; LL w;
    tie(w, u) = pq.top(); pq.pop();

    if (visited[u])
      continue;

    visited[u] = true;
    ans += w;

    for (PL v : adjList[u]) {
      pq.push(v);
    }
  }

  return ans;
}

