class DisjointSet {
public:
    std::vector<int> rank, p; //p: parent
    DisjointSet() {}
    DisjointSet(int size) {
        rank.resize(size, 0);
        p.resize(size, 0);
        for (int i = 0; i < size; i++) makeSet(i);
    }

    void makeSet(int x) {
        p[x] = x;
        rank[x] = 0;
    }

    bool same (int x, int y) {
        return findSet(x) == findSet(y);
    }

    void unite(int x, int y) {
        link(findSet(x), findSet(y));
    }

    void link(int x, int y) {
        if (rank[x] > rank[y]) {
            p[y] = x;
        } else {
            p[x] = y;
            if (rank[x] == rank[y]) rank[y]++;
        }
    }

    //find parent (represtator) of x set
    int findSet(int x) {
        if (x != p[x]) {
            p[x] = findSet(p[x]);
        }
        return p[x];
    }
};

class Edge {
public:
    int source, target, cost;
    Edge (int source = 0, int target = 0, int cost = 0) : source(source), target(target), cost(cost) {}
    bool operator < (const Edge &e) const {
        return cost < e.cost;
    }
};

int kruskal(int N, std::vector<Edge> edges) {
    int totalCost = 0;
    std::sort(edges.begin(), edges.end());

    DisjointSet dset = DisjointSet(N+1);

    for (int i = 0; i < N; i++) dset.makeSet(i);

    for (int i = 0; i < edges.size(); i++) {
        Edge e = edges[i];
        if (!dset.same (e.source, e.target)) {
            totalCost += e.cost;
            dset.unite(e.source, e.target);
        }
    }

    return totalCost;

}



