struct LCA {
	// https://onlinejudge.u-aizu.ac.jp/courses/library/5/GRL/all/GRL_5_C
	int ver;
	int h;	//最大ダブリング回数
	int rt;
	vector<int> par;
	vector<vector<int>> anc;
	vector<int> depth;

	LCA(int _ver, vector<int> _par) : ver(_ver), par(_par), depth(_ver, -1) {
		for(int i = 0; i < ver; i++) {
			if(i == par[i]) rt = i;
		}
		anc.push_back(_par);
		vector<int> nxt(_ver);
		bool f = 1;
		int i = 0;
		while(f) {
			f = 0;
			for(int j = 0; j < _ver; j++) {
				if((nxt[j] = anc[i][anc[i][j]]) != rt) {
					f = 1;
				}
			}
			anc.push_back(nxt);
			i++;
		}
		h = (int)anc.size();
	}

	int dep(int now) {
		if(depth[now] != -1) return depth[now];
		if(now == rt) return depth[rt] = 0;
		return depth[now] = dep(par[now]) + 1;
	}

	int Lowest_Common_Ancestor(int x, int y) {
		int dx = dep(x), dy = dep(y);
		// 深さを揃える
		if(dx < dy) {
			int diff = dy - dx;
			for(int i = 0; i < h; i++) {
				if(diff & (1 << i)) {
					y = anc[i][y];
				}
			}
		} else {
			int diff = dx - dy;
			for(int i = 0; i < h; i++) {
				if(diff & (1 << i)) {
					x = anc[i][x];
				}
			}
		}
		if(x == y) return x;
		for(int i = h - 1; i > -1; i--) {
			if(anc[i][x] != anc[i][y]) {
				x = anc[i][x];
				y = anc[i][y];
			}
		}
		return par[x];
	}

	int distance(int x, int y) { return dep(x) + dep(y) - 2 * dep(Lowest_Common_Ancestor(x, y)); }
};

template <class T>	// WarshallFloyd
void warshall(vector<vector<T>> &v, T dekai = numeric_limits<T>::max()) {
	int n = v.size();
	for(int i = 0; i < n; i++)
		for(int j = 0; j < n; j++)
			for(int k = 0; k < n; k++) {
				if(v[j][i] == dekai || v[i][k] == dekai) continue;
				v[j][k] = min(v[j][k], v[j][i] + v[i][k]);
			}
	return;
}

