const long long INF = 1001001001;
const long long MOD = 1000000007;
const double EPS = 1e-10;

template<typename T>
struct Edge {
    int from, to;
    T cost;
};

template<typename T>
using Edges = vector<Edge<T>>;

template<typename T>
struct Graph {
    vector<Edges<T>> g;
    Graph(int n): g(n) {}
    int size() { return g.size(); };
    bool add_edge(int from, int to, T cost = 1) {
        g[from].emplace_back((Edge<T>){ from, to, cost });
    }
};

template<typename T>
struct MST {
    T cost;
    Edges<T> edges;
};

struct UnionFind {
    vector<int> d;
    UnionFind(int n): d(n, -1) {}
    int find(int x) {
        if(d[x] < 0) return x;
        return d[x] = find(d[x]);
    }
    bool unite(int x, int y) {
        x = find(x), y = find(y);
        if(x == y) return false;
        if(d[x] > d[y]) swap(x, y);
        d[x] += d[y];
        d[y] = x;
        return true;
    }
    bool same(int x, int y) { return find(x) == find(y); }
    int size(int x) { return -d[find(x)]; }
};

template<typename T>
MST<T> kruskal(Edges<T> &edges, int V) {
    sort(begin(edges), end(edges), [](const Edge<T> &a, const Edge<T> &b) {
        return a.cost < b.cost;
    });
    UnionFind tree(V);
    T total = T();
    Edges<T> es;
    for(auto &e : edges) {
        if(tree.unite(e.from, e.to)) {
            total += e.cost;
            es.emplace_back(e);
        }
    }
    return { total, es };
}

