    cin.tie(0);
    ios::sync_with_stdio(false);

    int v,e;
    cin>>v>>e;
    Edges<int> edges(e);
    for(int i=0;i<e;i++){
        int s,t,w;
        cin>>s>>t>>w;
        edges.emplace_back((Edge<int>){s,t,w});
        edges.emplace_back((Edge<int>){t,s,w});
    }
    cout<<kruskal<int>(edges,v).cost<<endl;
}

