    {
        if(myrank[x]>myrank[y])
        {
            p[y]=x;
        }
        else
        {
            p[x]=y;
            if(myrank[x]==myrank[y])
            {
                myrank[y]++;
            }
        }
    }
    int findside(int x)
    {
        if(x!=p[x])
        {
            p[x]=findside(p[x]);
        }
