struct UnionFind {
    int n;
    vector<int> sz,par;
    UnionFind(){}
    UnionFind(int sz):n(sz),sz(sz,1),par(sz,0){ iota(par.begin(),par.end(),0); }
    // xの親を見つける.
    int find(int x){
        return (x==par[x]?x:par[x]=find(par[x]));
    }
    // 同じ集合か
    bool same(int x,int y){
        return find(x)==find(y);
    }
    // xの属する集合とyの属する集合を結合
    void unite(int x,int y){
        x=find(x);y=find(y);
        if(x==y) return;
        if(sz[x]<sz[y]) swap(x,y);
        sz[x]+=sz[y];
        par[y]=x;
    }
    // xの属する集合サイズ
    int size(int x){
        return sz[find(x)];
    }
};


template<typename T>
struct Edge{
    int from,to;
    T cost;
    int used;
    Edge(int from,int to,T cost):
        from(from),to(to),cost(cost),used(0){}
    bool operator<(const Edge& e) const{
        return cost<e.cost;
    }
};


template <typename T>
T Kruskal(int V, vector<Edge<T>> &E) {
    // E: 辺集合
    UnionFind uf(V);
    sort(E.begin(), E.end());
    T minCost = 0;
    for (auto &e : E) {
        // 辺を採用
        if (!uf.same(e.from, e.to)) {
            minCost += e.cost;
            uf.unite(e.from, e.to);
            e.used = 1;
        }
    }
    return minCost;
}

int main(void) {
    int V, E;
    cin >> V >> E;
    vector<Edge<int>> edge;
    for (int i = 0;i < E;i++) {
        int s, t, w;
        cin >> s >> t >> w;
        edge.emplace_back(s,t,w);
    }
    cout << Kruskal(V, edge) << endl;
}

