    int n, m, s, t, c;
    vector<Edge> E;
    cin >> n >> m;
    for(int i = 0; i < m; i++) {
        cin >> s >> t >> c;
        E.push_back(Edge(s, t, c));
    }

    cout << kruskal(n, E) << endl;

    return 0;
}

