class DisjointSet{
public:
    vector<int>rank,p;
    DisjointSet(){}
    DisjointSet(int size){
        rank.resize(size,0);
        p.resize(size,0);
        for(int i=0;i<size;i++)
            makesets(i);
    }
    void makesets(int x){
        rank[x]=0;
        p[x]=x;
    }
    bool same(int x,int y){
        return findset(x)==findset(y);
    }
    void unite(int x,int y){
        if(findset(x)==findset(y))return;
        linked(findset(x),findset(y));
    }
    void linked(int x,int y){
        if(rank[x]>rank[y])
            p[y]=x;
        else{
            p[x]=y;
            if(rank[x]==rank[y])
                rank[y]++;
        }
    }
    int findset(int x){
        if(p[x]!=x){
            p[x]=findset(p[x]);
        }
        return p[x];
    }
};
