using namespace std;

class Connection {
public:
    int cost;
    string node1;
    string node2;
    Connection(int c, string n1, string n2) {
        cost = c;
        node1 = n1;
        node2 = n2;
    }
};

int myComp1 (const void* connection1, const void* connection2) {
    return ((Connection*)connection1)->cost - ((Connection*)connection2)->cost;
}

int myComp2 (const void* connection1, const void* connection2) {
    Connection* conn1 = (Connection*)connection1;
    Connection* conn2 = (Connection*)connection2;

    if (conn1->node1 < conn2->node1) {
        return -1;
    } else if (conn1->node1 > conn2->node1) {
        return 1;
    } else {
        if (conn1->node2 <= conn2->node2) {
            return -1;
        } else {
            return 1;
        }
    }
}

string myFind (string node, map<string, string>& parent) {
    if (node == parent[node]) {
        return node;
    } else {
        return myFind(parent[node], parent);
    }
}

bool myUnionFind (Connection connection, map<string, string>& parent) {
    string parent1 = myFind(connection.node1, parent);
    string parent2 = myFind(connection.node2, parent);

    if (parent1 == parent2) {
        return false;
    } else {
        parent[parent1] = parent2;
        return true;
    }
}

std::vector<Connection> minimumCostConnection(std::vector<Connection> connections) 
{
    vector<Connection> result;
    map<string, string> parent;
    set<string> nodes;

    qsort(&connections[0], connections.size(), sizeof(Connection), myComp1);

    for (int i = 0; i < connections.size(); i++) {
        parent[connections[i].node1] = connections[i].node1;
        parent[connections[i].node2] = connections[i].node2;
        nodes.insert(connections[i].node1);
        nodes.insert(connections[i].node2);
    }

    for (int i = 0; i < connections.size(); i++) {
        if (myUnionFind(connections[i], parent)) {
            result.push_back(connections[i]);
        }
    }

    if (result.size() != nodes.size()-1) {
        result.clear();
        return result;
    }

    qsort(&result[0], result.size(), sizeof(Connection), myComp2);

    return result;
}

int main() {
    vector<Connection> connections;
    int m, n;
    cin >> n >> m;

    for (int i = 0; i < m; i++) {
    	string n1, n2;
    	int c;
        cin >> n1 >> n2 >> c;
    	connections.push_back(Connection(c, n1, n2));
    }

    vector<Connection> result = minimumCostConnection(connections);
    int sum = 0;
    for (int i = 0; i < result.size(); i++) {
        Connection conn = result[i];
        sum += conn.cost;
    }
    cout << sum << endl;
    return 0;
}

