class UnionFindForests{
    public:
        vector<ll> parents, ranks;
        UnionFindForests(ll size){
            for (ll i = 0; i < size; ++i)
            {
                parents.push_back(i);
                ranks.push_back(0);
            }
        }

        ll find(ll x){
            if(parents[x] == x){
                return x;
            }else{
                //???????????????????????£?????´???????????´??\??????????????´????????????
                //pass compression(????????§???)
                return parents[x] = find(parents[x]);
            }
        }

        bool same(ll x, ll y){
            if(parents[x] == parents[y]){
                return true;
            }else{
                return false;
            }
        }

        void unite(ll x, ll y){
            ll root_x = find(x);
            ll root_y = find(y);
            if (ranks[root_x] > ranks[root_y])
            {
                parents[root_y] = root_x;
            }else if(ranks[root_x] < ranks[root_y]){
                parents[root_x] = root_y;
            }else if(ranks[root_x] == ranks[root_y]){
                parents[root_x] = root_y;
                ranks[root_y]++;
            }
        }
};

class Edge{ 
public:
	ll source, target, cost;

	Edge(ll source = 0, ll target = 0, ll cost = 0)
	:source(source)
	,target(target)
	,cost(cost){}

	static bool compare(const Edge& e1, const Edge& e2){
		return e1.cost < e2.cost;
	}
};

