class union_find_tree {
private:
	vector<int>par, rank_;
public:
	union_find_tree(int n) : par(n),rank_(n) {
		for (int i = 0; i < n; i++) {
			par[i] = i;
			rank_[i] = 0;
		}

	}
	int root(int x) {
		if (par[x] == x) {
			return x;
		}
		else {
			return par[x] = root(par[x]);
		}
	}
	bool same(int x, int y) {
		return root(x) == root(y);
	}
	void unite(int x, int y) {
		x = root(x);
		y = root(y);
		if (rank_[x] > rank_[y]) {
			par[y] = x;
		}
		else if (rank_[x] == rank_[y]) {
			par[x] = y;
			rank_[y]++;
		}
		else if (rank_[x] < rank_[y]) {
			par[x] = y;
		}

	}
};

