struct graph_t {
	int n;           // |V|, index begins with 0
	int m;           // |E|
	vector<P> edges; // E
	vector<ll> cost; // cost or distance
	vector<ll> cap;  // capacity
};

class Prim {
private:
	struct node {
		int id; bool done; vi to; vll cost; int from; ll d;
		bool operator<(const node & another) const {
			return !(d != another.d ? d < another.d : id < another.id);
		}
	};
	vector<node> nodes;
	int n;
	int root;
public:
	Prim(graph_t G, int start) {
		n = G.n;
		nodes.resize(n);
		Loop(i, n) nodes[i] = { i, false,{},{}, -1, INFLL };
		Loop(i, G.edges.size()) {
			nodes[G.edges[i].first].to.push_back(G.edges[i].second);
			nodes[G.edges[i].first].cost.push_back(G.cost[i]);
		}
		priority_queue<node> pq;
		root = start;
		nodes[root].d = 0;
		pq.push(nodes[root]);
		while (pq.size()) {
			node a = pq.top(); pq.pop();
			if (nodes[a.id].done) continue;
			nodes[a.id].done = true;
			Loop(j, a.to.size()) {
				node *b = &nodes[a.to[j]];
				if ((*b).done) continue;
				ll buf = a.cost[j];
				if (buf < (*b).d) {
					(*b).d = buf;
					(*b).from = a.id;
					pq.push(*b);
				}
			}
		}
	}
	vector<P> get_tree() {
		vector<P> ret;
		Loop(i, n) {
			if (i != root) {
				ret.push_back({ nodes[i].from, i });
			}
		}
		return ret;
	}
	ll get_weight() {
		ll ret = 0;
		Loop(i, n) {
			if (i != root) {
				ret += nodes[i].d;
			}
		}
		return ret;
	}
};

int main() {
	graph_t G;
	cin >> G.n >> G.m;
	Loop(i, G.m) {
		int s, t, c; cin >> s >> t >> c;
		G.edges.push_back({ s, t });
		G.cost.push_back(c);
		G.edges.push_back({ t, s });
		G.cost.push_back(c);
	}
	Prim prim(G, 0);
	cout << prim.get_weight() << endl;
	return 0;
}

