using tiii = tuple<int, int, int>;

class UnionFind
{
    public:
        const int n;
        vector<int> rank;
        vector<int> parent;

        UnionFind(int num): n(num)
        {
            rep(i, 0, n)
            {
                rank.push_back(0);
                parent.push_back(i);
            }
        }

        int root(int x)
        {
            if (parent[x] == x)
                return x;
            else
                return parent[x] = root(parent[x]);
        }

        void unite(int x, int y)
        {
            x = root(x);
            y = root(y);

            if (x == y) return;

            if (rank[x] < rank[y])
                parent[x] = y;
            else if (rank[y] < rank[x])
                parent[y] = x;
            else
            {
                parent[x] = y;
                rank[y]++;
            }
        }

        bool is_same(int x, int y)
        {
            return root(x) == root(y);
        }
};

int main()
{
    int num_v, num_e; 
    cin >> num_v >> num_e;

    UnionFind uf_tree(num_v);

    priority_queue<tiii, vector<tiii>, greater<tiii>> edges;

    rep(i, 0, num_e)
    {
        int s, t, w;
        cin >> s >> t >> w;
        edges.push(make_tuple(w, s, t));
    }

    ll ans = 0;
    while(edges.size() > 0)
    {
        int s, t, w;
        tie(w, s, t) = edges.top();
        edges.pop();

        if (! uf_tree.is_same(s, t))
        {
            ans += w;
            uf_tree.unite(s, t);
        }
    }
    cout << ans << endl;
    return 0;
}

