struct edge
{
	int u,v,cost;
	edge(int _u,int _v,int _cost){
		u =_u;
		v =_v;
		cost =_cost;
	}
};
void init(int V){
	for(int i= 0;i < V;i++){
		parent[i] = i;
		rank[i] =0;
	}
}

int find(int x){
	if(parent[x] == x)
		return x;
	else{
		return find(parent[x]);
	}
}

void unit(int x,int y){
	x = find(x);
	y = find(y);
	if(x == y)
		return;
	if(rank[x] < rank[y]){
		parent[x] = y;
	}
	else{
		parent[y] = x;
		if(rank[x] == rank[y])
			rank[x]++;
	}
}

bool same(int x,int y){
	return find(x) == find(y);
}
//コストが低い順にsortする
bool cmp(const edge left,const edge right){
	return left.cost <right.cost;
}
