int V,E;
int kruskal(){
	init(V);
	sort(es.begin(),es.end(),cmp);
	int res = 0;
	for(int i =0;i <E;i++){
		edge e =es[i];
		if(!same(e.u,e.v)){
			unit(e.u,e.v);
			res +=e.cost;
		}
	}
	return res;
}


