inline int Prim(int node_size, short int** G){
    short int V = node_size, mn = INF, mn_id = 0, v = 0, j, a, b;
    int res = 0;
    iota(nx, nx + V, 1), iota(prv, prv + V, -1);
    fill(d, d + V, INF);
    for(int i = 0; i < V-1; i++){
        for(j = nx[0]; j != V; j = nx[j]){
            a = min(v, j), b = max(v, j);
            d[j] = min(d[j], G[a][b-a-1]);
            if(d[j] < mn) mn = d[j], mn_id = j;
        }
        res += mn, v = mn_id;
        d[mn_id] = mn = INF;
        prv[nx[mn_id]] = prv[mn_id], nx[prv[mn_id]] = nx[mn_id];
    }
    return res;
}

