class DisjointSet {
  vector<int> p;
  vector<int> r;

public:
  DisjointSet(int n) {
    for (int i = 0; i < n; i++) {
      p.push_back(i);
      r.push_back(0);
    }
  }

  int findRoot(int u) {
    while (u != p[u]) {
      p[u] = p[p[u]];
      u = p[u];
    }
    return p[u];
  }

  bool isSame(int u, int v) {
    return (findRoot(u) == findRoot(v));
  }

  void link(int u, int v) {
    int u_root = findRoot(u);
    int v_root = findRoot(v);

    if (r[u_root] < r[v_root]) {
      p[u_root] = v_root;
    } else {
      p[v_root] = u_root;
      if (r[u_root] == r[v_root]) r[u_root]++;
    }
  }
};

class Edge {
public:
  int s, t, w;
  Edge(int s, int t, int w): s(s), t(t), w(w) {}
  bool operator < (const Edge &e) const {
    return w < e.w;
  }
};

vector<Edge> Es;

void kruskal() {
  DisjointSet ds(Es.size());
  int cost = 0;

  sort(Es.begin(), Es.end());

  for (int i = 0; i < Es.size(); i++) {
    Edge e = Es[i];
    if (!ds.isSame(e.s, e.t)) {
      ds.link(e.s, e.t);
      cost += e.w;
    }
  }

  cout << cost << endl;
}

