template<class T=int, class E>
T prim(Graph<E> &G, int s=0)
{
    T ret=0;
    using P=pair<T,int>;
    int V = G.size();
    vector<bool> use(V);
    priority_queue<P,vector<P>,greater<P> > que;
    que.push(P(0,s));
    while(!que.empty()){
        T cost; int v;
        tie(cost,v) = que.top(); que.pop();
        if (use[v]) continue;
        ret+=cost; use[v]=true;
        for(auto e:G[v])if(!use[e.to]){
            que.push(P(e.cost,e.to));
        }
    }
    return ret;
}

