class UnionFind {
	std::vector<int> m_nodes;

public:
	UnionFind(size_t size) : m_nodes(size) {
		for (size_t i = 0; i < size; i++)
			m_nodes[i] = i;
	}

	int find(int index) {
		int ret = m_nodes[index];
		if (ret == index) return ret;

		ret = find(ret);
		m_nodes[index] = ret;
		return ret;
	}

	void merge(int x, int y) {
		x = find(x);
		y = find(y);
		m_nodes[x] = y;
	}
};

