cost_type prim(long long s) {
  priority_queue<Pll, vector<Pll>, greater<Pll>> que;

  used[s] = true;

  for (auto e : Graph[s]) {
    que.push(Pll(e.cost, e.to));
  }

  // 使用済みの辺のコスト
  cost_type res = 0;
  // 使用済みの頂点の数
  long long v_count = 1;

  while (!que.empty() && v_count < V) {
    auto elem = que.top();
    que.pop();

    auto nc = elem.first;
    auto nv = elem.second;

    if (used[nv]) continue;

    used[nv] = true;
    res += nc;
    ++v_count;

    for (auto e : Graph[nv]) {
      if (!used[e.to]) {
        que.push(Pll(e.cost, e.to));
      }
    }
  }

  return res;
}

