    while(remain){
        ll w = -pq.top().first;
        ll now = pq.top().second;
        pq.pop();
        if(visit.at(now)) continue; //訪問済みは除く
        visit.at(now) = true;
        --remain;
        ans += w; //重み追加
        for(i = 0;i < graph.at(now).size();++i){
            ll nw = graph.at(now).at(i).first;
            ll next = graph.at(now).at(i).second;
            if(!visit.at(next)) pq.emplace(-nw, next);
        }
    }

