class UFind{
private:
    vector<int> par;
    vector<int> rank;
    vector<int> diff_weight;

    int root(int x) {
        if (par[x] == x)
            return x;
        else {
            int r = root(par[x]);
            diff_weight[x] += diff_weight[par[x]];
            return par[x] = r;
        }
    }

    int weight(int x) {
        root(x);
        return diff_weight[x];
    }

public:
    UFind(int n) {
        for (int i = 0; i < n; ++i){
            par.push_back(i);
            rank.push_back(0);
            diff_weight.push_back(0);
        }
    }

    bool issame(int x, int y) {
        return root(x) == root(y);
    }

    int diff(int x, int y) {
        return weight(y) - weight(x);
    }

    bool merge(int x, int y, int w) {
        w += weight(x);
        w -= weight(y);
        x = root(x);
        y = root(y);

        if (x == y)
            return false;

        if (rank[x] < rank[y]){
            swap(x, y);
            w = -w;
        }

        if (rank[x] == rank[y])
            ++rank[x];

        par[y] = x;
        diff_weight[y] = w;

        return true;
    }
};


