    if(!(1 <= VN && VN <= V) || !(0 <= EN && EN <= E))
        return -1;

    for(int i = 0; i < EN; i++){
        cin >> s >> t >> w;
        if(!(0 <= w && w <= WMAX) || !(0 <= s && s < VN) || !(0 <= t && t < VN))
            return -1;

        EdgeData.emplace_back(s, t, w);
    }

    EdgeData.sort(comp_weight);

    return VN;
}

void Kruskal(list<Edge> &EdgeData, int VertexNum){
    UFind uf(VertexNum);
    int TW = 0;

    while(!EdgeData.empty()){
        Edge et = EdgeData.front();
        EdgeData.pop_front();

        if(!uf.issame(et.e1, et.e2)){
            uf.merge(et.e1, et.e2, et.weight);
            TW += et.weight;
        }
    }

