struct UnionFind {
    int gid[SIZE], rank[SIZE];
    int groups;

    void init(int n) {
        for (int i = 0; i < n; ++i) {
            gid[i] = i;
            rank[i] = 0;
        }
        groups = 0;
    }

    int find(int x) {
        if (gid[x] == x) {
            return x;
        }
        return gid[x] = find(gid[x]);
    }

    bool equals(int a, int b) {
        return find(a) == find(b);
    }

    int merge(int x, int y) {
        int rx = find(x);
        int ry = find(y);
        if (rx != ry) {
            if (rank[rx] < rank[ry]) {
                gid[rx] = ry;
            } else {
                gid[ry] = rx;
            }
            groups--;
        }
        return groups;
    }
};

