	std::cin >> n >> m;
	Graph<Weight> g(n);
	for (int i = 0; i < m; ++i)
	{
		int u, v, cost;
		std::cin >> u >> v >> cost;
		g.AddEdge(u, v, cost);
		g.AddEdge(v, u, cost);
	}
	std::cout << Kruskal<Weight>(g).first << std::endl;
}

