int main(void) {
    int V, E;
    cin >> V >> E;

    priority_queue<Edge, vector<Edge>, std::greater<Edge>> queue;

    // edges.resize(V);
    for (int i = 0; i < E; i++) {
        int s, t, w;
        cin >> s >> t >> w;
        // edges[s].push_back({t, w});
        // edges[t].push_back({s, w});
        queue.push({s, t, w});
    }

    UnionFind uf(V);

    ll ans = 0;
    while (!queue.empty()) {
        Edge edge = queue.top();
        queue.pop();
        if (uf.same(edge.s, edge.t)) continue;
        uf.unite(edge.s, edge.t);
        ans += edge.w;
    }

    cout << ans << endl;

    return 0;
}

