typedef long long int ll;
typedef pair <int,int> P;

typedef tuple <ll,int,int> T;
struct edge{int to;ll cost;};
vector<edge> G[SIZE],M[SIZE];
bool used[SIZE];

//0_indexed
ll prim(){
  priority_queue<T,vector<T>,greater<T>> que;
  fill(used,used+SIZE,false);
  rep(i,0,SIZE) M[i].clear();
  ll res = 0;
  que.push(T(0,0,0));
  while(!que.empty()){
    T t = que.top();que.pop();
    ll l = get<0>(t);
    int v = get<1>(t);
    int from = get<2>(t);
    if(used[v])continue;
    res += l;
    used[v] = true;
    M[v].push_back((edge){from,l});
    M[from].push_back((edge){v,l});
    for(edge u : G[v]){
      if(!used[u.to])que.push(T(u.cost,u.to,v));
    }
  }
  return res;
}

void add_edge(int a,int b,ll c){
  G[a].push_back((edge){b,c});
  G[b].push_back((edge){a,c});
}

