int root(int x)
{
	if (par[x] == x)
	{
		return x;
	}
	else
	{
		return par[x] = root(par[x]);
	}
}


bool same(int x, int y)
{
	return root(x) == root(y);
}


void unite(int x, int y)
{
	x = root(x);
	y = root(y);
	if (x==y)
	{
		return;
	}


	if (r[x] < r[y])

	{
		par[x] = y;
	}
	else if(r[x]>r[y])
	{
