class DisjointSet {
public:
    vector<int> p;

    DisjointSet() {}
    DisjointSet(int size) {
        p.resize(size, 0);
        for (int i = 0; i < size; i++) {
            makeSet(i);
        }
    }

    void makeSet(int x) {
        p[x] = x;
    }

    int findset(int x) {
        if (p[x] != x) {
            p[x] = findset(p[x]);
        }
        return p[x];
    }

    bool same(int x, int y) {
        if (findset(x) == findset(y)) {
            return true;
        }
        else {
            return false;
        }
    }

    void unite(int x, int y) {
        link(findset(x), findset(y));
    }

    void link(int x, int y) {
        p[y] = x;
    }

};

class Edge {
public:
    int m_s, m_t, m_w;
    Edge() {}
    Edge(int s, int t, int w) {
        m_s = s;
        m_t = t;
        m_w = w;
    }
    bool operator < (const Edge &e) const {
        return m_w < e.m_w;
    }
};

vector<Edge> K;

int kruskal(int n, vector<Edge> edges) {
    int total_wgt = 0;
    sort(edges.begin(), edges.end());

    DisjointSet ds = DisjointSet(n + 1);

    for (int i = 0; i < edges.size(); i++) {
        Edge e = edges[i];
        if (ds.same(e.m_s, e.m_t) == false) {
            K.push_back(e);
            total_wgt += e.m_w;
            ds.unite(e.m_s, e.m_t);
        }
    }
    return total_wgt;
}

