int main()
{
	for (unsigned int i = 0; i < 10000; i++)
	{
		C[i] = false;
		N[i] = -1;
	}
	int V, E;
	cin >> V >> E;
	priority_queue<edge> S;
	priority_queue<edge> S1;
	for (unsigned int i = 0; i < E; i++)
	{
		int s, t, w;
		cin >> s >> t >> w;
		S.push(edge(w, s, t));
	}
	int count = 0;
	int sum = 0;
	while (!S.empty())
	{
		edge front = S.top();
		if (C[front.i] == false && C[front.j] == false)
		{
			N[front.i] = front.i;
			N[front.j] = front.i;
			sum += front.weight;
			C[front.i] = true;
			C[front.j] = true;
			count+=2;
		}
		else if (C[front.i] == false)
		{
			N[front.i] = N[front.j];
			sum += front.weight;
			C[front.i] = true;
			count++;

		}
		else if (C[front.j] == false)
		{
			N[front.j] = N[front.i];
			sum += front.weight;
			C[front.j] = true;
			count++;
		}
		else
		{
			S1.push(front);
		}
		if (count == E)
		{
			while (!S.empty())
			{
				S1.push(S.top());
				S.pop();
			}
		}
		else S.pop();
	}
	set<int> ignore;
	while (!S1.empty())
	{
		edge front = S1.top();
		if (N[front.i] != N[front.j])
		{
			if (find(ignore.begin(), ignore.end(), N[front.i]) == ignore.end()
				|| find(ignore.begin(), ignore.end(), N[front.j]) == ignore.end())
			{
				sum += front.weight;
				ignore.insert(N[front.j]);
				ignore.insert(N[front.i]);
			}
		}
		S1.pop();
	}
	cout << sum << endl;
	return 0;
}

