class Graph {
private:
	int V;
	vector<vector<int> > graph;
public:
	Graph(int V): V(V), graph(V, vector<int>(V, -1)) {
	};

	void addEdge(int src, int dst, int weight) {
		graph[src][dst] = weight;
		graph[dst][src] = weight;
	}

	int findMin(const vector<int> &distance, const vector<bool> &inSet) {
		int min = INT_MAX;
		int index;

		for (int i = 0; i < distance.size(); i++) {
			if (inSet[i])
				continue;
			if (distance[i] < min) {
				min = distance[i];
				index = i;
			}
		}
		return index;
	}

	int prim() {
		vector<int> distance(V, INT_MAX);
		vector<bool> inSet(V, false);
		vector<int> parent(V);
		int result = 0;

		distance[0] = 0;
		parent[0] = 0; 

		for (int i = 0; i < V-1; i++) {
			int index = findMin(distance, inSet);
			inSet[index] = true;

			for (int j = 0; j < V; j++) {
				if (graph[index][j] != -1 && inSet[j] == false && graph[index][j] < distance[j]) {
					parent[j] = index;
					distance[j] = graph[index][j];
				}
			}
		}

		for (int i = 1; i < V; i++) {
			result += graph[i][parent[i]];
			//printf("%d - %d    %d \n", parent[i], i, graph[i][parent[i]]);
		}

		return result;
	}
};

int main() {
	int V, E;
	cin >> V >> E;
	Graph g(V);

	for(int i = 0; i < E; i++) {
		int src, dst, weight;
		cin >> src >> dst >> weight;
		g.addEdge(src ,dst, weight);
	}

	cout << g.prim() << endl;

	return 0;
}

