int prim(int v) {
  mincost[0] = 0;
  int res = 0;

  while (true) {
    int ver = -1;
    for (int i = 0; i < v; i++) {
      if (used[i] == 0 && (ver == -1 || mincost[i] < mincost[ver])) ver = i;
    }
    if (ver == -1) break;

    used[ver] = 1;
    res += mincost[ver];

    for (int i = 0; i < v; i++) {
      mincost[i] = min(mincost[i], cost[ver][i]);
    }
  }
  return res;
}

