struct UnionFind {
  vector<int> data;

  UnionFind(int sz)
  {
    data.assign(sz, 0);
    for(int i = 0; i < sz; i++) data[i] = i;
  }

  int root(int x)
  {
    if(data[x] == x) return x;
    else return data[x] = root(data[x]);
  }

  bool unite(int x, int y)
  {
    x = root(x);
    y = root(y);
    if(x == y) return false;
    data[x] = y;
  }

  bool same(int x, int y)
  {
    return root(x) == root(y);
  }
};

void kruskal()
