  sum = 0;
  for(auto e : G)
  {
    ll cost = e.first;
    int from = e.second.first, to = e.second.second;
    if(!uf.same(from, to))
    {
      uf.unite(from, to);
      sum += cost;
      mst.emplace_back(P(from, to));
    }
  }
}

