}

void unite(int x, int y) {
	x = root(x);
	y = root(y);
	if (x == y) {
		return;
	}
	if (rank_[x] < rank_[y]) {
		par[x] = y;
	}
	else if (rank_[x]==rank_[y]){
		par[y] = x;
		rank_[x]++;

	}
	else if (rank_[y] < rank_[x]) {
		par[y] = x;
	}
}

