struct edge{
  int from, to;
  int weight;

  bool operator<(const edge &r) const{
    return weight != r.weight ? weight > r.weight : // !!INVERSE!!
    from != r.from ? from < r.from : to < r.to;
  }
};

class Kruskal{
  public:
  int Num; //ノードの数
  vector<int> par; //親の番号
  vector<int> height; //木の高さ(ランク)
  vector<edge> Edges;

  Kruskal(int N):
    par(vector<int>(N, 0)), height(vector<int>(N, 0)), Num(N) {}

  //初期化
  void init(){
    REP(i, Num){
      par[i] = i;
      height[i] = 0;
    }
  }

  //xの親番号を返す、再帰処理あり
  int root(int x){
    return par[x] == x ? x : par[x] = root(par[x]);
  }

  //xとyの親番号が同一か判定する
  bool same(int x, int y){
    return root(x) == root(y);
  }

  //xとyのある木を結合する
  void unite(int x, int y){
    x = root(x);
    y = root(y);
    if(x == y) return; //親が同一なら結合済み。

    if(height[x] < height[y]) par[x] = y;
    else {
      par[y] = x;
      if(height[x] == height[y]) height[x]++;
    }
  }

  //Kruskal法
  int operate(priority_queue<edge> &Q){
    int total_weight=0;
    while(Edges.size()<Num-1 && !Q.empty()){
      edge e = Q.top();
      Q.pop();
      if(!same(e.from, e.to)){
        unite(e.from, e.to);
        Edges.push_back(e);
        total_weight += e.weight;
      }
    }
    return total_weight;
  }
};



