// クラスカルのアルゴリズム
// 1. 辺を重みの昇順に整列する
// 2. 最小全域木の辺の集合をKとしてそれを空に初期化する
// 3. |最小全域木| = |頂点| - 1となるまでK or 辺が閉路を作らないような辺をKに追加する

class DisjointSet {
public:
    // rankは木の高さ(この数)，pは親
    vector<int> rank, p;

    DisjointSet() {}
    DisjointSet(int size)
    {
        // ベクターrankとpの大きさをsizeとして，足りない要素は0で補う
        rank.resize(size, 0);
        p.resize(size, 0);
        // すべての値を初期化する
        for (int i = 0; i < size; i++) {
            makeSet(i);
        }
    }

    void makeSet(int x)
    {
        // x番目の要素の親を自分自身にする
        // 木の高さ(子の数)も0で初期化する
        p[x] = x;
        rank[x] = 0;
    }

    bool same(int x, int y)
    {
        return findSet(x) == findSet(y);
    }

    void unite(int x, int y)
    {
        link(findSet(x), findSet(y));
    }

    void link(int x, int y)
    {
        // 木の高さが高い方に木の高さが小さい方の親の親を設定する
        if (rank[x] > rank[y]) {
            // xの方が高いときはyの代表の親をxにする
            p[y] = x;
        } else {
            // それ以外はyをxの代表の親にする
            p[x] = y;
            if (rank[x] == rank[y]) {
                // 高さが同じ時は高さを一つ高くする
                rank[y]++;
            }
        }
    }

    int findSet(int x)
    {
        if (x != p[x]) { // xが代表でない(xの親がxでない)時
            p[x] = findSet(p[x]); // xの親の親が代表か調べる(これを再帰)
        }
        return p[x];  // xの属する集団の代表を返す
    }
};

class Edge {
    public:
    int source, target, cost;
    Edge(int source = 0, int target = 0, int cost = 0):
    source(source), target(target), cost(cost) {}
    bool operator < (const Edge &e) const {
        return cost < e.cost;
    }
};

int kruskal (int N, vector<Edge> edges) {
    int totalCost = 0;
    sort(edges.begin(), edges.end()); // 辺を整列する

    DisjointSet dset = DisjointSet(N + 1); // UFを作る

    for (int i = 0; i < N; i++) {
        dset.makeSet(i);
    }

    int source, target;
    for (int i = 0; i  < edges.size(); i++) {
        Edge e = edges[i];
        if (!dset.same(e.source, e.target)) { // sourceとtargetの親が同じでなければ
            // MST.push_back(e);
            totalCost += e.cost;
            dset.unite(e.source, e.target);
        }
    }
    return totalCost;
}

