using namespace std;

std::vector<int> parent;
std::vector<int> rnk;

void init(int n){
    parent.clear();
    rnk.clear();
    for(int i=0; i<n; i++){
        parent.push_back(i);
        rnk.push_back(0);
    }
}

int find(int x){
    if(x == parent[x]){
        return x;
    } else {
        return parent[x] = find(parent[x]);
    }
}

void unite(int x, int y){
    x = find(x);
    y = find(y);

    if(x == y) return;

    if(rnk[x] < rnk[y]){
        parent[x] = y;
    } else {
        parent[y] = x;
        if(rnk[x] == rnk[y]) rnk[x]++;
    }
}

bool same(int x, int y) {
    return find(x) == find(y);
}

struct edge{
    int from, to, cost;
};

bool comp(const edge& e1, const edge& e2){
    return e1.cost < e2.cost;
}
