struct unionFind{
	vector<int> par;
	vector<int> rank;
	unionFind(int n) : par(n), rank(n,1) {
		rep(i,0,n){
			par[i] = i;
		}
	}

	int find(int x){
		if(par[x] == x){
			return x;
		}
		return par[x] = find(par[x]);
	}

	bool same(int x, int y){
		return find(x) == find(y);
	}

	void unite(int x, int y){//rank[x] > rank[y]
		x = find(x);
		y = find(y);
		if(x == y){
			return;
		}
		if(rank[x] < rank[y]){
			swap(x,y);
		}
		par[y] = x;
		rank[x] += rank[y];
		rank[y] = 0;
	}

	int size(int x){
		return rank[x];
	}
};

