const int INF_32 = 2e9;

struct PersistentUF {
	vector<int> par;
	vector<int> size;
	vector<int> time;
	int clock = 0;

	PersistentUF(int n) { init(n); }

	void init(int n) {
		par.resize(n);
		size.assign(n,1);
		time.assign(n,INF_32);
		for (int i = 0; i < n; ++i) par[i] = i; 
	}

	int scale(int x, int t = INF_32 - 1) {
		return size[find(x,t)];
	}

	int find(int x, int t = INF_32 - 1) {
		if(time[x] > t) return x;
		return find(par[x],t);
	}

	bool is_same(int x, int y, int t = INF_32 - 1) {
		return find(x,t) == find(y,t);
	}

	int unite(int x, int y) {
		++clock;
		x = find(x);
		y = find(y);
		if(x != y) {
			if(size[x] < size[y]) swap(x,y);
			size[x] += size[y];
			par[y] = x;
			time[y] = clock; 
		}
		return clock;
	}
};

int main(){
