};

class MinimumSpanningTree{
	ll cost;
	deque<bool> use;
public:
	MinimumSpanningTree(ConnectNodeInfo& connect){
		int N = connect.size();
		use.resize(N,false);

		auto comp = [](pair<ll,ll>& l,pair<ll,ll>& r){return l.second>r.second;};
		priority_queue<pair<ll,ll>,vector<pair<ll,ll>>,decltype(comp)> Q(comp);
		Q.emplace(0,0);
		cost=0;
		while(!Q.empty()){
			auto e=Q.top();
			Q.pop();
			if(use[e.first]) continue;
			use[e.first] = true;
			cost += e.second;
			for(auto& x:connect[e.first]){
				Q.push(x);
			}
		}
	}
	ll GetCost(){return cost;}
};

