struct union_find {
	struct node {int p, r = 0;};
	vector<node> nodes;

	union_find(int n) : nodes(n) {
		int i = 0;
		for (node &n: nodes)
			n.p = i++;
	}
	int find(int x) {
		int &p = nodes[x].p;
		if (p != x)
			p = find(p);
		return p;
	}
	void unite(int a, int b) {
		int ar = find(a), br = find(b);
		node &an = nodes[ar], &bn = nodes[br];
		if (an.r > bn.r)
			bn.p = ar;
		else {
			an.p = br;
			if (an.r == bn.r)
				bn.r++;
		}
	}
	bool same(int a, int b) {
		return find(a) == find(b);
	}
};

