struct UnionFind {
	vector<ll> par, rank, cnt;
	UnionFind(ll n) : par(n), rank(n, 0), cnt(n, 1){
		for(int i=0; i<n; ++i) par[i] = i;
	}

	ll find(ll x) {
		if (x == par[x]) return x;
		return par[x] = find(par[x]);
	}

	void unite(ll x, ll y) {
		x = find(x); y = find(y);
		if (x == y) return;

		if (rank[x] < rank[y]) swap(x, y);

		par[y] = x;
		cnt[x] += cnt[y];
		if (rank[x] == rank[y]) rank[x]++;
	}

	bool same(ll x, ll y) {
		return find(x) == find(y);
	}

	ll size(ll x) {
		return cnt[find(x)];
	}
};

