namespace SpanningTree{
    using namespace EGraph;

    //条件: 連結区間内
    //O(E*log(V))
    // verified by ACAC002 B
    // http://judge.u-aizu.ac.jp/onlinejudge/creview.jsp?rid=899143&cid=ACAC002
    Cost prim(Graph g,int s){
        const int V=g.size();
        vector<bool> visited(V);
        priority_queue<Edge,vector<Edge>,greater<Edge>> que;que.push(Edge(-1,s,0));
        Cost res=0;
        while(!que.empty()){
            Edge task=que.top();que.pop();
            int pos=task.to;
            if(visited[pos])continue;
            visited[pos]=true;
            res+=task.cost;
            for(Edge e:g[pos])if(!visited[e.to])que.push(e);
        }
        return res;
    }

    //O(E*log(V))
    // verified by ACAC002 B
    // http://judge.u-aizu.ac.jp/onlinejudge/creview.jsp?rid=899132&cid=ACAC002
    Cost kruskal(const Graph& g){
        const int V=g.size();
        UnionFind uf=UnionFind(V);
        priority_queue<Edge,vector<Edge>,greater<Edge>> que;
        REP(u,V)for(Edge e:g[u])que.push(e);
        Cost res=0;
        while(!que.empty()){
            Edge e=que.top();que.pop();
            if(!uf.same(e.from,e.to)){
                uf.unite(e.from,e.to);
                res+=e.cost;
            }
        }
        return res;
    }
}

