/*================================================
	Disjoint Set
================================================*/
class DisjointSet {
private:
	vector<int> rank, p;

	void link(int x, int y) {
		if (rank[x] > rank[y]) {
			p[y] = x;
		}
		else {
			p[x] = y;
			if (rank[x] == rank[y]) rank[y]++;
		}
	}
	int findSet(int x) {
		if (x != p[x]) p[x] = findSet(p[x]);
		return p[x];
	}

public:
	DisjointSet() {}
	DisjointSet(int size) {
		rank.resize(size, 0);
		p.resize(size, 0);
		rep(i, size) makeSet(i);
	}
	void makeSet(int x) {
		p[x] = x;
		rank[x] = 0;
	}
	bool same(int x, int y) {
		return findSet(x) == findSet(y);
	}
	void unite(int x, int y) {
		link(findSet(x), findSet(y));
	}
};

/* weight, source, destination */
priority_queue<pair<int, pair<int, int> >, vector<pair<int, pair<int, int> > >, greater<pair<int, pair<int, int> > > > Edges;

int krustal(int V)
{
	int totalCost = 0;
	pair<int, pair<int, int> > edge;
	DisjointSet dset = DisjointSet(V + 1);

	rep(i, V) dset.makeSet(i);
	while(!Edges.empty()) {
		edge = Edges.top(); Edges.pop();
