using namespace std;
class DSU {
  int n;  
  vector<int> p;
  vector<int> rank;
public:
  DSU(int _n): n(_n), p(n), rank(n, 0) {
    for (int i = 0; i < n; ++i) p[i] = i;
  }
  void unite(int x, int y) {
    int par_x = findRep(x);
    int par_y = findRep(y);
    if (rank[par_x] > rank[par_y]) {
      p[par_y] = par_x;
    } else {
      p[par_x] = par_y;
      if (rank[par_x] == rank[par_y]) rank[par_y]++;
    }
  }

  int findRep(int x) {
    if (x != p[x]) {
      p[x] = findRep(p[x]);
    }
    return p[x];
  }
};

template <typename T>
struct Edge {
  int from, to;
  T cost;
  Edge(int f, int t, T c): from(f), to(t), cost(c){};
  bool operator < (const Edge &e) const {
    return cost < e.cost;
  }
};

template <typename T>
T kruskal(vector< Edge<T> > &G, int n) {
  T total = 0;
  sort(G.begin(), G.end());
  DSU d = DSU(n);
  for (size_t i = 0; i < G.size(); ++i) {
    Edge<T> e = G[i];
    if (d.findRep(e.to) != d.findRep(e.from)) {
      d.unite(e.to, e.from);
      total += e.cost;
    }
  }
  return total;
}

