#include <bits/stdc++.h>
using namespace std;

struct	UnionFind {
	int		size;
	int		*par;
	int		*rank;
	int		num_group;
	UnionFind(int size): size(size), par(NULL), rank(NULL), num_group(size) {
		assert(size > 0);
		par = new int[size];
		rank = new int[size];
		assert(par != NULL && rank != NULL);
		for (int i = 0; i < size; ++i) {
			par[i] = i;
			rank[i] = 0;
		}
	}
	~UnionFind() {
		delete [] par;
		delete [] rank;
		par = NULL;
		rank = NULL;
	}
	int		find(int idx) {
		if (par[idx] == idx)
			return idx;
		return (par[idx] = find(par[idx]));
	}
	bool	same(int lhs, int rhs) {
		if (find(lhs) == find(rhs))
			return true;
		return false;
	}
	void	unite(int lhs, int rhs) {
		int	par_l = find(lhs), par_r = find(rhs);
		if (par_l == par_r)
			return;
		if (rank[par_l] < rank[par_r]) {
			par[par_l] = par_r;
		} else {
			par[par_r] = par_l;
			if (rank[par_l] == rank[par_r])
				++rank[par_l];
		}
		--num_group;
	}
};

int	main()
{
	int	V, E;
	cin >> V >> E;
	vector<tuple<int64_t, int, int>>	edge(E);
	UnionFind							uf(V);
	int									s, t;
	int64_t								w;
	for (int i = 0; i < E; ++i) {
		cin >> s >> t >> w;
		edge.at(i) = make_tuple(w, s, t);
	}
	sort(edge.begin(), edge.end());
	int64_t	total = 0;
	for (auto tpl : edge) {
		tie(w, s, t) = tpl;
		if (uf.same(s, t))
			continue;
		total += w;
		uf.unite(s, t);
		if (uf.num_group == 1)
			break;
	}
	cout << total << endl;
}

