struct edge_base {
  int from;
  int to;
};

template<class E>
struct graph_base {
  virtual void add_edge(E e) = 0;
  virtual const vector<E>& operator[](int i) const = 0;
  virtual int N() const = 0;
};

template<class E, class W>
vector<E> prim(const graph_base<E>& g, function<W(E)> sel) {
  int n = g.N();
  vector<E> ans;
  vector<bool> vis(n, false);
  using P = pair<W, E>;
  struct cmp {
    bool operator()(const P& a,const P& b){ 
      return a.first > b.first;
    }
  };
  priority_queue<P, vector<P>, cmp> que;
  vis[0] = true;
  for(auto & e : g[0]) {
    que.push({sel(e) , e});
  }
  for(int c = 0;c < n - 1;) {
    auto e = que.top().second;
    que.pop();
    if(vis[e.to]) continue;
    vis[e.to] = true;
    ans.push_back(e);
    for(auto & ee : g[e.to]) {
      if(!vis[ee.to])
        que.push({sel(ee) , ee});
    }
    c++;
  }
  return std::move(ans);
}

