struct uv_t{
  int u;
  int v;
};

vector<int> Parent;
vector<int> Rank;
multimap<int, uv_t> Edge; // Key: weight

int findSet(int x);

void makeSet(int x){
  Parent.push_back(x);
  Rank.push_back(0);
}
int findSet(int x){
  if( x != Parent[x] ){
    int r = findSet(Parent[x]);
    Parent[x] = r;
  }
  return Parent[x];
}
void link(int x, int y){
  if( Rank[x] > Rank[y] ){
    Parent[y] = x;
  }else{
    Parent[x] = y;
    if( Rank[x] == Rank[y] ){
      Rank[y] = Rank[y] + 1;
    }
  }
}

void unite(int x, int y){
  link(findSet(x), findSet(y));
}

