    for (lli i = 0; i < n; i++) {
      rank[i] = 0;
      parent[i] = i;
    }
  }
  lli find(lli x){
    if(x == parent[x])return x;
    else return parent[x] = find(parent[x]);
  }

  void unite(lli x, lli y){
    x = find(x);
    y = find(y);
    if(x == y)return;
    if(rank[x] < rank[y]){
      parent[x] = y;
    }else{
      parent[y] = x;
      if(rank[x] == rank[y])rank[x]++;
    }
  }
  bool same(lli x, lli y){
    return find(x) == find(y);
  }
private:
  lli n;
  vector<lli> rank, parent;
};


