int prim(vector< vector< pair<int,int> > > &G){
  vector<bool> connected(G.size(),false);
  priority_queue< pair<int,int> > wait;
  wait.emplace(0,0);
  int ret = 0;
  while(!wait.empty()){
    int c = -wait.top().first, v = wait.top().second;
    wait.pop();
    if(connected[v]) continue;
    connected[v] = true;
    ret += c;
