  }
}

void join(uint32_t a, uint32_t b)
{
  node_t *a_root = root(nodes[a]);
  node_t *b_root = root(nodes[b]);
  a_root->parent = b_root;
  b_root->children.push_back(a_root);
}

bool same(uint32_t a, uint32_t b)
{
  return root(nodes[a])->val == root(nodes[b])->val;
}

