class unionFindTree {
private:
	vector <int> tree;
	vector <int> rank;

public:
	unionFindTree() {}

	unionFindTree(int sz) {
		tree = vector <int> (sz);
		for(int i = 0; i < tree.size(); i++) {
			tree[i] = i;
		}
		rank = vector <int> (sz, 0);
	}

	unionFindTree(const unionFindTree &o) {
		tree = o.tree;
		rank = o.rank;
	}

	unionFindTree &operator=(const unionFindTree &o) {
		tree = o.tree;
		rank = o.rank;
		return (*this);
	};

	int root(int x) {
		return tree[x] == x ? x : tree[x] = root(tree[x]);
	}

	bool same(int a, int b) {
		return root(a) == root(b);
	}

	void unite(int a, int b) {
		a = root(a);
		b = root(b);
		if(a == b)return;

		if(rank[a] < rank[b]) swap(a, b);

		tree[b] = a;
		rank[a] += rank[a] == rank[b];
	}

	int size() {
		return tree.size();
	}
};

class Kruskal : public unionFindTree{
private:
	struct edge {
		int u, v, cost;
		bool operator< (const edge& e) const {
			return cost < e.cost;
		}
	};
	vector <edge> es;
	int V;

public:
	Kruskal(int v, int e) : unionFindTree(v){
		V = v;
		es = vector <edge> (e);
	}

	void addEdge(int start, int end, int cost) {
		es.push_back({start, end, cost});
	}

	int execute() {
		sort(es.begin(), es.end());
		int res = 0;
		for(int i = 0; i < es.size(); i++) {
			edge e = es[i];
			if(!same(e.u, e.v)) {
				unite(e.u, e.v);
				res += e.cost;
			}
		}
		return res;
	}
};


