    ll v = p.second;
    if(used[v] == true) continue;
    used[v] = true;
    res += p.first;
    for(int i=0;i<graph[v].size();i++){
      ll to = graph[v][i].first;
      ll cost = graph[v][i].second;
      if(!used[to]) PQ.push(make_pair(cost, to));
    }
  }
  return res;
}

