  vector<int> par; // par[i]:iの親の番号

  UnionFind(int N) : par(N){ // 最初は全てが根であるとして初期化
    for(int i = 0; i < N; i++) par[i] = i;
  }

  int root(int x){// データxが属する木の根を再帰で得る:root(x) = {xの木の根}
    if (par[x] == x) return x;
    return par[x] = root(par[x]);
  }

  bool unite(int x, int y){ // xとyの木を併合
    int rx = root(x); // xの根をrx
    int ry = root(y); // yの根をry
    if (rx == ry) return false; // xとyの根が同じ時はそのまま
    par[rx] = ry; // xとyの根が同じでない時，xの根rxをyの根ryにつける
    return true;
  }

  bool same(int x, int y){
    int rx = root(x);
    int ry = root(y);
    return rx == ry;
  }
};

struct corridor {
  int a, b, len;
  corridor(int a, int b, int len) : a(a), b(b), len(len){}
  // ソート用
  bool operator <(const corridor& rhs) const {
    if (len != rhs.len) { return len < rhs.len; }
    if (a != rhs.a) { return a < rhs.a; }
    return b < rhs.b;
  }
};

int main() {
  int V, E;
  cin >> V >> E;

  UnionFind tree(V);
  vector<corridor> cor;
  int s, t, w;
  rep(i, E){
    cin >> s >> t >> w;
    cor.push_back(corridor(s, t, w));
  }
  sort(cor.begin(), cor.end());
  int ans = 0;
  rep(i, E){
    if (tree.unite(cor[i].a, cor[i].b)){
      ans += cor[i].len;
    }
  }
  cout << ans << endl;

  return 0;
}

