vb Graph_func::graph_num_BFS(int BFS_ini, vb filled) { // ex. graph_num_BFS(i, filled);
	x_prqarr.push_back(BFS_ini);
	x_visited[BFS_ini] = true;

	while (!x_prqarr.empty())	{
		int Ntmp = x_prqarr.size();
		vi x_prqarr_next(0);
		rep(n, Ntmp) {
			int x = x_prqarr[n];
			rep(i, adjnum[x]) {
				int x_new = adjlist[x][i];
				if (!x_visited[x_new]) {
					x_prqarr_next.push_back(x_new);
					x_visited[x_new] = true;
					filled[x_new] = true;
				}
			}
		}
		x_prqarr = x_prqarr_next;
	}
	return filled;
}

int Graph_func::graph_num() {
	int anstmp = 0;
	int i = 0;
	vector<bool> filled;
	filled.resize(Vnum);
	rep(j, Vnum)
		filled[j] = false;
	bool end = false;
	while (!end)	{
		if (i >= Vnum)
			break;
		while (1) {
			if (!filled[i])
				break;
			i++;
			if (i >= Vnum) {
				end = true;
				break;
			}
		}
		if (end)
			break;
		filled[i] = true;
		filled = graph_num_BFS(i, filled);
		anstmp++;
	}
	return anstmp;
}

