  // }
  Vector(const unsigned int initial_size) {
    end = initial_size;
    alloc = max((unsigned int)1, initial_size);
    A = (T *)malloc(sizeof(T) * initial_size);
  }
  Vector(const Vector &other) {
    end = other.end;
    alloc = other.alloc;
    A = (T *)malloc(sizeof(T) * alloc);
    memcpy(A, other.A, sizeof(T) * alloc);
  }
  Vector &operator=(const Vector &other) {
    if (this != &other) {
      end = other.end;
      alloc = other.alloc;
      A = (T *)malloc(sizeof(T) * alloc);
      memcpy(A, other.A, sizeof(T) * alloc);
    }
    return *this;
  }
  unsigned int size() const { return end; }
  void push_back(T v) {
    if (end < alloc) {
    } else {
      if (alloc == 0 || A == NULL) {
        A = (T *)malloc(sizeof(T));
        alloc++;
      } else {
        unsigned int nalloc = alloc * 2;
        T *nA = (T *)malloc(sizeof(T) * nalloc);
        memcpy(nA, A, sizeof(T) * end);
        free(A);
        A = nA;
        alloc = nalloc;
      }
    }
    A[end] = v;
    end++;
  }
  void pop_back() {
    if (end == 0)
      return;
    end--;
  }
  T &operator[](unsigned int idx) { return A[idx]; }
  ~Vector() { free(A); }
};

template <typename T> class Heap {
private:
  Vector<T> A;

public:
  Heap() { A = Vector<T>(1); }

  void push(T v) {
    unsigned int idx = A.size();
    A.push_back(v);

    while (1) {
      if (idx == 1)
        break;
      unsigned int par = idx / 2;
      if (A[par] < A[idx])
        break;
      swap(A[idx], A[par]);
      idx = par;
    }
  };

  T top() {
    assert(A.size() > 1);
    return A[1];
  }
  T pop() {
    assert(A.size() > 1);
    T res = top();
    remove();
    return res;
  }
  bool empty() { return A.size() <= 1; }
  void remove() {
    T v = A[A.size() - 1];
    unsigned int idx = 1;
    A.pop_back();
    A[idx] = v;
    while (1) {
      unsigned int least = idx;
      unsigned int l = 2 * idx, r = 2 * idx + 1;
      if (l < A.size() && A[l] <= A[least]) {
        least = l;
      }
      if (r < A.size() && A[r] <= A[least]) {
        least = r;
      }

      if (least == idx)
        break;
      swap(A[idx], A[least]);
      idx = least;
    }
  }
#ifdef EBUG
  void print() {
    for (int i = 1; i < A.size(); i++) {
      cout << A[i] << " ";
    }
    cout << endl;
  }
#endif
};

