    q.push(pair<T, int>(0, 0));
    while (!q.empty()) {
        pair<T, int> p = q.top();
        q.pop();
        int from = p.second;
        if (used[from]) {
            continue;
        }
        //printf("append node %d\n", from);
        //printf("add cost %d\n", mincost[from]);
        result += mincost[from];
        used[from] = true;
        for (edge<T> e: g.edges[from]) {
            int to = e.to;
            T cost = e.cost;
            if (!used[to]) {
            //printf("edge (%d, %d), weight: %d\n", from, to, cost);
                if (!mincost_defined[to]) {
                    mincost_defined[to] = true;
                    mincost[to] = cost;
                    q.push(pair<T, int>(cost, to));
                } else if (mincost[to] > cost) {
                    mincost[to] = cost;
                    q.push(pair<T, int>(cost, to));
                }
            }
        }
    }
    delete [] used;
    delete [] mincost;
    delete [] mincost_defined;
    return result;
}

