pair<Weight, Edges> Kruskal(const Graph &g)
{
  int n = g.size();
  UnionFind uf(n);
  priority_queue<Edge> Q;
  rep(u, n) vrep(e, g[u]) if (u < e->dst) Q.push(*e);

  Weight total = 0;
  Edges F;
  while (F.size() < n-1 && !Q.empty()) {
    Edge e = Q.top(); Q.pop();
    if (uf.unite(e.src, e.dst)) {
      F.push_back(e);
      total += e.weight;
    }
  }
  return pair<Weight, Edges>(total, F);
}

