int getRoot (int d){
	if (parent[d] == d)
		return d;
	parent[d] = getRoot(parent[d]);
	return getRoot(parent[d]);
}

void MergeComp (int dx, int dy){
	parent[getRoot(dx)] = getRoot(dy);
}

bool isSameComp (int dx, int dy){
	return (getRoot(dx) == getRoot(dy));
