struct UnionFind {
    vector <int> par; 
    vector <int> siz; 
    UnionFind(int sz): par(sz), siz(sz, 1LL) {
        rep(i, sz) par[i] = i; 
    }
    int root(int x) { 
        while (par[x] != x) x = par[x] = par[par[x]]; 
        return x;
    }
    bool merge(int x, int y) {
        x = root(x);
        y = root(y);
        if (x == y) return false;
        if (siz[x] < siz[y]) swap(x, y);
        siz[x] += siz[y];
        par[y] = x;
        return true;
    }
    bool issame(int x, int y) { 
        return root(x) == root(y);
    }
    int size(int x) { 
        return siz[root(x)];
    }
};
int kruskal(WeightedGraph &g){
    priority_queue <tuple <int,int,int>,vector <tuple<int,int,int>>,greater <tuple<int,int,int>>> q;
    rep(i, g.size()){
        rep(j, g[i].size()){
            if(i <= g[i][j].F) continue;
            q.push(make_tuple(g[i][j].S, i, g[i][j].F));
        }
    }
    struct UnionFind tree(g.size());
    int ret = 0;
    while(!q.empty()){
        auto tmp = q.top(); q.pop();
        if(tree.root(get<1>(tmp)) != tree.root(get<2>(tmp))){
            tree.merge(get<1>(tmp),get<2>(tmp)); ret+= get<0>(tmp);
        }
    }
    return ret;
}
