class disjointset {
	vector<int> rank, p;
public:
	disjointset(int size) {
		rank.resize(size);
		p.resize(size);
		for (int i = 0; i < size; i++)
			makeset(i);
	}
	void unite(int a, int b) {
		link(findset(a), findset(b));
	}
	bool same(int a, int b) {
		return findset(a) == findset(b);
	}
private:
	void makeset(int x) {
		p[x] = x;
		rank[x] = 0;
	}
	void link(int x, int y) {
		if (rank[x] > rank[y]) {
			p[y] = x;
		} else {
			p[x] = y;
			if (rank[x] == rank[y])
				rank[y]++;
		}
	}
	int findset(int x) {
		if (p[x] == x)
			return x;
		else
			return p[x] = findset(p[x]);
	}
};

