// Union-Find木.
struct UnionFind{

    vector<int> data;
    UnionFind(int sz){ data.assign(sz, -1); }

    // 1. 頂点 x, y の 結合.
    bool unite(int x, int y){
        x = find(x), y = find(y);
        if(x == y)            return false;
        if(data[x] > data[y]) swap(x, y);
        data[x] += data[y];
        data[y] = x;
        return true;
    }

    // 2. 頂点 k を 探索.
    int find(int k){
        if(data[k] < 0) return k;
        return data[k] = find(data[k]);
    }

    // 3. 頂点 k を含む集合 の 大きさ.
    int size(int k){ return (-data[find(k)]); }
};

// クラスカル法.
int kruskal(){

    // 1. 辺をコストで昇順ソート.
    sort(es, es + E);

    // 2. Union-Find木を作成.
    UnionFind uf(V);

    // 3. 最小全域木の辺の重みの総和を計算.
    int res = 0;
    for(int i = 0; i < E; i++){
        edge e = es[i];
        if(uf.find(e.u) != uf.find(e.v)){
            uf.unite(e.u, e.v);
            res += e.c;
        }
    }
    return res;
}

