struct UnionFindTree {
    vector<int> par, rank;
    UnionFindTree(int n) : par(n , -1), rank(n, 0) { }
    int find(int x) {
        if (par[x] == -1) return x;
        else return par[x] = find(par[x]);
    }
    void unite(int x, int y) {
        x = find(x);
        y = find(y);
        if (x == y) return;
        if (rank[x] < rank[y]) swap(x, y);
        if (rank[x] == rank[y]) ++rank[x];
        par[y] = x;
    }
    bool same(int x, int y) {
        return find(x) == find(y);
    }
};

