        es.emplace_back(start, to, cost);
    }
    void build() {
        sort(es.begin(), es.end(), [](const edge& e1, const edge& e2) {
            return e1.cost < e2.cost;
        });
        for (edge &e : es) {
            if (!uft.same(e.start, e.to)) {
                uft.unite(e.start, e.to);
                cost_sum += e.cost;
            }
        } 
    }
