class edge {
public:
  int from, to, cost;
  edge(int from = 0, int to = 0, int cost = 0): from(from), to(to), cost(cost) {}
  bool operator < (const edge &e) const {
    return cost > e.cost;
  }
};

bool comp(const edge &e1, const edge &e2) {
  return e1.cost < e2.cost;
}

