vector <edge> graph[MAX_V];

int solve() {
  int mincost[V];
  bool used[V];
  memset(used, false, sizeof(used));
  setinf(mincost);
  mincost[0] = 0;
  int ret = 0;

  priority_queue<edge> pque;
  for (int i = 0; i < graph[0].size(); i++) {
    pque.push(graph[0][i]);
  }
  used[0] = true;
  while (true) {
    while (!pque.empty() && used[pque.top().to]) pque.pop();
    if (pque.empty()) break;

    int p = pque.top().to;
    used[p] = true;
    ret += pque.top().cost;
    pque.pop();
    for (int i = 0; i < graph[p].size(); i++) {
      edge e = graph[p][i];
      if (used[e.to]) continue;
      pque.push(e);
    }
  }

  return ret;
}

