class UnionFindTree:
    def __init__(self, V):
        self.parent = [i for i in range(V)]

    def root(self, x):
        if self.parent[x] == x:
            return x
        self.parent[x] = self.root(self.parent[x])
        return self.parent[x]

    def unite(self, x, y):
        rx = self.root(x)
        ry = self.root(y)
        self.parent[rx] = ry
        return

    def find(self, x, y):
        return self.root(x) == self.root(y)

class Edge:
    def __init__(self, s, t, w):
        self.s = s
        self.t = t
        self.w = w

    def __lt__(self, right):
        return self.w < right.w

def Kruscal(edges, V):
    utf = UnionFindTree(V)
    res = 0
    edges.sort()
    for e in edges:
        s = e.s
        t = e.t
        if not utf.find(e.s, e.t):
            res += e.w
            utf.unite(e.s, e.t)
    return res

