bool Judge(vector<Edge> e2, int x, int y) {
	vector<int> find (y);
	int m, n;
	for (int i = 0; i < y; i++) find[i] = i;
	for (int j = 0; j < x; j++) {
		m = e2[j].first;
		n = e2[j].second;
		while (find[m] != m) m = find[m];
		while (find[n] != n) n = find[n];
		if (m == n) {
			return false;
		}
		m = find[n];
	}
	return true;
}



void sort(int n) {
	vector<int> weight(n);
	for (int i = 0; i < n; i++) weight[i] = e[i].weight;
	for (int m = 0; m < n; m++) {
		for (int j = 0; j < n - m - 1; j++) {
			if (weight[j] > weight[j + 1]) {
				int tmp_w = weight[j];
				int tmp_f = e[j].first;
				int tmp_s = e[j].second;
				weight[j] = weight[j + 1];
				e[j].first = e[j + 1].first;
				e[j].second = e[j + 1].second;
				e[j].weight = e[j + 1].weight;
				weight[j + 1] = tmp_w;
				e[j + 1].first = tmp_f;
				e[j + 1].second = tmp_s;
				e[j + 1].weight = tmp_w;
			}
		}
	}
}

int min_span_tree(int n, int m) {
	sort(n);
	vector<Edge> ans(n);
	int count = 0;
	int ret = 0;
	for (int i = 0; count < m - 1; i++) {
		ans[count].first = e[i].first;
		ans[count].second = e[i].second;
		ans[count].weight = e[i].weight;
		ret += e[i].weight;
		count++;
		if (!Judge(ans,count, m)) {
			count--;
			ret -= e[i].weight;
		}
	}
	return ret;
}
