class UnionFind {
public:
	UnionFind(int n) : par(n, -1){}
	int root(int x){
		if (par[x] < 0) return x;
		return par[x] = root(par[x]);
	}
	bool same(int x, int y){
		return root(x) == root(y);
	}
	bool unite(int x, int y){
		x = root(x);
		y = root(y);
		if (x == y) return false;
		par[x] += par[y];
		par[y] = x;
		return true;
	}
	int size(int x){
		return -par[root(x)];
	}

private:
	vector<int> par;
};

