pair<Cost, Edges> kruskal(const Graph &g){
	UnionFind uf(g.size());
	priority_queue<Edge> pq;

	each(es, g) each(e, *es) pq.push(*e);

	Cost total = 0;
	Edges used;
	while (pq.size()){
		Edge e = pq.top(); pq.pop();
		if (uf.unite(e.src, e.dst)){
			used.pb(e);
			total += e.cost;
		}
	}

	return mp(total, used);
}



