vector<bool> visited; // 各頂点の訪問状況
vector<bool> connected; // 各頂点の始点からの連結性

void dijkstra(int start) { // 始点から各頂点までの最短距離を求めるダイクストラ法
    dist.resize(n, INF);
    visited.resize(n, false);
    dist[start] = 0;
    priority_queue<pair<int,int>, vector<pair<int,int>>, greater<pair<int,int>>> pq;
    pq.push({dist[start], start});
    while (not pq.empty()) {
        int cur = pq.top().second;
        pq.pop();
        visited[cur] = true;
        for (edge e : adj_list[cur]) {
            // int adj = e.to;
            if (visited[e.to] == false) {
                if (dist[e.to] > dist[e.from] + e.cost) {
                    dist[e.to] = dist[e.from] + e.cost;
                    pq.push({dist[e.to], e.to});
                }
            }
        }
    }
}

void dfs(int start) { // 始点からの経路が存在するか判定する
    connected[start] = true;
    for (edge e : adj_list[start]) {
        if (connected[e.to] == false) {
            dfs(e.to);
        }
    }
}

void bellman_ford(int start) { // 負の重みをもつ辺がある場合に単一始点最短距離を求めるベルマンフォード法
    connected.resize(n, false);
    dist.resize(n, INF);
    dfs(start);
    dist[start] = 0;
    negative = false;
    rep(i, n) { // 頂点の数n回ループ
        for (edge e : edges) {
            if (connected[e.from] == false) continue; // 始点からの経路が存在しなければスルー
            if (dist[e.to] > dist[e.from] + e.cost) {
                dist[e.to] = dist[e.from] + e.cost;
                if (i == n - 1) {
                    negative = true; // nループ目でdistの更新が生じるとき、負の閉路が存在
                    break;
                }                
            }
        }
    }
}

void warshall_floyd() { // 各頂点間の最短距離を求めるワーシャルフロイド法
    negative = false;
    rep(i, n) {
        dist_w[i][i] = 0;
    }
    rep(k, n) {
        rep(i, n) {
            rep(j, n) {
                if (dist_w[i][k] == INF || dist_w[k][j] == INF) continue;
                dist_w[i][j] = min(dist_w[i][j], dist_w[i][k] + dist_w[k][j]);
            }
        }
    }
    rep(i, n) {
        if (dist_w[i][i] < 0) {
            negative = true;
            break;
        }
    }
}

void prim() { // 最小全域木の辺の重みの総和
    dist.resize(n, INF);
    visited.resize(n, false);
    dist[0] = 0;
    priority_queue<pair<int,int>, vector<pair<int,int>>, greater<pair<int,int>>> pq;
    pq.push({dist[0], 0});
    while (not pq.empty()) {
        int cur = pq.top().second;
        pq.pop();
        visited[cur] = true;
        for (edge e : adj_list[cur]) {
            if (visited[e.to] == false) {
                if (dist[e.to] > e.cost) {
                    dist[e.to] = e.cost;
                    pq.push({dist[e.to], e.to});
                }
            }
        }
    }
}

