		add_edge(G, s, t, w);
		es.emplace_back(s, t, w);
		es.emplace_back(t, s, w);
	}

	auto cmp = [&](const Edge& l, const Edge& r) -> bool {
		return l.weight < r.weight;
	};

	sort(ALLOF(es), cmp);

	int ans = 0;
	uf_tree uf(V);
	for (auto e : es) {
		if (!uf.is_same(e.src, e.dst)) {
			ans += e.weight;
			uf.unite(e.src, e.dst);
		}
	}

	cout << ans << "\n";

	return 0;
}

