    UF(int num):V(num){
        a.resize(V);weight.resize(V);
        for(int i = 0; i < V;i++){
            a[i] = i;weight[i] = 1;
        }
    }
    int root(int i){
        while(a[i] != i) i = a[i];
        return i;
    }
    void Union(int i,int j);
    bool find(int i,int j){return root(i) == root(j);}
};

void UF::Union(int i,int j){
    i = root(i);
    j = root(j);
    if(weight[i] > weight[j]){
        a[j] = a[i];
        weight[i] += weight[j];
    }
    else{
        a[i] = a[j];
        weight[j] += weight[i];
    }
}

