int build_mst() {
	int mst_edge_count = 0;
	int sum = 0;
	for (int mst_edge_count = 0; mst_edge_count < v_ - 1; ++mst_edge_count) {
		//if (mst_edge_count % 1000 == 0) {
		//	cout << "mst_edge_count = " << mst_edge_count << endl;
		//}

		for (auto s : visited_nodes) {
			//cout << "s = " << s << endl;
			auto l = adjacency_list[s];
			while (!l.empty()) {
				auto e = l[l.size() - 1];
				//cout << "current edge: " << e.s_ << " " << e.t_ << " " << e.w_ << endl;
				if (visited_nodes.count(e.t_) == 0) {
					//cout << "not visited, adding to the queue." << endl;
