				}

				//cout << "vector size before: " << l.size() << endl;
				l.pop_back();
				//cout << "vector size after: " << l.size() << endl;
				adjacency_list[s] = l;
			}
		}

		for (int added = 0; added < 1;){
			WeightedEdge next_edge = candidate_edge_queue.top();
			candidate_edge_queue.pop();
			//cout << "next edge: " << next_edge.s_ << " " << next_edge.t_ << " " << next_edge.w_ << endl;
