class UnionFind
{
private:
    vector<int> par;
    vector<int> rank;
    vector<int> sz;
    int _count;

public:
    UnionFind(int n) : par(n), rank(n, 0), sz(n, 1), _count(n) {
        iota(par.begin(), par.end(), 0);
    }

    int find(int x) {
        if (par[x] == x) return x;
        else return par[x] = find(par[x]);
    }

    void unite(int x, int y) {
        x = find(x); y = find(y);
        if (x == y) return;

        _count--;
        if (rank[x] < rank[y]) {
            par[x] = y; sz[y] += sz[x];
        } else {
            par[y] = x; sz[x] += sz[y];
            if (rank[x] == rank[y]) rank[x]++;
        }
    }

    bool same(int x, int y) { return find(x) == find(y); }

    int size(int x) { return sz[find(x)]; }

    int count() { return _count; }
};

struct edge
{
    int u, v; ll cost;
};
bool operator<(const edge &lhs, const edge &rhs) { return lhs.cost < rhs.cost; };

int main()
{
    int V, E; cin >> V >> E;
    vector<edge> es(E);
    for (int i = 0; i < E; i++) cin >> es[i].u >> es[i].v >> es[i].cost;

    UnionFind uf(V);

    // kruskal法
    sort(es.begin(), es.end());
    ll ans = 0;
    for (auto &e: es) {
        if (!uf.same(e.u, e.v)) {
            uf.unite(e.u, e.v);
            ans += e.cost;
        }
    }

    cout << ans << endl;
    return 0;
}

