#include <vector>
using namespace std;

#define MAX_V (10010)

typedef struct {
    int f;
    int s;
    int w;
} Edge;

int V, E;
int parent[MAX_V];

vector<Edge> edge_array;

bool cmp( const Edge &l, const Edge &r ) {
    return ( l.w <= r.w );
}

void init_union(int v) {
    for ( int i = 0; i < v; i++ ) parent[i] = i;
}

int find_root( int a ) {
    if ( parent[a] == a ) return a;
    else return parent[a] = find_root( parent[a] );
}

bool is_same( int a, int b ) {
    int r_a = find_root( a );
    int r_b = find_root( b );

    return ( r_a == r_b );
}

void combine( int a, int b ) {
    int r_a = find_root( a );
    int r_b = find_root( b );
    parent[r_b] = r_a;
}


int main()
{
    int ans = 0;
    scanf("%d %d", &V, &E);

    for ( int i = 0; i < E; i++ ) {
	Edge e;
	scanf("%d %d %d", &e.f, &e.s, &e.w);
	edge_array.push_back( e );
    }

    sort( edge_array.begin(), edge_array.end(), cmp );

    init_union( V );

    for ( int i = 0; i < edge_array.size(); i++ ) {
	Edge e = edge_array[i];
	if ( !is_same( e.f, e.s ) ) {
	    ans += e.w;
	    combine( e.f, e.s );
	}
    }

    printf("%d\n", ans);
    return 0;
}

