    // Kruskal's algorithm
    int total = 0;
    sort(edges.begin(), edges.end(), [](const edge& a, const edge& b) { return a.weight < b.weight; });
    auto S = DisjointSet(V);
    for (auto& e : edges) {
        if (!S.same(e.src, e.dst)) {
            total += e.weight;
            S.unite(e.src, e.dst);
        }
    }
    cout << total << endl;

    return 0;
}

