        q.push(e);
    }

    UnionFind uf(N);
    ll ans = 0;
    while (!q.empty()) {
        auto t = q.top();
        q.pop();
        if (uf.same(t.a, t.b))
            continue;
        uf.unit(t.a, t.b);
        ans += t.c;
    }

    cout << ans << endl;

    return 0;
}

