const int MAX_N=1e5+5;
class UnionFind
{
    int par[MAX_N];
    int rnk[MAX_N];
    int sizes[MAX_N];
    public:
    void init(int n)
    {
        for(int i=0;i<n;i++)
        {
            par[i]=i;
            rnk[i]=0;
            sizes[i]=1;
        }
    }
    int find(int x)
    {
        if(par[x]==x)
        {
            return x;
        }
        else
        {
            return par[x]=find(par[x]);
        }
    }
    void unite(int x,int y)
    {
        x=find(x);
        y=find(y);
        if(x==y) return;
        if(rnk[x]<rnk[y]) swap(x,y);
        par[y]=x;
        if(rnk[x]==rnk[y]) rnk[x]++;
        sizes[x]+=sizes[y];
    }
    bool same(int x,int y)
    {
        return find(x)==find(y);
    }
    int size(int x)
    {
        return sizes[find(x)];
    }
};

