void ReadGraph()
{
    cin>>n>>m;
    for (int i = 0; i < m; ++i)
        cin>>e[i].u>>e[i].v>>e[i].c;
}

int FindRoot(int u)
{
    if (parent[u] <= 0)
        return u;
    int root = FindRoot(parent[u]);
    parent[u] = root;
    return root;
}

void Union(int u, int v)
{
    if (parent[u] < parent[v])
        parent[v] = u;
    else
    {
        parent[v] = min(parent[v], parent[u]-1);
        parent[u] = v;
    }
}


void Solve()
{
    ReadGraph();
    sort(e, e+m, cmp);
    for (int u = 0; u < n; ++u)
        parent[u] = 0;
    int ans = 0;
    for (int i = 0; i < m; ++i)
    {
        edge x = e[i];
        int ru = FindRoot(x.u);
        int rv = FindRoot(x.v);
        if (ru != rv)
        {
            ans += x.c;
            Union(ru, rv);
        }
    }
    cout<<ans;
}

