void unite(int r1, int r2, vector<int>& node, vector<int>& hight){
    int big   = r1;
    int small = r2;
    if (hight[big] < hight[small]) swap(big, small);
    if (hight[big] == hight[small]) hight[big]++;
    node[small] = big;
}

