class unionFindTree {
private:
	vector <int> tree;
	vector <int> rank;

public:
	unionFindTree() {}

	unionFindTree(int sz) {
		tree = vector <int> (sz);
		rank = vector <int> (sz, 0);
		for(int i = 0; i < tree.size(); i++)
			tree[i] = i;
	}

	unionFindTree(const unionFindTree &o) {
		tree = o.tree;
		rank = o.rank;
	}

	unionFindTree &operator=(const unionFindTree &o) {
		tree = o.tree;
		rank = o.rank;
		return (*this);
	};

	int root(int x) {
		return tree[x] == x ? x : tree[x] = root(tree[x]);
	}

	bool same(int a, int b) {
		return root(a) == root(b);
	}

	void unite(int a, int b) {
		a = root(a);
		b = root(b);
		if(a == b)return;

		if(rank[a] < rank[b]) swap(a, b);

		tree[b] = a;
		rank[a] += rank[a] == rank[b];
	}

	int size() {
		return tree.size();
	}
};

class Kruskal {
	private:
		struct edge {
			int u, v, cost;
			bool operator< (const edge& e) const {
				return cost < e.cost;
			}
		};
		vector <edge> es;
		unionFindTree uft;
		int V;

	public:
		Kruskal(int v, int e) {
			V = v;
			es = vector <edge> (e);
			uft = unionFindTree(V);
		}

		void addEdge(int start, int end, int cost) {
			es.push_back({start, end, cost});
		}

		int execute() {
			sort(es.begin(), es.end());
			int res = 0;
			for(int i = 0; i < es.size(); i++) {
				edge e = es[i];
				if(!uft.same(e.u, e.v)) {
					uft.unite(e.u, e.v);
					res += e.cost;
				}
			}
			return res;
		}
};

