int prim(Graph &G) {
    int V = G.size(), ans = 0;
    vector<bool> used(V, false);
    priority_queue< Edge, vector<Edge>, greater<Edge> > q;
    q.push(Edge(0, 0, 0));
    while(!q.empty()) {
        Edge temp = q.top(); q.pop();
        if(used[temp.to]) continue;
        used[temp.to] = true;
        ans += temp.cost;

        rep(i,0,G[temp.to].size()) q.push(G[temp.to][i]);
    }
    return ans;
}

