const int MAX = 10000;
const int INF = 999999999;
int U[MAX];
int n, G[MAX][MAX];
struct Edge
{
	int u;
	int v;
	int w;
};
vector<Edge> E;
void init()
{
	for (int i = 0; i < n; i++)
		U[i] = i;
}
int getAncestor(int v)
{
	if (U[v] == v)
		return v;
	else
	{
		U[v] = getAncestor(U[v]);
		return U[v];
	}
}
bool merge(int s, int t)
{
	int a1 = getAncestor(s);
	int a2 = getAncestor(t);
	if (a1 != a2)
	{
		U[a2] = a1;
		return false;
	}
	return true;
}
bool cmp(Edge a, Edge b)
{
	return a.w < b.w;
}
int main()
{
	int m;
	cin >> n >> m;
	for (int i = 0; i < m; i++)
	{
		int u, v, w;
		cin >> u >> v >> w;
		Edge e = { u,v,w };
		E.push_back(e);
	}
	init();
	sort(E.begin(), E.end(), cmp);
	int sum = 0;
	int edgeNum = 0;
	//cout << "MST的边为：\n";
	for (int i = 0; i < E.size(); i++)
	{
		Edge e = E[i];
		if (!merge(e.u, e.v))
		{
			sum += e.w;
			edgeNum++;
			//cout << e.u << "---" << e.v << " 权值为" << e.v << endl;
		}
		if (edgeNum == n - 1)
			break;
	}
	cout << sum << endl;
}

