int Kruskal() {
	sort(es, es + E, comp);
	UnionFindTree::UnionFindTree ufT(V);
	int res = 0;
	rep(i, E) {
		edge e = es[i];
		if (!ufT.Same(e.u, e.v)) {
			ufT.Unite(e.u, e.v);
			res += e.cost;
		}
	}
	return res;
}


