int n, m, k1, k2, dad[maxN], high[maxN], ans;
pair <int, pair <int, int> > P[maxN]; 
int root(int a){
	if (dad[a] == a)
		return a;
	dad[a] = root(dad[a]);
	return dad[a];
}
void merrge(int a, int b){
	if (high[root(a)] > high[root(b)])
		swap(a, b);
	int newhigh = high[root(b)];
	if (high[root(a)] == high[root(b)])
		newhigh++;
	dad[root(a)] = root(b);
	high[root(a)] = newhigh;
	return ;
}
int main(){
