using wight_graph = std::vector<std::vector<std::pair<size_t, size_t>>>;

int main(){

    size_t v, e;
    std::cin >> v >> e;

    wight_graph g(v);

    for(size_t i = 0; i < e; i++){
        size_t s, t, w;
        std::cin >> s >> t >> w;

        g.at(s).emplace_back(t, w);
        g.at(t).emplace_back(s, w); // 婿向グラフリスト表現
    }

    std::vector<size_t> cost(v, std::numeric_limits<size_t>::max()); // 添字(頂点)の最も小さいコスト
    std::vector<size_t> seen(v, false);
    std::priority_queue<std::pair<size_t, size_t>,
                        std::vector<std::pair<size_t, size_t>>, 
                        std::greater<std::pair<size_t, size_t>>> candidate; // firsr: 重み second: 添字(頂点)

    cost.at(0) = 0; // 始点のコストをゼロに
    candidate.emplace(0, 0); // 始点を候補へ追加

    while(!candidate.empty()){
        size_t weight, index;
        std::tie(weight, index) = candidate.top(); candidate.pop(); // c++14 (c++17: structured bindings)
        seen.at(index) = true;

        for(size_t i = 0; i < g.at(index).size(); i++){
            if(cost.at(g.at(index).at(i).first) > g.at(index).at(i).second){
                if(!seen.at(g.at(index).at(i).first)){
                    cost.at(g.at(index).at(i).first) = g.at(index).at(i).second;
                    candidate.emplace(cost.at(g.at(index).at(i).first), g.at(index).at(i).first);
                }
            }
        }
    }

    std::cout << std::accumulate(cost.begin(), cost.end(), 0ul) << std::endl;

    return 0;
}

