int prim() {
    int res = 0;
    priority_queue< P, vector<P>, greater<P> > que;
    que.push(P(0, 0));
    d[0] = 0;
    while(!que.empty()) {
        P p = que.top(); que.pop();
        int u = p.second;
        if (seen[u]) continue;
        seen[u] = true;
        res += p.first;
        REP(i, (int)es[u].size()) {
            edge e = es[u][i];
            if (d[e.to] > e.cost) {
                d[e.to] = e.cost;
                que.push(P(d[e.to], e.to));
            }
        }
    }
    return res;
}
