int root(int x){
  if (*(p+x) == x){// 根
    return x;
  }
  else {
    return *(p+x) = root(*(p+x)); // 経路圧縮
  }
}

void unite(int x, int y){
  x = root(x);
  y = root(y);
  if (x == y){}
  else{
    *(p+x) = y;     //xの親をyの親にする
  }
}

int same(int x, int y){
  return root(x) == root(y);
}

