	heap q;
	vector<typename heap::np> node(e.size(), nullptr);
	q.push(0, start);
	while (!q.empty()) {
		auto a = q.top(); q.pop();
		if (used[a.second]) continue;
		used[a.second] = true;
		res += a.first;
		for (auto& p : e[a.second]) {
			if (p.w == INF_COST) continue;
			if (!used[p.to]) {
				if (!node[p.to]) node[p.to] = q.push(p.w, p.to);
				q.increase_key(node[p.to], p.w);
			}
		}
	}
	return res;
}
