ll prim(vec<vec<pea>> &c) {
	ll sum = 0;
	ll n = c.size();
	vec<bool> seen(n, false);

	ll count = 1;
	seen[0] = true;
	yuque<pea> hen;
	rep(i, 0, c[0].size())hen.push({ -c[0][i].f,c[0][i].s });

	while (count != n) {
		pea k = hen.top(); hen.pop();
		while (seen[k.s]) {
			k = hen.top();
			hen.pop();
		}

		sum -= k.f;
		count++;
		seen[k.s] = true;
		rep(i, 0, c[k.s].size())hen.push({ -c[k.s][i].f,c[k.s][i].s });
	}

	return sum;
}
