class Disjointset {
public:
	vector<int> rank, p;
	Disjointset(int n) {
		rank.resize(n, 0);
		for (int i = 0; i < n; i++)
			p.push_back(i);
	}
	int find(int x) {
		if (x != p[x])
			return p[x] = find(p[x]);
		else return x;
	}
	bool same(int x, int y) {
		return find(x) == find(y);
	}
	void unite(int x, int y) {
		int px = find(x);
		int py = find(y);
		if (rank[px] > rank[py]) {
			p[py] = px;
		}
		else {
			p[px] = py;
			if (rank[px] == rank[py]) rank[py]++;
		}
	}
};
class Edge {
public:
	int fr, to, co;
	Edge(int f, int t, int c):fr(f), to(t), co(c) {}
	bool operator < (const Edge &e) const{
		return co > e.co;
	}
};
int main() {
	int n, e;
	cin >> n >> e;
	priority_queue <Edge> q;
	for (int i = 0; i < e; i++) {
		int s, t, w;
		cin >> s >> t >> w;
		Edge ed(s, t, w);
		q.push(ed);
	}
	Disjointset d(n);
	int sum = 0;
	while (!q.empty()) {
		Edge e = q.top(); q.pop();
		if (d.same(e.fr, e.to)) continue;
		else {
			d.unite(e.fr, e.to);
			sum += e.co;
		}
	}
