			if (!disjointset.same(edges[i].u, edges[i].v))//把合适的点添加到最小生成树中，如果两个点都在最小生成树中，他们相连接就会成环
			{
				TotalCost += edges[i].value;
				disjointset.unite(edges[i].u, edges[i].v);
			}
		}
		return TotalCost;
	}

};
