class UnionFind {
public:
    vector<int> par, rank;
    UnionFind(int n) {
        par.resize(n), rank.resize(n);
        for (int i = 0; i < n; i++) par[i] = i;
    }
    int root(int a) {
        if (par[a] == a) return a;
        else return par[a] = root(par[a]);
    }
    bool isConnect(int a, int b) { return root(a) == root(b); }
    void connect(int a, int b) {
        a = root(a);
        b = root(b);
        if (a == b) return;
        if (rank[a] < rank[b]) {
            par[a] = b;
        } else {
            par[b] = a;
            if (rank[a] == rank[b]) rank[a]++;
        }
    }
};

template<class T = int>
T kruskal(vector<Edge> &edges, int V) {
    sort(edges.begin(), edges.end(), [](const Edge &a, const Edge &b) {
        return a.cost < b.cost;
    });
    UnionFind uf(V);
    T res = 0;
    for(auto &e : edges) {
        if(uf.isConnect(e.from, e.to)) continue;
        uf.connect(e.from, e.to);
        res += e.cost;
    }
    return res;
}

