struct UnionFind {
    UnionFind() {}
    UnionFind(int n) {
        resize(n);
    }

    void resize(int n) {
        par.resize(n, -1);
    }

    int root(int x) {
        if (par[x] < 0) return x;
        return par[x] = root(par[x]);
    }

    bool merge(int x, int y) {
        int rx = root(x);
        int ry = root(y);
        if (rx == ry) return false;
        if (par[rx] > par[ry]) swap(rx, ry);
        par[rx] += par[ry];
        par[ry] = rx;
        return true;
    }

    bool is_same(int x, int y) {
        return (root(x) == root(y));
    }

    int size(int x) {
        return -par[root(x)];
    }

private:
    vector<int> par;
};

template<class T>
struct MinimumSpanningTree {
    MinimumSpanningTree() {}
    MinimumSpanningTree(int n) {
        vertex_count = n;
    }

    void resize(int n) {
        vertex_count = n;
    }

    void add_edge(int from, int to, T cost) {
        edges.emplace_back((Edge){from, to, cost});
    }

    T get_total_cost() {
        sort(edges.begin(), edges.end(), [&](const Edge &a, const Edge &b) {
            return a.cost < b.cost;
        });
        UnionFind uf(vertex_count);
        T ans = 0;
        for (int i = 0, lc = (int)edges.size(); i < lc; i++) {
            if (uf.is_same(edges[i].from, edges[i].to)) continue;
            uf.merge(edges[i].from, edges[i].to);
            ans = ans + edges[i].cost;
        }
        return ans;
    }

private:
    struct Edge {
        int from, to;
        T cost;
    };

    int vertex_count = 0;
    vector<Edge> edges;
};

