class UnionFind{
public:
    UnionFind(){}
    UnionFind(int n){init(n);}
    void init(int n){
        REP(i, n){
            parent[i] = i;
            rank[i] = 0;
        }
    }
    int find(int v){
        if(parent[v] == v){return v;}
        return parent[v] = find(parent[v]);
    }
    void unite(int x, int y){
        x = find(x);
        y = find(y);
        if(x == y){return;}
        if(rank[x] > rank[y]){
            parent[y] = x;
        }else{
            parent[x] = y;
            if(rank[x] == rank[y]){rank[y]++;}
        }
    }
    bool same(int x, int y){
        return find(x) == find(y);
    }
private:
    int parent[MAX_V], rank[MAX_V];
};

