int root(vector<int> &par, int x) {
  if (par[x] == x) {
    return x;
  }
  else {
    return par[x] = root(par, par[x]);
  }
}

bool same(vector<int> &par, int x, int y) {
  return root(par, x) == root(par, y);
}

void unite(vector<int> &par, int x, int y) {
  int rootx = root(par, x);
  int rooty = root(par, y);

  if (rootx == rooty) {
    return;
  }
  else {
    par[rootx] = rooty;
  }
}

