template<class T,class E,class F,class C>
inline T kruscal(edgeset<E> &graph,T id){
	int e=graph.esize();
	E *t=new E[e];
	for(int i=0;i<e;++i) t[i]=graph[i];
	C cmp;
	std::sort(t,t+e,cmp);
	unionfind s(graph.vsize());
	F appf;
	T ans=id;
	for(int i=0;i<e;++i){
		if(!s.same(t[i].start,t[i].end)){
			ans=appf(t[i].wgt,ans);
			s.unite(t[i].start,t[i].end);
		}
		if(s.group()==1) break;
	}
	return ans;
}

