inline void unionfind::unite(int ndx,int ndy){
	ndx=find(ndx);
	ndy=find(ndy);
	if(ndx==ndy) return;
	if(par[ndx]>par[ndy]){
		par[ndy]+=par[ndx];
		par[ndx]=ndy;
	}
	else{
		par[ndx]+=par[ndy];
		par[ndy]=ndx;
	}
	--grp;
	return;
}
