}

// 初期化
void init(int n){
    int i;

    // create S
    p = (int *)malloc(n*sizeof(int));
    rank = (int *)malloc(n*sizeof(int));

    // make Set
    for(i=0;i<n;i++){
        p[i] = i;
        rank[i]=0;
    }
}

// xとyの属する集合を併合
void unite(int x, int y){
    link(findSet(x),findSet(y));
}

// xとyの属する集合を併合
void link(int x, int y){
    if(rank[x] > rank[y]) p[y] = x;
    else{
        p[x]=y;
        if(rank[x]==rank[y]) rank[y]=rank[x]+1;
    }
}

// 木のrootを求める
int findSet(int x){
    if(x!=p[x]) p[x]=findSet(p[x]);
    return p[x];
}

// xとyが同じ集合に属するか否か
int Same(int x, int y){
    if(findSet(x)==findSet(y)) return 1;
    else return 0;
}

// compare
int comp(const void * e1, const void * e2){
    return ((const edge*)e1)->w - ((const edge*)e2)->w;
}

// クラスカル法
int kuruskal(void){
    int res;
    int i;
    edge e;

    qsort(es,E,sizeof(es[0]),comp); // edge.wの小さい順

    init(V); // Union-Findの初期化

    res=0; // 答え, 辺の重みの総和

    for(i=0;i<E;i++){
        e=es[i];
        if(Same(e.s,e.t)==0){
            unite(e.s,e.t);
            res+=e.w;
        }
    }

    return res;
}

