            return 1;
        }
        memset(AdjacencyMatrix[i],0,sizeof(int)*V);    
    }
//*********************************************************//

    predecessor         = malloc(sizeof(int)*V);
    key                 = malloc(sizeof(int)*V);
    visited             = malloc(sizeof(int)*V);

    if( AdjacencyMatrix == NULL || predecessor == NULL || key == NULL || visited == NULL){
        if(DEBUG)printf("Out Of Memory !!Meow!! \n");
        return 1;
    }
    // 檢查是否記憶體不足 沒辦法全部初始化空間 (理論上不會 如果會的話也太扯了)

