void PrimMST(int start){
    // 此演算法核心 ==>      1. 挑出key 最小的放入MST
    //                      2. 更新visited 代表這個點已經被放入MST
    //                      3. 比較周遭相連的edge 跟 點 ，如果從剛挑出來的key出發會重量比較輕 就設定上去 (更新key[] 與 predecessor[])

    int K;                                                                      // 大寫 K 代表目前被挑選出來的 key 最小的點
    int v = 0;                                                                  // 小寫 v 被初始化成 V (總共幾個點) 用來給迴圈扣 扣到 0 等於所有點都放進MST了
    int X;                                                                      // 大寫 X 代表比較edge的時候，由 K 出發可到達的終點
    key[start] = 0;
    // 到達起點的權重當然是0

    while(v < V){
        if(DEBUG)printf("\n----------------------------\nThe %3dth loop\n",v+1);

        K = Select_Min_Key();
        if(DEBUG)printf("K = %3d\n",K);
        // 步驟一

        visited[K] = 1;
        // 步驟二

        Check_Connected_Edge(K);
        // 步驟三
        if(DEBUG)Print_Support_Matrix();
        v++;
    }
    // 主迴圈

}

int Select_Min_Key(void){
    int min = INT_MAX;
    int min_index;
    int i;
    for(i = 0; i< V; i++){
        if(key[i] < min && visited[i] == false){
            min = key[i];
            min_index = i;
        }
    }
    return min_index;
}

void Check_Connected_Edge(int K){
    int i;

    for (i = 0; i< V; i++){

        if(visited[i] == false){ //挑選出還沒放入MST的點

            if( AdjacencyMatrix[K][i] != 0){ //挑選出與K相連的點

                if(AdjacencyMatrix[K][i] < key[i]){ //如果經由 K 走到 i 的重量 小於 上次紀載的 從任意一個點走向 i 的重量還小  就把這個重量更新上去。 因為最終目標是找出 走到i 最輕的路徑

                    predecessor[i] = K;                         //因為從K 走到 i 最短 所以紀錄下來 (幾乎等同放進MST 只是還沒更新visited 因為還沒確定)
                    key[i] = AdjacencyMatrix[K][i];             //同理 重量也記錄下來

                }

            }

        }
    }

}


void Print_MST(int start){
    int i;

    printf("MST find by Prim :\n");
    printf(" v1 -  v2 : weight\n");

    i = (start+1)%V;
    while(i != start){
        printf("%3d - %3d :%5d\n", predecessor[i],i,AdjacencyMatrix[predecessor[i]][i]);
        i = (++i)%V;
    }

}


