        LinkedList<Edge> edges = (LinkedList<Edge>)list[node];
        Iterator<Edge> it = edges.iterator();
        while(it.hasNext()) {
        	que.add(it.next());
        }
        while(que.isEmpty() == false) {
            Edge edge = que.poll();
            if (visited[edge.t])
                continue;

            visited[edge.t] = true;
            node = edge.t;
            d += edge.w;

            it = ((LinkedList<Edge>)list[node]).iterator(); 
            while(it.hasNext()) {
            	edge = it.next();
            	if (visited[edge.t])
            		continue;
            	que.add(edge);
            }

            count++;
            if (count >= V-1)
                break;
        }
        System.out.println(d);
    }
}

