public class Main {
    private ArrayList<ArrayList<Edge>> graph;
    public static void main(String[] args) throws Exception {
        new Main().solve();
    }

    //Prim's Algorithm
    private void solve() throws Exception{
        FastScanner scanner = new FastScanner(System.in);

        int V = scanner.nextInt();
        int E = scanner.nextInt();

        graph = new ArrayList<>(V);
        for(int i = 0; i < V; ++i){
            graph.add(new ArrayList<Edge>());
        }

        for(int i = 0; i < E; ++i){
            int u = scanner.nextInt();
            int v = scanner.nextInt();
            int w = scanner.nextInt();

            graph.get(u).add(new Edge(v, w));
            graph.get(v).add(new Edge(u, w));
        }

        PriorityQueue<Edge> queue = new PriorityQueue<>(11, new Comparator<Edge>() {
            @Override
            public int compare(Edge o1, Edge o2) {
                return o1.weight - o2.weight;
            }
        });

        queue.add(new Edge(0, 0));
        boolean[] visited = new boolean[V];
        int total = 0;
        while(!queue.isEmpty()){
            Edge edge = queue.poll();
            int u = edge.v;
            if(visited[u]){
                continue;
            }
            visited[u] = true;
            total += edge.weight;

            for(Edge adj : graph.get(u)){
                if(!visited[adj.v]){
                    queue.add(adj);
                }
            }
        }

        System.out.println(total);
    }

    static class Edge{
        int v;
        int weight;

        public Edge(int v, int weight){
            this.v = v;
            this.weight = weight;
        }
    }

    static class FastScanner {
        private InputStream in;
        private final byte[] buffer = new byte[1024 * 8];
        private int ptr = 0;
        private int buflen = 0;

        public FastScanner(InputStream in){
            this.in = in;
        }

        private boolean hasNextByte() {
            if (ptr < buflen) {
                return true;
            } else {
                ptr = 0;
                try {
                    buflen = in.read(buffer);
                } catch (IOException e) {
                    e.printStackTrace();
                }
                if (buflen <= 0) {
                    return false;
                }
            }
            return true;
        }

        private int readByte() {
            if (hasNextByte()) return buffer[ptr++];
            else return -1;
        }

        private static boolean isPrintableChar(int c) {
            return 33 <= c && c <= 126;
        }

        private void skipUnprintable() {
            while (hasNextByte() && !isPrintableChar(buffer[ptr])) ptr++;
        }

        public boolean hasNext() {
            skipUnprintable();
            return hasNextByte();
        }

        public String next() {
            if (!hasNext()) throw new NoSuchElementException();
            StringBuilder sb = new StringBuilder();
            int b = readByte();
            while (isPrintableChar(b)) {
                sb.appendCodePoint(b);
                b = readByte();
            }
            return sb.toString();
        }

        public long nextLong() {
            return Long.parseLong(next());
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public double nextDouble() {
            return Double.parseDouble(next());
        }
    }
}

import java.util.Comparator;
import java.util.PriorityQueue;
import java.util.Scanner;

public class Main{
	public static void main(String[]args) {
		try(Scanner scan = new Scanner(System.in)){
			int V = scan.nextInt();
			int E = scan.nextInt();
			int[]s = new int [E];
			int[]t= new int [E];
			int[]w = new int [E];
			long goukei = 0;

			final Comparator<Edge> comp = new COMP();
			PriorityQueue<Edge> queue = new PriorityQueue<Edge>(comp);
			UnionfindTree U = new UnionfindTree(V);
			for(int i=0;i<E;i++) {
				s[i] = scan.nextInt();
				t[i] = scan.nextInt();
				w[i] = scan.nextInt();	
				queue.add(new Edge(s[i],t[i],w[i]));	
			}

			while(!queue.isEmpty()) {
				Edge z = queue.poll();
				if(!U.same(z.se, z.to)) {
					U.union(z.se, z.to);
					goukei+=z.we;
				}	
			}

			System.out.println(goukei);

		}
	}


	static class Edge{//辺の保持
		int se;int to;int we;
		Edge(int s,int t,int w){se=s;to=t;we=w;}
	}


	static class COMP implements Comparator<Edge>{	
		public int compare(Edge x,Edge y) {
			if(x.we>y.we) return 1;
			if(x.we<y.we) return -1;
			return 0;
			}
	}

	//unionfind は分割できない以下重要なこと。
/*
 * 繋げていく処理だけを考えるとき，繋げたものだけを考えれば良いので，連結かどうかの判定は簡単
 * 
 * 辺を壊した後にグラフが連結がどうかは，遠くまで見ないと連結かどうかの判定が難しい．
 * 
 * 上記の「難しい」というのは，グラフ上を遠くまで探索して連結かどうかを愚直に調べることのできるのは 
 * DFS，BFS なので，制約が大きいと計算量的に判定が難しい，という意味．
 * 
 * 以上 3 つを考えると意味が分かると思います．繋がっているかどうかの判定は，
 * ここまで見てきた通り，Union-Find 木を使えば簡単にできます
 * （DFS，BFS，ワーシャルフロイド法などでも繋がっているかの判定はできるが，制約が大きくなると計算量的に使えない）．
 * このポイントは，例えば「無向グラフが与えられてその辺を壊し
 * ，連結かどうかの判定」を行うという典型的な問題に対して適用することができます．
 */



//グループを作る、そしてそのグループについてどうなのかという問題に使えるUNIONFIND木
static class UnionfindTree{
	int [] parent;//配列番号＝頂点番号、値＝その点の親の頂点
	int [] rank;//その頂点を根とするグラフの深さの値、独立した頂点をランク１とする


	public UnionfindTree(int size){//size=グループ分けしたい頂点の数の合計
		this.parent = new int[size];
		this.rank = new int[size];
		for(int i = 0;i<size;i++) {
			parent[i] = i;
			rank[i] = 0; //集合の高さ
		}
	}

	public void union(int x, int y) {//計算量　O(logN)パス圧縮してるのでO(1/A(n,n))と相当小さくなる
		int xRoot = find(x);
		int yRoot = find(y);

		//xが属する木の方が大きい場合
		if (rank[xRoot] > rank[yRoot]) { 
			parent[yRoot] = xRoot; //yの親をxに更新 

		} else if(rank[xRoot] < rank[yRoot]) {
			parent[xRoot] = yRoot;

		} else if (xRoot != yRoot){//高さ一緒で同じ値ではない、同じ値は無視していい
			parent[yRoot] = xRoot;
			rank[xRoot]++; //同じ高さの木がルートの子として着くから大きさ++;
		}
	}

	//引数の属する木のルートのidを返す
	public int find(int i) {//計算の工夫パス圧縮、これによりこのメソッドの計算量は  O(logN)  になる。(非自明)
		if (i != parent[i]) {//指定された頂点が根(親)なら無視してそのまま値を返せばいい
			parent[i] = find(parent[i]);//そうでないならその頂点がもつ親の値までいきそこでその値をもらいに行く
		}//それと同時に、指定された頂点のもつ値をそこで保存しておくことで、パス圧縮が行われ計算量が短縮される。
		return parent[i];
	}

	//同じ木に属しているか
	public boolean same(int x, int y) {//計算量O(logN)
		return find(x) == find(y);
	}
}


}

import java.util.Scanner;
import java.util.Set;
import java.util.HashSet;
import java.util.PriorityQueue;

import static java.lang.System.out;

public class Main {
    private static final int INF = (int)1e9;

    static class Vertex {
        int v;
        Set<Integer> vs;

        public Vertex(int v) {
            this.v = v;
            this.vs = new HashSet<>();
        }
    }

    static class Pair {
        int first;
        int second;

        public Pair(int first, int second) {
            this.first = first;
            this.second = second;
        }

        @Override
        public boolean equals(Object other) {
            if (other != null && other instanceof Pair) {
                Pair p = (Pair)other;

                return p.first == first && p.second == second;
            }
            return false;
        }

        @Override
        public int hashCode() {
            int hash = 17;
            hash += hash*31 + first;
            hash += hash*31 + second;

            return hash;
        }
    }

	public static void main(String[] args) {
		try (Scanner in = new Scanner(System.in)) {
            int n = in.nextInt();
            Vertex[] g = new Vertex[n];
            for (int i = 0; i < n; i++)
                g[i] = new Vertex(i);

            int m = in.nextInt();
            int[][] ws = new int[n][n];
            for (int i = 0;i < m; i++) {
                int f = in.nextInt();
                int t = in.nextInt();
                int w = in.nextInt();

                g[f].vs.add(t);
                g[t].vs.add(f);
                ws[f][t] = ws[t][f] = w;
            }

            prim(g, n, ws, 0);
		} catch (Exception ex) {
			throw new RuntimeException(ex);
		}
	}

    private static void prim(Vertex[] g, int n, int[][] ws, int s) {
        int[][] d = new int[n][2];
        for (int i = 0; i < n; i++) {
            d[i][0] = INF;
            d[i][1] = -1;
        }

        d[s][0] = 0;
        d[s][1] = s;
        PriorityQueue<Pair> pq = new PriorityQueue<>((x, y) -> Integer.compare(x.second, y.second));
        pq.add(new Pair(s, 0));

        int[] visited = new int[n];
        while (!pq.isEmpty()) {
            Pair v = pq.poll();

            if (visited[v.first] == 1)
                continue;

            visited[v.first] = 1;
            for (int vv : g[v.first].vs) {
                int nd = ws[v.first][vv];
                if (nd < d[vv][0] && d[v.first][1] != vv) {
                    Pair old = new Pair(vv, d[vv][0]);
                    d[vv][0] = nd;
                    d[vv][1] = v.first;
                    pq.remove(old);
                    pq.add(new Pair(vv, d[vv][0]));
                }
            }
        }

        long mc = 0L;
        for (int i = 0; i < n; i++)
            mc += d[i][0];

        out.printf("%d\n", mc);
    }
}

