import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws Exception {
        new Main().solve();
    }

    private void solve() throws Exception{
        FastScanner scanner = new FastScanner(System.in);

        int V = scanner.nextInt();
        int E = scanner.nextInt();

        int[] parent = new int[V];
        for(int i = 0; i < V; ++i){
            parent[i] = i;
        }

        PriorityQueue<Edge> queue = new PriorityQueue<>(Math.max(1, E), new Comparator<Edge>() {
            @Override
            public int compare(Edge o1, Edge o2) {
                return o1.weight - o2.weight;
            }
        });

        for(int i = 0; i < E; ++i){
            int u = scanner.nextInt();
            int v = scanner.nextInt();
            int w = scanner.nextInt();

            queue.add(new Edge(u, v, w));
        }

        int count = 0;
        int total = 0;
        while(!queue.isEmpty()){
            Edge edge = queue.poll();
            if(union(parent, edge.u, edge.v)){
                ++count;
                total += edge.weight;
                if(count == V - 1){
                    break;
                }
            }
        }

        System.out.println(total);
    }

    private int find(int[] parent, int x){
        int father = parent[x];
        while(father != parent[father]){
            father = parent[father];
        }

        int fa = x;
        while(fa != parent[fa]){
            int temp = parent[fa];
            parent[fa] = father;
            fa = temp;
        }

        return father;
    }

    private boolean union(int[] parent, int x, int y){
        int faX = find(parent, x);
        int faY = find(parent, y);

        if(faX == faY){
            return false;
        }

        parent[faX] = faY;

        return true;
    }

    static class Edge{
        int u;
        int v;
        int weight;

        public Edge(int u, int v, int weight){
            this.u = u;
            this.v = v;
            this.weight = weight;
        }
    }

    static class FastScanner {
        private InputStream in;
        private final byte[] buffer = new byte[1024 * 8];
        private int ptr = 0;
        private int buflen = 0;

        public FastScanner(InputStream in){
            this.in = in;
        }

        private boolean hasNextByte() {
            if (ptr < buflen) {
                return true;
            } else {
                ptr = 0;
                try {
                    buflen = in.read(buffer);
                } catch (IOException e) {
                    e.printStackTrace();
                }
                if (buflen <= 0) {
                    return false;
                }
            }
            return true;
        }

        private int readByte() {
            if (hasNextByte()) return buffer[ptr++];
            else return -1;
        }

        private static boolean isPrintableChar(int c) {
            return 33 <= c && c <= 126;
        }

        private void skipUnprintable() {
            while (hasNextByte() && !isPrintableChar(buffer[ptr])) ptr++;
        }

        public boolean hasNext() {
            skipUnprintable();
            return hasNextByte();
        }

        public String next() {
            if (!hasNext()) throw new NoSuchElementException();
            StringBuilder sb = new StringBuilder();
            int b = readByte();
            while (isPrintableChar(b)) {
                sb.appendCodePoint(b);
                b = readByte();
            }
            return sb.toString();
        }

        public long nextLong() {
            return Long.parseLong(next());
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public double nextDouble() {
            return Double.parseDouble(next());
        }
    }
}

import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int V = Integer.parseInt(sc.next());
        int E = Integer.parseInt(sc.next());
        ArrayList<int[]> edge = new ArrayList<int[]>();
        for (int i=0;i<E;i++) {
            int s = Integer.parseInt(sc.next());
            int t = Integer.parseInt(sc.next());
            int d = Integer.parseInt(sc.next());
            int[] add = {s, t, d};
            edge.add(add);
        }
        Comparator<int[]> comparator = new Comparator<int[]>() {
            @Override
            public int compare(int[] o1, int[] o2) {
                return Integer.compare(o1[2], o2[2]);
            }
        };
        Collections.sort(edge, comparator);

        UnionFind uf = new UnionFind(V);
        long ans = 0L;
        for (int i=0;i<E;i++) {
            if (uf.root(edge.get(i)[0])!=uf.root(edge.get(i)[1])) {
                ans += edge.get(i)[2];
            }
            uf.connect(edge.get(i)[0], edge.get(i)[1]);
        }
        System.out.println(ans);
    }

    static class UnionFind {
        List<Integer> Parent;
        UnionFind(int N) {
            Parent = new ArrayList<Integer>();
            Integer[] values = new Integer[N];
            Arrays.fill(values, -1);
            Parent.addAll(Arrays.asList(values));
        }
        int root(int A) {
            if (Parent.get(A) < 0)
                return A;
            int root = root(Parent.get(A));
            Parent.set(A, root);
            return root;
        }
        int size(int A) {
            return -Parent.get(root(A));
        }

        boolean connect(int A, int B) {
            A = root(A);
            B = root(B);
            if (A == B) {
                return false;
            }

            if (size(A) < size(B)) {
                int temp = A;
                A = B;
                B = temp;
            }

            Parent.set(A, Parent.get(A) + Parent.get(B));
            Parent.set(B, A);

            return true;
        }
    }
}

import java.util.Scanner;
import java.util.Set;
import java.util.HashSet;
import java.util.PriorityQueue;

import static java.lang.System.out;

public class Main {
    private static final int INF = (int)1e9;

    static class Vertex {
        int v;
        Set<Integer> vs;

        public Vertex(int v) {
            this.v = v;
            this.vs = new HashSet<>();
        }
    }

    static class Pair {
        int first;
        int second;

        public Pair(int first, int second) {
            this.first = first;
            this.second = second;
        }

        @Override
        public boolean equals(Object other) {
            if (other != null && other instanceof Pair) {
                Pair p = (Pair)other;

                return p.first == first && p.second == second;
            }
            return false;
        }

        @Override
        public int hashCode() {
            int hash = 17;
            hash += hash*31 + first;
            hash += hash*31 + second;

            return hash;
        }
    }

	public static void main(String[] args) {
		try (Scanner in = new Scanner(System.in)) {
            int n = in.nextInt();
            Vertex[] g = new Vertex[n];
            for (int i = 0; i < n; i++)
                g[i] = new Vertex(i);

            int m = in.nextInt();
            int[][] ws = new int[n][n];
            for (int i = 0;i < m; i++) {
                int f = in.nextInt();
                int t = in.nextInt();
                int w = in.nextInt();

                g[f].vs.add(t);
                g[t].vs.add(f);
                ws[f][t] = ws[t][f] = w;
            }

            prim(g, n, ws, 0);
		} catch (Exception ex) {
			throw new RuntimeException(ex);
		}
	}

    private static void prim(Vertex[] g, int n, int[][] ws, int s) {
        int[][] d = new int[n][2];
        for (int i = 0; i < n; i++) {
            d[i][0] = INF;
            d[i][1] = -1;
        }

        d[s][0] = 0;
        d[s][1] = s;
        PriorityQueue<Pair> pq = new PriorityQueue<>((x, y) -> Integer.compare(x.second, y.second));
        pq.add(new Pair(s, 0));

        int[] visited = new int[n];
        while (!pq.isEmpty()) {
            Pair v = pq.poll();

            if (visited[v.first] == 1)
                continue;

            visited[v.first] = 1;
            for (int vv : g[v.first].vs) {
                int nd = ws[v.first][vv];
                if (nd < d[vv][0] && d[v.first][1] != vv) {
                    Pair old = new Pair(vv, d[vv][0]);
                    d[vv][0] = nd;
                    d[vv][1] = v.first;
                    pq.remove(old);
                    pq.add(new Pair(vv, d[vv][0]));
                }
            }
        }

        long mc = 0L;
        for (int i = 0; i < n; i++)
            mc += d[i][0];

        out.printf("%d\n", mc);
    }
}

