// AOJ GRL_2_A Kruskal O(E log V)
public class Main {

	private static Scanner sc;
	private static Printer pr;

	private static void solve() {
		int v = sc.nextInt();
		int e = sc.nextInt();

		Kruskal kr = new Kruskal(v);
		for (int i = 0; i < e; i++) {
			int s = sc.nextInt();
			int t = sc.nextInt();
			int d = sc.nextInt();
			kr.addEdge(s, t, d);
		}

		pr.println(kr.getSpaningTreeCost());
	}

	// MST by Kruskal O(E logV)
	private static class Kruskal {
		List<Edge> edges;
		int n;

		// Union-Find
		int[] parent;
		int[] rank;

		Kruskal(int n) {
			this.n = n;
			edges = new ArrayList<Edge>();

			// Union-Find
			parent = new int[this.n];
			rank = new int[this.n];
			for (int i = 0; i < this.n; i++) {
				parent[i] = i;
				rank[i] = 0;
			}
		}

		// i, j:0-indexed
		public void addEdge(int i, int j, int c) {
			edges.add(new Edge(i, j, c));
		}

		public long getSpaningTreeCost() {
			Collections.sort(edges);

			long ret = 0;
			for (Edge e : edges) {
				if (!same(e.u, e.v)) {
					ret += e.w;
					unite(e.u, e.v);
				}
			}

			return ret;
		}

		private static class Edge implements Comparable<Edge> {
			int u; // from
			int v; // to
			int w; // cost

			Edge(int u, int v, int w) {
				this.u = u;
				this.v = v;
				this.w = w;
			}

			@Override
			public int compareTo(Edge o) {
				return Integer.compare(this.w, o.w);
			}
		}

		int find(int x) {
			if (parent[x] == x) {
				return x;
			} else {
				return parent[x] = find(parent[x]);
			}
		}

		boolean same(int x, int y) {
			return find(x) == find(y);
		}

		void unite(int x, int y) {
			x = find(x);
			y = find(y);
			if (x != y) {
				if (rank[x] > rank[y]) {
					parent[y] = x;
				} else {
					parent[x] = y;
					if (rank[x] == rank[y]) {
						rank[y]++;
					}
				}
			}

			return;
		}
	}

	// ---------------------------------------------------
	public static void main(String[] args) {
		sc = new Scanner(INPUT == null ? System.in : new ByteArrayInputStream(INPUT.getBytes()));
		pr = new Printer(System.out);

		solve();

//		pr.close();
		pr.flush();
//		sc.close();
	}

	static String INPUT = null;

	@SuppressWarnings("unused")
	private static class Scanner {
		BufferedReader br;

		Scanner (InputStream in) {
			br = new BufferedReader(new InputStreamReader(in));
		}

		private boolean isPrintable(int ch) {
			return ch >= '!' && ch <= '~';
		}

		private boolean isCRLF(int ch) {
			return ch == '\n' || ch == '\r' || ch == -1;
		}

		private int nextPrintable() {
			try {
				int ch;
				while (!isPrintable(ch = br.read())) {
					if (ch == -1) {
						throw new NoSuchElementException();
					}
				}

				return ch;
			} catch (IOException e) {
				throw new NoSuchElementException();
			}
		}

		String next() {
			try {
				int ch = nextPrintable();
				StringBuilder sb = new StringBuilder();
				do {
					sb.appendCodePoint(ch);
				} while (isPrintable(ch = br.read()));

				return sb.toString();
			} catch (IOException e) {
				throw new NoSuchElementException();
			}
		}

		int nextInt() {
			try {
				// parseInt from Integer.parseInt()
				boolean negative = false;
				int res = 0;
				int limit = -Integer.MAX_VALUE;
				int radix = 10;

				int fc = nextPrintable();
				if (fc < '0') {
					if (fc == '-') {
						negative = true;
						limit = Integer.MIN_VALUE;
					} else if (fc != '+') {
						throw new NumberFormatException();
					}
					fc = br.read();
				}
				int multmin = limit / radix;

				int ch = fc;
				do {
					int digit = ch - '0';
					if (digit < 0 || digit >= radix) {
						throw new NumberFormatException();
					}
					if (res < multmin) {
						throw new NumberFormatException();
					}
					res *= radix;
					if (res < limit + digit) {
						throw new NumberFormatException();
					}
					res -= digit;

				} while (isPrintable(ch = br.read()));

				return negative ? res : -res;
			} catch (IOException e) {
				throw new NoSuchElementException();
			}
		}

		long nextLong() {
			try {
				// parseLong from Long.parseLong()
				boolean negative = false;
				long res = 0;
				long limit = -Long.MAX_VALUE;
				int radix = 10;

				int fc = nextPrintable();
				if (fc < '0') {
					if (fc == '-') {
						negative = true;
						limit = Long.MIN_VALUE;
					} else if (fc != '+') {
						throw new NumberFormatException();
					}
					fc = br.read();
				}
				long multmin = limit / radix;

				int ch = fc;
				do {
					int digit = ch - '0';
					if (digit < 0 || digit >= radix) {
						throw new NumberFormatException();
					}
					if (res < multmin) {
						throw new NumberFormatException();
					}
					res *= radix;
					if (res < limit + digit) {
						throw new NumberFormatException();
					}
					res -= digit;

				} while (isPrintable(ch = br.read()));

				return negative ? res : -res;
			} catch (IOException e) {
				throw new NoSuchElementException();
			}
		}

		float nextFloat() {
			return Float.parseFloat(next());
		}

		double nextDouble() {
			return Double.parseDouble(next());
		}

		String nextLine() {
			try {
				int ch;
				while (isCRLF(ch = br.read())) {
					if (ch == -1) {
						throw new NoSuchElementException();
					}
				}
				StringBuilder sb = new StringBuilder();
				do {
					sb.appendCodePoint(ch);
				} while (!isCRLF(ch = br.read()));

				return sb.toString();
			} catch (IOException e) {
				throw new NoSuchElementException();
			}
		}

		void close() {
			try {
				br.close();
			} catch (IOException e) {
//				throw new NoSuchElementException();
			}
		}
	}

	private static class Printer extends PrintWriter {
		Printer(OutputStream out) {
			super(out);
		}
	}
}

import java.util.*;

class Main {
    public static void main(String[] args) throws Exception {
        Scanner scanner = new Scanner(System.in);
        int V = scanner.nextInt();
        int E = scanner.nextInt();

        boolean[] visited = new boolean[V];
        HashMap<Integer, List<int[]>> graph = new HashMap<>(V);
        for(int i = 0; i < V; ++i){
            graph.put(i, new LinkedList<int[]>());
        }

        for(int i = 0; i < E; ++i){
            int x = scanner.nextInt();
            int y = scanner.nextInt();
            int weight = scanner.nextInt();

            graph.get(x).add(new int[] {y, weight});
            graph.get(y).add(new int[] {x, weight});
        }

        PriorityQueue<int[]> queue = new PriorityQueue<>(new Comparator<int[]>() {
            @Override
            public int compare(int[] o1, int[] o2) {
                return o1[1] - o2[1];
            }
        });

        queue.offer(new int[]{0, 0});
        long minCost = 0;

        while(!queue.isEmpty()){
            int[] edge = queue.poll();
            if(visited[edge[0]]){
                continue;
            }

            visited[edge[0]] = true;
            minCost += edge[1];

            for(int[] adj : graph.get(edge[0])){
                if(!visited[adj[0]]){
                    queue.offer(adj);
                }
            }
        }

        System.out.println(minCost);
    }
}

import java.util.*;

class Main {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        int v = in.nextInt();
        int e = in.nextInt();
        Prim prim = new Prim(v);
        for (int i = 0; i < e; i++) {
            int a = in.nextInt();
            int b = in.nextInt();
            int w = in.nextInt();

            prim.addEdge(a, b, w);
        }

        ArrayList<Triplet> mst = prim.getMinimumSpanningTree();
        int sum = 0;
        for (Triplet edge: mst)
            sum += edge.w;
        System.out.println(sum);
    }
}

class Prim {
    private int size;
    private ArrayList<ArrayList<Triplet>> adl;

    public Prim(int size) {
        this.size = size;
        adl = new ArrayList<>();
        for (int i = 0; i < size; i++)
        	adl.add(new ArrayList<>());
    }

    public void addEdge(int u, int v, int w) {
    	adl.get(u).add(new Triplet(u, v, w));
    	adl.get(v).add(new Triplet(v, u, w));
    }

    public ArrayList<Triplet> getMinimumSpanningTree() {
    	ArrayList<Triplet> mst = new ArrayList<>();
    	PriorityQueue<Triplet> nearest = new PriorityQueue<>((a, b) -> a.w - b.w);
    	boolean[] visit = new boolean[this.size];

    	nearest.offer(new Triplet(-1, 0, 0));
    	while (nearest.size() > 0) {
    		Triplet cur = nearest.poll();
    		if (visit[cur.v])
    			continue;

    		visit[cur.v] = true;
    		if (cur.u != -1)
	    		mst.add(cur);

    		for (Triplet ng: this.adl.get(cur.v))
    			nearest.offer(ng);
    	}
    	return mst;
    }
}

class Triplet {
    public int u;
    public int v;
    public int w;

    public Triplet(int u, int v, int w) {
        this.u = u;
        this.v = v;
        this.w = w;
    }

    public String toString() {
        return "("
                + Integer.toString(u) + ", "
                + Integer.toString(v) + ", "
                + Integer.toString(w) + ")";
    }
}

