				for (Edge e : edges)
					if (!visited[e.to])
						pq.offer(e);

				visited[edge.to] = true;
				sum += edge.cost;
				nodesVisited++;

			}
		}

		// Check if MST spans entire graph
		if (nodesVisited == n)
			return sum;
		return null;

	}

