	{
		long S = System.currentTimeMillis();
		is = INPUT.isEmpty() ? System.in : new ByteArrayInputStream(INPUT.getBytes());
		out = new PrintWriter(System.out);

		solve();
		out.flush();
		long G = System.currentTimeMillis();
		tr(G-S+"ms");
	}

	private static boolean eof()
	{
		if(lenbuf == -1)return true;
		int lptr = ptrbuf;
		while(lptr < lenbuf)if(!isSpaceChar(inbuf[lptr++]))return false;

		try {
			is.mark(1000);
			while(true){
				int b = is.read();
				if(b == -1){
					is.reset();
					return true;
				}else if(!isSpaceChar(b)){
					is.reset();
					return false;
				}
			}
		} catch (IOException e) {
			return true;
		}
	}

	private static byte[] inbuf = new byte[1024];
	static int lenbuf = 0, ptrbuf = 0;

	private static int readByte()
	{
		if(lenbuf == -1)throw new InputMismatchException();
		if(ptrbuf >= lenbuf){
			ptrbuf = 0;
			try { lenbuf = is.read(inbuf); } catch (IOException e) { throw new InputMismatchException(); }
			if(lenbuf <= 0)return -1;
		}
		return inbuf[ptrbuf++];
	}

	private static boolean isSpaceChar(int c) { return !(c >= 33 && c <= 126); }
	//	private static boolean isSpaceChar(int c) { return !(c >= 32 && c <= 126); }
	private static int skip() { int b; while((b = readByte()) != -1 && isSpaceChar(b)); return b; }

	private static double nd() { return Double.parseDouble(ns()); }
	private static char nc() { return (char)skip(); }

	private static String ns()
	{
		int b = skip();
		StringBuilder sb = new StringBuilder();
		while(!(isSpaceChar(b))){
			sb.appendCodePoint(b);
			b = readByte();
		}
		return sb.toString();
	}

	private static char[] ns(int n)
	{
		char[] buf = new char[n];
		int b = skip(), p = 0;
		while(p < n && !(isSpaceChar(b))){
			buf[p++] = (char)b;
			b = readByte();
		}
		return n == p ? buf : Arrays.copyOf(buf, p);
	}

	private static char[][] nm(int n, int m)
	{
		char[][] map = new char[n][];
		for(int i = 0;i < n;i++)map[i] = ns(m);
		return map;
	}

	private static int[] na(int n)
	{
		int[] a = new int[n];
		for(int i = 0;i < n;i++)a[i] = ni();
		return a;
	}

	private static int ni()
	{
		int num = 0, b;
		boolean minus = false;
		while((b = readByte()) != -1 && !((b >= '0' && b <= '9') || b == '-'));
		if(b == '-'){
			minus = true;
			b = readByte();
		}

		while(true){
			if(b >= '0' && b <= '9'){
				num = num * 10 + (b - '0');
			}else{
				return minus ? -num : num;
			}
			b = readByte();
		}
	}

	private static long nl()
	{
		long num = 0;
		int b;
		boolean minus = false;
		while((b = readByte()) != -1 && !((b >= '0' && b <= '9') || b == '-'));
		if(b == '-'){
			minus = true;
			b = readByte();
		}

		while(true){
			if(b >= '0' && b <= '9'){
				num = num * 10 + (b - '0');
			}else{
				return minus ? -num : num;
			}
			b = readByte();
		}
	}

	private static void tr(Object... o) { if(INPUT.length() != 0)System.out.println(Arrays.deepToString(o)); }
}

import java.io.OutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.HashSet;
import java.util.Objects;
import java.util.AbstractCollection;
import java.util.PriorityQueue;
import java.util.Map;
import java.util.Scanner;
import java.util.Set;
import java.util.HashMap;

/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        Scanner in = new Scanner(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        AizuMST solver = new AizuMST();
        solver.solve(1, in, out);
        out.close();
    }

    static class AizuMST {
        public void solve(int testNumber, Scanner in, PrintWriter out) {
            int n = in.nextInt();
            int m = in.nextInt();

            final AizuMST.Vertex[] g = new AizuMST.Vertex[n];
            for (int i = 0; i < n; i++) {
                g[i] = new AizuMST.Vertex();
            }

            Map<AizuMST.Edge, Integer> weights = new HashMap<>();
            for (int j = 0; j < m; j++) {
                int f = in.nextInt();
                int t = in.nextInt();
                int w = in.nextInt();

                g[f].vs.add(t);
                g[t].vs.add(f);
                weights.put(new AizuMST.Edge(f, t, w), w);
                weights.put(new AizuMST.Edge(t, f, w), w);
            }

            out.printf("%d\n", prims(g, 0, weights));
        }

        private int prims(final AizuMST.Vertex[] g, final int s, final Map<AizuMST.Edge, Integer> weights) {
            Set<Integer> visited = new HashSet<>();
            visited.add(s);

            Set<AizuMST.Edge> mst = new HashSet<>();

            PriorityQueue<AizuMST.Edge> pq = new PriorityQueue<>((x, y) -> Integer.compare(x.weight, y.weight));
            for (int v : g[s].vs) {
                pq.add(new AizuMST.Edge(s, v, weights.get(new AizuMST.Edge(s, v, -1))));
            }

            while (!pq.isEmpty()) {
                final AizuMST.Edge e = pq.poll();

                if (visited.contains(e.to)) {
                    continue;
                }

                visited.add(e.to);
                for (int vv : g[e.to].vs) {
                    pq.add(new AizuMST.Edge(e.to, vv, weights.get(new AizuMST.Edge(e.to, vv, -1))));
                }
                mst.add(e);
            }

            int w = 0;
            for (final AizuMST.Edge e : mst) {
                w += e.weight;
            }

            return w;
        }

        static class Vertex {
            Set<Integer> vs;

            Vertex() {
                vs = new HashSet<>();
            }

        }

        static class Edge {
            int from;
            int to;
            int weight;

            Edge(final int from, final int to, final int weight) {
                this.from = from;
                this.to = to;
                this.weight = weight;
            }


            public boolean equals(Object o) {
                if (o == null || !(o instanceof AizuMST.Edge)) {
                    return false;
                }

                final AizuMST.Edge other = (AizuMST.Edge) o;
                return other.from == from && other.to == to ||
                        other.from == to && other.to == from;
            }


            public int hashCode() {
                return Objects.hash(from, to);
            }

        }

    }
}

import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.List;
import java.util.Scanner;

public class Main {

    public static void main(String[] args) {
        Scanner scan = new Scanner(System.in);
        int v = Integer.parseInt(scan.next());
        int e = Integer.parseInt(scan.next());
        List<Edge> edgeList = new ArrayList<Edge>(e);
        for (int i = 0; i < e; i++) {
            int s = Integer.parseInt(scan.next());
            int t = Integer.parseInt(scan.next());
            int w = Integer.parseInt(scan.next());
            edgeList.add(new Edge(s, t, w));
        }
        scan.close();

        Collections.sort(edgeList, new Comparator<Edge>() {
            @Override
            public int compare(Edge o1, Edge o2) {
                if (o1.w != o2.w) {
                    return o1.w - o2.w;
                }
                if (o1.s != o2.s) {
                    return o1.s - o2.s;
                }
                return o1.t - o2.t;
            }
        });

        UnionFind uf = new UnionFind(v);
        long ans = 0;
        for (Edge edge : edgeList) {
            if (!uf.isSameParent(edge.s, edge.t)) {
                uf.union(edge.s, edge.t);
                ans += edge.w;
            }
        }

        System.out.println(ans);
    }

    static class Edge {
        int s;
        int t;
        int w;

        public Edge(int s, int t, int w) {
            this.s = s;
            this.t = t;
            this.w = w;
        }

    }

    static class UnionFind {
        int[] elements;

        public UnionFind(int elementsCount) {
            elements = new int[elementsCount];
            for (int i = 0; i < elementsCount; i++) {
                elements[i] = i;
            }
        }

        public void union(int x, int y) {
            elements[getParent(y)] = getParent(x);
        }

        public boolean isSameParent(int x, int y) {
            return getParent(x) == getParent(y);
        }

        public int getParent(int x) {
            int parent = elements[x];
            if (x != parent) {
                elements[x] = getParent(parent);
            }
            return elements[x];
        }
    }

}

