			int t = sc.nextInt();
			int w = sc.nextInt();
			matrix[s][t] = w;
			matrix[t][s] = w;
		}
		solve(V, E, matrix);
	}

	public static void solve(int V, int E, int[][] matrix) {
		boolean[] visited = new boolean[V];
		PriorityQueue<Edge> que = new PriorityQueue<Edge>(E, new Comparator<Edge>() {
			@Override
			public int compare(Edge o1, Edge o2) {
				return o1.w - o2.w;
			}
		});

		int node = 0;
		visited[node] = true;
		int d = 0;
		int count = 0;
		for (int i = 0; i < V; i++) {
			if (matrix[node][i] > 0) {
				que.add(new Edge(node, i, matrix[node][i]));
			}
		}
		while(que.isEmpty() == false) {
			Edge edge = que.poll();
			if (visited[edge.t]) 
				continue;

			visited[edge.t] = true;
			node = edge.t;
			d += edge.w;

			for (int i = 0; i < V; i++) {
				if (matrix[node][i] > 0 && !visited[i]) {
					que.add(new Edge(node, i, matrix[node][i]));
				}
			}
			count++;
			if (count >= V-1)
				break;
		}
		System.out.println(d);
	}
}

