    static class Task {
        int N, M;

        void solve(InputReader in, PrintWriter out) {
            N = in.nextInt();
            M = in.nextInt();

            Kruskal ksk = new Kruskal(N);

            for (int i = 0; i < M; ++i) {
                int u = in.nextInt();
