	}
	static void add(List<Edge>[] node, int from, int to, int cost){
		Edge e = Edge.make(from, to, cost);
		node[from].add(e);
		node[to].add(e.rev);
	}
	static Edge make(int from, int to, int cost){
		Edge se = new Edge(to, cost);
		Edge te = new Edge(from, cost);
		se.rev = te;
		te.rev = se;
		return se;
	}
	@Override
	public int compareTo(Edge o) {
		return Integer.compare(c, o.c);
	}
}

