		E = sc.nextInt();
		// 隣接リストの作成
		for(int i = 0; i < E; i++) {
			int s = sc.nextInt();
			int v = sc.nextInt();
			int w = sc.nextInt();
			// s -> v
			if(adj.containsKey(s)) {
				int[]pair = {v, w};
				adj.get(s).add(pair);
			}else {
				List<int[]> list = new ArrayList<int[]>();
				int[]pair = {v, w};
				list.add(pair);
				adj.put(s, list);
			}
			// v -> s
			if(adj.containsKey(v)) {
				int[]pair = {s, w};
				adj.get(v).add(pair);
			}else {
				List<int[]> list = new ArrayList<int[]>();
				int[]pair = {s, w};
				list.add(pair);
				adj.put(v, list);
			}
		}
