import java.math.*;

public class Main {

	static final Scanner in = new Scanner(System.in);
	static final PrintWriter out = new PrintWriter(System.out,false);
	static boolean debug = false;

	static int prim(int[][] g) {
		int n = g.length;
		BitSet used = new BitSet();
		int[] cost = new int[n];
		Arrays.fill(cost, 1<<29);
		int res = 0;
		cost[0] = 0;

		while(true) {
			int v = -1;
			for (int i=0; i<n; i++) {
				if (!used.get(i) && (v == -1 || cost[i] < cost[v])) v = i;
			}

			if (v == -1) break;
			used.set(v);
			res += cost[v];
			for (int i=0; i<n; i++) {
				cost[i] = Math.min(cost[i], g[v][i]);
			}
		}

		return res;
	}

	static void solve() {
		int v = in.nextInt();
		int e = in.nextInt();
		int[][] g = new int[v][v];
		for (int i=0; i<v; i++) {
			Arrays.fill(g[i], 1<<29);
		}
		for (int i=0; i<e; i++) {
			int s = in.nextInt();
			int t = in.nextInt();
			int w = in.nextInt();
			g[s][t] = g[t][s] = w;
		}
		out.println(prim(g));
	}

	public static void main(String[] args) {
		debug = args.length > 0;
		long start = System.nanoTime();

		solve();
		out.flush();

		long end = System.nanoTime();
		dump((end - start) / 1000000 + " ms");
		in.close();
		out.close();
	}

	static void dump(Object... o) { if (debug) System.err.println(Arrays.deepToString(o)); }
}

import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.NoSuchElementException;
import java.util.*;

public class Main {
    ArrayList<Edge>[] graph;
    int V, E;

    private class Edge implements Comparable<Edge> {
        int to, cost;
        public Edge(int to, int cost) {
            this.to = to;
            this.cost = cost;
        }

        public int compareTo(Edge e) {
            return this.cost - e.cost;
        }
    }

    @SuppressWarnings("unchecked")
    public void solve() {
        V = nextInt();
        E = nextInt();
        graph = new ArrayList[V];
        for(int i = 0; i < V; i++) {
            graph[i] = new ArrayList<Edge>();
        }
        for(int i = 0; i < E; i++) {
            int s = nextInt();
            int t = nextInt();
            int w = nextInt();

            graph[s].add(new Edge(t, w));
            graph[t].add(new Edge(s, w));
        }

        int num = 1;
        int sum = 0;
        boolean[] used = new boolean[V];
        used[0] = true;
        PriorityQueue<Edge> pq = new PriorityQueue<Edge>();
        for(Edge e : graph[0]) {
            pq.add(e);
        }

        while(pq.size() > 0) {
            Edge e = pq.poll();
            if(used[e.to]) continue;
            used[e.to] = true;
            num++;
            sum += e.cost;
            if(num == V) break;
            for(Edge next : graph[e.to]) {
                if(used[next.to]) continue;
                pq.add(next);
            }
        }

        out.println(sum);
    }

    public static void main(String[] args) {
        out.flush();
        new Main().solve();
        out.close();
    }

    //Input
    private static final InputStream in = System.in;
    private static final PrintWriter out = new PrintWriter(System.out);
    private final byte[] buffer = new byte[2048];
    private int p = 0;
    private int buflen = 0;

    private boolean hasNextByte() {
        if(p < buflen)
            return true;
        p = 0;
        try {
            buflen = in.read(buffer);
        }catch(IOException e) {
            e.printStackTrace();
        }
        if(buflen <= 0)
            return false;

        return true;
    }

    public boolean hasNext() {
        while(hasNextByte() && !isPrint(buffer[p])) {
            p++;
        }
        return hasNextByte();
    }

    private boolean isPrint(int ch) {
        if(ch >= '!' && ch <= '~')
            return true;

        return false;
    }

    private int nextByte() {
        if(!hasNextByte())
            return -1;

        return buffer[p++];
    }

    public String next() {
        if(!hasNext())
            throw new NoSuchElementException();
        StringBuilder sb = new StringBuilder();
        int b = -1;
        while(isPrint((b = nextByte()))) {
            sb.appendCodePoint(b);
        }
        return sb.toString();
    }
    public int nextInt() {
        return Integer.parseInt(next());
    }

    public long nextLong() {
        return Long.parseLong(next());
    }

    public double nextDouble() {
        return Double.parseDouble(next());
    }
}

import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws Exception {
        new Main().solve();
    }

    private void solve() throws Exception{
        FastScanner scanner = new FastScanner(System.in);

        int V = scanner.nextInt();
        int E = scanner.nextInt();

        int[] parent = new int[V];
        for(int i = 0; i < V; ++i){
            parent[i] = i;
        }

        Edge[] edges = new Edge[E];
        for(int i = 0; i < E; ++i){
            int u = scanner.nextInt();
            int v = scanner.nextInt();
            int w = scanner.nextInt();

            edges[i] = new Edge(u, v, w);
        }

        Arrays.parallelSort(edges, new Comparator<Edge>() {
            @Override
            public int compare(Edge o1, Edge o2) {
                return o1.weight - o2.weight;
            }
        });

        int count = 0;
        int total = 0;
        for(int i = 0; i < E; ++i){
            Edge edge = edges[i];
            if(union(parent, edge.u, edge.v)){
                ++count;
                total += edge.weight;

                if(count == V - 1){
                    break;
                }
            }
        }

        System.out.println(total);
    }

    private int find(int[] parent, int x){
        int father = parent[x];
        while(father != parent[father]){
            father = parent[father];
        }

        int fa = x;
        while(fa != parent[fa]){
            int temp = parent[fa];
            parent[fa] = father;
            fa = temp;
        }

        return father;
    }

    private boolean union(int[] parent, int x, int y){
        int faX = find(parent, x);
        int faY = find(parent, y);

        if(faX == faY){
            return false;
        }

        parent[faX] = faY;

        return true;
    }

    static class Edge{
        int u;
        int v;
        int weight;

        public Edge(int u, int v, int weight){
            this.u = u;
            this.v = v;
            this.weight = weight;
        }
    }

    static class FastScanner {
        private InputStream in;
        private final byte[] buffer = new byte[1024 * 8];
        private int ptr = 0;
        private int buflen = 0;

        public FastScanner(InputStream in){
            this.in = in;
        }

        private boolean hasNextByte() {
            if (ptr < buflen) {
                return true;
            } else {
                ptr = 0;
                try {
                    buflen = in.read(buffer);
                } catch (IOException e) {
                    e.printStackTrace();
                }
                if (buflen <= 0) {
                    return false;
                }
            }
            return true;
        }

        private int readByte() {
            if (hasNextByte()) return buffer[ptr++];
            else return -1;
        }

        private static boolean isPrintableChar(int c) {
            return 33 <= c && c <= 126;
        }

        private void skipUnprintable() {
            while (hasNextByte() && !isPrintableChar(buffer[ptr])) ptr++;
        }

        public boolean hasNext() {
            skipUnprintable();
            return hasNextByte();
        }

        public String next() {
            if (!hasNext()) throw new NoSuchElementException();
            StringBuilder sb = new StringBuilder();
            int b = readByte();
            while (isPrintableChar(b)) {
                sb.appendCodePoint(b);
                b = readByte();
            }
            return sb.toString();
        }

        public long nextLong() {
            return Long.parseLong(next());
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public double nextDouble() {
            return Double.parseDouble(next());
        }
    }
}

