class Kraskal {
	int vnum;
	ArrayList<WEdge2> elist;

	public Kraskal(int vnum){
		this.vnum = vnum;
		elist = new ArrayList<>();
	}

	void addEdge(int u, int v, int w){
		elist.add(new WEdge2(u,v,w));
	}

	//クラスカル法で最小全域木を求める
	ArrayList<WEdge2> KraskalTree(){		
		//UFT
		class UFT{
			int[] par;
			int[] rank;

			public UFT(int n){
				par = new int[n];
				rank = new int[n];

				for(int i=0;i<n;i++){
					par[i] = i;
				}
			}

			//木の根を求める
			public int find(int x){
				if(par[x] == x){
					return x;
				}
				else{
					return par[x] = find(par[x]);
				}
			}

			//xとyの属する集合を併合
			void unite(int x, int y){
				int px = find(x);
				int py = find(y);

				if(px == py){
					return;
				}
				else if(rank[px] < rank[py]){
					par[px] = py;

				}
				else{
					par[py] = px;
					if(rank[px]==rank[py]){
						rank[px]++;
					}
				}

			}

			//xとyが同じ集合に属するか
			boolean isEquivalent(int x, int y){
				return find(x) == find(y);
			}
		}

		PriorityQueue<WEdge2> s = new PriorityQueue<>();
		s.addAll(elist);
		ArrayList<WEdge2> forest = new ArrayList<>();
		UFT uft = new UFT(vnum);

		while(!s.isEmpty()){
			WEdge2 now = s.poll();

			if(!uft.isEquivalent(now.u,now.v)){
				forest.add(now);
				uft.unite(now.u, now.v);
			}
		}

		return forest;
	}

	//クラスカル法で最小全域木の重みの和を求める
	long KraskalWeight(){		
		//UFT
		class UFT{
			int[] par;
			int[] rank;

			public UFT(int n){
				par = new int[n];
				rank = new int[n];

				for(int i=0;i<n;i++){
					par[i] = i;
				}
			}

			//木の根を求める
			public int find(int x){
				if(par[x] == x){
					return x;
				}
				else{
					return par[x] = find(par[x]);
				}
			}

			//xとyの属する集合を併合
			void unite(int x, int y){
				int px = find(x);
				int py = find(y);

				if(px == py){
					return;
				}
				else if(rank[px] < rank[py]){
					par[px] = py;

				}
				else{
					par[py] = px;
					if(rank[px]==rank[py]){
						rank[px]++;
					}
				}

			}

			//xとyが同じ集合に属するか
			boolean isEquivalent(int x, int y){
				return find(x) == find(y);
			}
		}

		PriorityQueue<WEdge2> s = new PriorityQueue<>();
		s.addAll(elist);
		UFT uft = new UFT(vnum);
		long sum = 0;

		while(!s.isEmpty()){
			WEdge2 now = s.poll();

			if(!uft.isEquivalent(now.u,now.v)){
				sum += now.w;
				uft.unite(now.u, now.v);
			}
		}

		return sum;
	}

	class WEdge2 implements Comparable<WEdge2>{
		int u;
		int v;
		int w;

		public WEdge2(int u, int v, int w){
			this.u = u;
			this.v = v;
			this.w = w;
		}

		@Override
		public int compareTo(WEdge2 o){
			return Integer.compare(w, o.w);
		}
	}
}

class FastScanner {
	private final InputStream in = System.in;
	private final byte[] buffer = new byte[1024];
	private int ptr = 0;
	private int buflen = 0;
	private boolean hasNextByte() {
		if (ptr < buflen) {
			return true;
		} else {
			ptr = 0;
			try {
				buflen = in.read(buffer);
			} catch (IOException e) {
				e.printStackTrace();
			}
			if (buflen <= 0) {
				return false;
			}
		}
		return true;
	}
	private int readByte() {
		if (hasNextByte())
			return buffer[ptr++];
		else
			return -1;
	}
	private static boolean isPrintableChar(int c) {
		return 33 <= c && c <= 126;
	}
	public boolean hasNext() {
		while (hasNextByte() && !isPrintableChar(buffer[ptr]))
			ptr++;
		return hasNextByte();
	}
	public String next() {
		if (!hasNext())
			throw new NoSuchElementException();
		StringBuilder sb = new StringBuilder();
		int b = readByte();
		while (isPrintableChar(b)) {
			sb.appendCodePoint(b);
			b = readByte();
		}
		return sb.toString();
	}
	public long nextLong() {
		if (!hasNext())
			throw new NoSuchElementException();
		long n = 0;
		boolean minus = false;
		int b = readByte();
		if (b == '-') {
			minus = true;
			b = readByte();
		}
		if (b < '0' || '9' < b) {
			throw new NumberFormatException();
		}
		while (true) {
			if ('0' <= b && b <= '9') {
				n *= 10;
				n += b - '0';
			} else if (b == -1 || !isPrintableChar(b)) {
				return minus ? -n : n;
			} else {
				throw new NumberFormatException();
			}
			b = readByte();
		}
	}
	public int nextInt() {
		long nl = nextLong();
		if (nl < Integer.MIN_VALUE || nl > Integer.MAX_VALUE)
			throw new NumberFormatException();
		return (int) nl;
	}
	public double nextDouble() {
		return Double.parseDouble(next());
	}
}

import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws Exception {
        new Main().solve();
    }

    private void solve() throws Exception{
        FastScanner scanner = new FastScanner(System.in);

        int V = scanner.nextInt();
        int E = scanner.nextInt();

        int[] parent = new int[V];
        for(int i = 0; i < V; ++i){
            parent[i] = i;
        }

        Edge[] edges = new Edge[E];
        for(int i = 0; i < E; ++i){
            int u = scanner.nextInt();
            int v = scanner.nextInt();
            int w = scanner.nextInt();

            edges[i] = new Edge(u, v, w);
        }

        Arrays.parallelSort(edges, new Comparator<Edge>() {
            @Override
            public int compare(Edge o1, Edge o2) {
                return o1.weight - o2.weight;
            }
        });

        int count = 0;
        int total = 0;
        for(int i = 0; i < E; ++i){
            Edge edge = edges[i];
            if(union(parent, edge.u, edge.v)){
                ++count;
                total += edge.weight;

                if(count == V - 1){
                    break;
                }
            }
        }

        System.out.println(total);
    }

    private int find(int[] parent, int x){
        int father = parent[x];
        while(father != parent[father]){
            father = parent[father];
        }

        int fa = x;
        while(fa != parent[fa]){
            int temp = parent[fa];
            parent[fa] = father;
            fa = temp;
        }

        return father;
    }

    private boolean union(int[] parent, int x, int y){
        int faX = find(parent, x);
        int faY = find(parent, y);

        if(faX == faY){
            return false;
        }

        parent[faX] = faY;

        return true;
    }

    static class Edge{
        int u;
        int v;
        int weight;

        public Edge(int u, int v, int weight){
            this.u = u;
            this.v = v;
            this.weight = weight;
        }
    }

    static class FastScanner {
        private InputStream in;
        private final byte[] buffer = new byte[1024 * 8];
        private int ptr = 0;
        private int buflen = 0;

        public FastScanner(InputStream in){
            this.in = in;
        }

        private boolean hasNextByte() {
            if (ptr < buflen) {
                return true;
            } else {
                ptr = 0;
                try {
                    buflen = in.read(buffer);
                } catch (IOException e) {
                    e.printStackTrace();
                }
                if (buflen <= 0) {
                    return false;
                }
            }
            return true;
        }

        private int readByte() {
            if (hasNextByte()) return buffer[ptr++];
            else return -1;
        }

        private static boolean isPrintableChar(int c) {
            return 33 <= c && c <= 126;
        }

        private void skipUnprintable() {
            while (hasNextByte() && !isPrintableChar(buffer[ptr])) ptr++;
        }

        public boolean hasNext() {
            skipUnprintable();
            return hasNextByte();
        }

        public String next() {
            if (!hasNext()) throw new NoSuchElementException();
            StringBuilder sb = new StringBuilder();
            int b = readByte();
            while (isPrintableChar(b)) {
                sb.appendCodePoint(b);
                b = readByte();
            }
            return sb.toString();
        }

        public long nextLong() {
            return Long.parseLong(next());
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public double nextDouble() {
            return Double.parseDouble(next());
        }
    }
}

