			graph[b].add(obj.new Edge(b, a, c));

		}
		for (int i = 0; i < cost.length; i++) {
			cost[i] = INFINITY;
		}

	}

	public static void prim() {

		int added = 1;
		int sum = 0;
		visited[0] = true;
		cost[0] = 0;
		PriorityQueue<Edge> pq = new PriorityQueue<Edge>();
		for (Edge e : graph[0]) {
			pq.offer(e);
		}
		while (!pq.isEmpty()) {
			Edge e = pq.poll();
			if (visited[e.to]) {
				continue;
			}

			sum += e.weight;
			added++;
			cost[e.to] = e.weight;
			parent[e.to] = e.from;
			visited[e.to] = true;

			if (added == vertex) {
				break;
