			mstSet[u] = true;

			for(int i=0; i<V; i++){
				if(graph[u][i] != 0 && !mstSet[i] &&
						key[i] > graph[u][i]){
					key[i] = graph[u][i];
				}
			}
			count ++;
		}


		return sum;
	}

	// return min key index;
	private static PairValue minKey(int[] key, boolean[] mstSet){
		int min = Integer.MAX_VALUE;
		int index = -1;

		for(int i=0; i<key.length; i++){
			if(min > key[i] && !mstSet[i]){
				min = key[i];
				index = i;
			}
		}
		return new PairValue(index, min);
	}
