class UnionFind {
    int[] size;
    int[] id;

    public UnionFind(int n) {
        size = new int[n];
        id = new int[n];
        for (int i = 0; i < n; ++i) {
            size[i] = 1;
            id[i] = i;
        }
    }

    void unify(int p, int q) {
        int root1 = find(p);
        int root2 = find(q);

        if (size[root1] > size[root2]) {
            size[root1] += size[root2];
            id[root2] = root1;
        } else {
            size[root2] += size[root1];
            id[root1] = root2;
        }
    }

    int find(int p) {
        int root = p;
        while (root != id[root]) root = id[root];
        while (p != root) {
            int next = id[p];
            id[p] = root;
            p = next;
        }
        return root;
    }

    boolean connected(int p, int q) {
        return find(p) == find(q);
    }
}

class Edge implements Comparable<Edge> {
    int from, to, cost;

    public Edge(int from, int to, int cost) {
        this.from = from;
        this.to = to;
        this.cost = cost;
    }

    @Override
    public int compareTo(Edge o) {
        return cost - o.cost;
    }
}

public class Main {

    static List<Edge> edges;
    static int V, E;

    static int kruskal() {
        int mstCost = 0;
        PriorityQueue<Edge> pq = new PriorityQueue<>(edges);
        UnionFind uf = new UnionFind(V);

        while (!pq.isEmpty()) {
            Edge e = pq.poll();
            if (uf.connected(e.from, e.to)) continue;
            mstCost += e.cost;
            uf.unify(e.from, e.to);
            if (uf.size[uf.find(0)] == V) break;
        }

        return mstCost;
    }

    public static void main(String[] args) {
        FastScanner fs = new FastScanner();
        V = fs.nextInt();
        E = fs.nextInt();
        edges = new ArrayList<>();
        for (int i = 0; i < E; ++i) {
            int a = fs.nextInt();
            int b = fs.nextInt();
            int cost = fs.nextInt();
            edges.add(new Edge(a, b, cost));
        }

        System.out.println(kruskal());
    }
}

class FastScanner {
    private final InputStream in = System.in;
    private final byte[] buffer = new byte[1024];
    private int ptr = 0;
    private int buflen = 0;

    private boolean hasNextByte() {
        if (ptr < buflen) {
            return true;
        }else{
            ptr = 0;
            try {
                buflen = in.read(buffer);
            } catch (IOException e) {
                e.printStackTrace();
            }
            if (buflen <= 0) {
                return false;
            }
        }
        return true;
    }

    private int readByte() { if (hasNextByte()) return buffer[ptr++]; else return -1;}
    private static boolean isPrintableChar(int c) { return 33 <= c && c <= 126;}
    public boolean hasNext() { while(hasNextByte() && !isPrintableChar(buffer[ptr])) ptr++; return hasNextByte();}

    public String next() {
        if (!hasNext()) throw new NoSuchElementException();
        StringBuilder sb = new StringBuilder();
        int b = readByte();
        while(isPrintableChar(b)) {
            sb.appendCodePoint(b);
            b = readByte();
        }
        return sb.toString();
    }

    public long nextLong() {
        if (!hasNext()) throw new NoSuchElementException();
        long n = 0;
        boolean minus = false;
        int b = readByte();
        if (b == '-') {
            minus = true;
            b = readByte();
        }
        if (b < '0' || '9' < b) {
            throw new NumberFormatException();
        }
        while(true){
            if ('0' <= b && b <= '9') {
                n *= 10;
                n += b - '0';
            }else if(b == -1 || !isPrintableChar(b)){
                return minus ? -n : n;
            }else{
                throw new NumberFormatException();
            }
            b = readByte();
        }
    }

    public int nextInt() {
        long nl = nextLong();
        if (nl < Integer.MIN_VALUE || nl > Integer.MAX_VALUE) throw new NumberFormatException();
        return (int) nl;
    }

    public double nextDouble() { return Double.parseDouble(next());}
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

public class Main {

	static BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
	static int vertex;
	static int edge;
	static int[][] graph;
	static int cost[];
	static int parent[];
	static boolean visited[];
	static final int INFINITY = Integer.MAX_VALUE;

	public static void main(String[] args) throws IOException {

		input();
		prim();
	}

	public static void prim() {
		int index = 1;
		for (int i = 1; i < vertex; i++) {
			for (int j = 1; j <= vertex; j++) {
				int weight = graph[index][j];
				if (cost[j] > weight && visited[j] == false && weight != 0) {
					cost[j] = weight;
					parent[j] = index;
				}
			}
			int min = INFINITY;
			for (int k = 1; k < cost.length; k++) {
				if (cost[k] < min && visited[k] == false) {
					min = cost[k];
					index = k;
				}
			}
			visited[index] = true;
		}
		int sum = 0;
		for (int m = 2; m < cost.length; m++) {
			sum += cost[m];
		}
		System.out.println(sum);
	}

	public static void input() throws IOException {
		StringTokenizer st = new StringTokenizer(br.readLine());

		vertex = Integer.parseInt(st.nextToken());
		edge = Integer.parseInt(st.nextToken());
		graph = new int[vertex + 1][vertex + 1];
		cost = new int[vertex + 1];
		parent = new int[vertex + 1];
		visited = new boolean[vertex + 1];
		for (int k = 1; k <= vertex; k++) {
			cost[k] = INFINITY;
		}
		for (int i = 1; i <= edge; i++) {
			st = new StringTokenizer(br.readLine());
			int a = Integer.parseInt(st.nextToken());
			int b = Integer.parseInt(st.nextToken());
			int c = Integer.parseInt(st.nextToken());
			graph[a][b] = graph[b][a] = c;

		}
		cost[1] = 0;
		parent[1] = 1;
		visited[1] = true;

	}
}

