	class Graph: Graph<long> {
		public Graph(int count) : base(count) { }
		public long Prim(out Graph tree, int start = 0) {
			tree = new Graph(N);
			var res = 0L;
			var PQ = new PriorityQueue<Edge<long>>(false);
			var O = Outs;
			PQ.Push(O[start]);
			var picked = new bool[N];
			picked[start] = true;
			while(PQ.Any()) {
				var e = PQ.Pop();
				var w = e.Out;
				if(picked[w]) continue;
				else picked[w] = true;
				res += e.cost;
				tree.Edges.Add(e);
				PQ.Push(O[w]);
			}
			return res;
		}
	}
	class Graph<V> where V : IComparable<V> {
		public int N { get; }
		public Graph(int count) {
			N = count;
			Edges = new List<Edge<V>>();
		}
		public List<Edge<V>> Edges { get; }
		public void AddEdge(int In, int Out, V Value) {
			var e = new Edge<V> { In = In, Out = Out, cost = Value };
			Edges.Add(e);
		}
		protected List<Edge<V>>[] Outs {
			get {
				var Res = new List<Edge<V>>[N];
				for(int i = 0; i < N; i++)
					Res[i] = new List<Edge<V>>();
				foreach(var e in Edges)
					Res[e.In].Add(e);
				return Res;
			}
		}
		protected List<Edge<V>>[] Ins {
			get {
				var Res = new List<Edge<V>>[N];
				for(int i = 0; i < N; i++)
					Res[i] = new List<Edge<V>>();
				foreach(var e in Edges)
					Res[e.Out].Add(e);
				return Res;
			}
		}


