namespace AizuOnline
{
    public class Node
    {
        public int id;
        public bool isPassed = false;
        public int groupId;
        public int cost = int.MaxValue;
        public List<Edge> edges = new List<Edge>();
    }

    public class Edge
    {
        public int id = int.MinValue;
        public int fromId;
        public int toId;
        public int cost;
        public bool isPassed = false;
    }

    internal class Program
    {
        private static void Main(string[] args)
        {
            var nodes = createDirectionNodesByList();
            prim(nodes);
            Console.ReadLine();
        }

        public static void prim(List<Node> nodes)
        {
            var sw = new Stopwatch();
            sw.Start();

            var node = nodes.FirstOrDefault();
            if (node == null)
            {
                return;
            }

            node.cost = 0;

            while (true)
            {
                //Pick up 1 node which is minimum cost from group id 2.
                var mincost = int.MaxValue;
                Node nextNode = null;
                foreach (var n in nodes)
                {
                    if (n.groupId != 1 && n.cost < mincost)
                    {
                        mincost = n.cost;
                        nextNode = n;
                    }
                }

                if (mincost == int.MaxValue)
                {
                    break;
                }
                //Set Group id 1 to picked up node.
                setConnectedEdge(nextNode, nodes);
                nextNode.groupId = 1;

                //Filter Next Nodes connected from group id 1. and set group id 2.
                foreach (var n in nodes.Where(n => n.groupId != 1 && isConnectedNode(n, nextNode)))
                {
                    var edge = nextNode.edges.Where(m => m.toId == n.id || m.fromId == n.id).FirstOrDefault();
                    if (edge == null)
                    {
                        continue;
                    }

                    n.cost = Math.Min(n.cost, edge.cost + nextNode.cost);
                    n.groupId = 2;
                }
            }

            //Console.WriteLine(sw.Elapsed);

            #region output

            var cost = nodes.SelectMany(n => n.edges).Where(n => n.isPassed).Select(n => n.cost).Sum();
            Console.WriteLine(cost);

            #endregion output
        }

        private static void setConnectedEdge(Node nextNode, List<Node> nodes)
        {
            var edge = nodes.Where(n => n.groupId != 1).SelectMany(n => n.edges).Where(n => n.toId == nextNode.id || n.fromId == nextNode.id && !n.isPassed).OrderBy(n => n.cost).FirstOrDefault();
            if (edge != null)
            {
                edge.isPassed = true;
            }
        }

        private static bool isConnectedNode(Node node, Node nextNode)
        {
            return node.edges.Any(n => n.toId == nextNode.id) || nextNode.edges.Any(n => n.toId == node.id);
        }

        /// <summary>
        /// |V| |E| r
        //   s0 t0 d0
        //   s1 t1 d1
        //   :
        //   s|E|???1 t|E|???1 d|E|???1
        /// </summary>
        /// <returns></returns>
        public static List<Node> createDirectionNodesByList()
        {
            #region Node Creation

            var nodes = new List<Node>();
            var x = Console.ReadLine().Split(' ');
            var nodeNum = Convert.ToInt32(x[0]);
            for (int i = 0; i < nodeNum; i++)
            {
                nodes.Add(new Node()
                {
                    id = i
                });
            }

            #endregion Node Creation

            #region Edge Creation

            var edgeNum = Convert.ToInt32(x[1]);
            for (int i = 0; i < edgeNum; i++)
            {
                var p = Console.ReadLine().Split(' ');
                var id = Convert.ToInt32(p[0]);

                var node = nodes.Where(m => m.id == id).FirstOrDefault();

                if (node == null)
                {
                    node = new Node()
                    {
                        id = id
                    };
                    nodes.Add(node);
                }

                node.edges.Add(new Edge()
                {
                    fromId = id,
                    toId = Convert.ToInt32(p[1]),
                    cost = Convert.ToInt32(p[2]),
                });
            }

            #endregion Edge Creation

            return nodes;
        }
    }
}

