        {
            var line = ReadLine().Split(' ').Select(value => int.Parse(value)).ToArray();
            var v = line[0];
            var e = line[1];
            var edges = new List<int[]>();
            for (var i = 0; i < e; i++)
            {
                line = ReadLine().Split(' ').Select(value => int.Parse(value)).ToArray();
                edges.Add(line);
            }
            edges = edges.OrderBy(array => array[2]).ToList();
            var parents = new int[v];
            for(var i = 0; i < v; i++)
            {
                parents[i] = i;
            }

            var cost = 0;
            foreach(var edge in edges)
            {
                if(GetRoot(parents, edge[0]) != GetRoot(parents, edge[1]))
                {
                    cost += edge[2];
                    Unite(parents, edge[0], edge[1]);
                }
            }

            WriteLine(cost);
        }

        private static int GetRoot(int[] parents, int node)
        {
            if (parents[node] == node)
            {
                return node;
            }
            return parents[node] = GetRoot(parents, parents[node]);
        }

        private static void Unite(int[] parents, int x, int y)
        {
            x = GetRoot(parents, x);
            y = GetRoot(parents, y);

            if (x == y)
            {
                return;
            }
            parents[x] = y;
        }
    }
