class MinimumSpanningTree
{
    public Edge[] Input(int m, int indexed = 1, bool cost = true)
    {
        var cin = new Scanner();
        var ret = new Edge[m];
        for (int i = 0; i < m; i++)
        {
            int a = cin.nextint - indexed;
            int b = cin.nextint - indexed;
            var c = cost ? cin.nextlong : 1;
            ret[i] = new Edge(a, b, c);
        }
        Array.Sort(ret);
        return ret;
    }
    public long Run(int n, Edge[] E)
    {
        var U = new DisjointSet(n);
        long ret = 0;
        foreach (var e in E)
        {
            if (U.Unite(e.from, e.to))
            {
                ret += e.cost;
            }
        }
        return ret;
    }
}

