        public class UnionFind
        {
            private class Node
            {
                public Node Parent { get; set; }
                public int Rank { get; set; }
            }

            private Dictionary<object, Node> _dict = new Dictionary<object, Node>();

            private Node Root(object data)
            {
                if (!_dict.ContainsKey(data))
                {
                    var node = new Node();
                    _dict.Add(data, node);
                    return node;
                }
                else
                {
                    var node = _dict[data];
                    return Find(node);
                }
            }

            private Node Find(Node node)
            {
                if (node.Parent == null) return node;
                return node.Parent = Find(node.Parent);
            }

            public void Unite(IComparable x, IComparable y)
            {
                var xRoot = Root(x);
                var yRoot = Root(y);
                if (xRoot == yRoot) return;

                if (xRoot.Rank < yRoot.Rank)
                {
                    xRoot.Parent = yRoot;
                }
                else
                {
                    yRoot.Parent = xRoot;
                    if (xRoot.Rank == yRoot.Rank) xRoot.Rank++;
                }
            }

            public bool IsSameGroup(IComparable x, IComparable y)
            {
                return Root(x) == Root(y);
            }
        }

        public class ComparablePair<T, U> : IComparable where T : IComparable<T>
        {
            public readonly T Item1;
            public readonly U Item2;

            public int CompareTo(object obj)
            {
                ComparablePair<T, U> castedObj = (ComparablePair<T, U>)obj;
                return this.Item1.CompareTo(castedObj.Item1);
            }

            public ComparablePair(T t, U u)
            {
                Item1 = t;
                Item2 = u;
            }
        }

        public class Kruskal
        {
            private class Edge { public int S; public int T; public int C; }

            SortedList<int, Edge> pathSet = new SortedList<int, Edge>();

            public Kruskal()
            {
            }

            public Kruskal(int V)
            {
                pathSet = new SortedList<int, Edge>(V);
            }

            public void AddEdge(int s, int t, int cost)
            {
                var edge = new Edge() { S = s, T = t, C = cost };
                pathSet.Add(cost, edge);
            }

            public int GetCost()
            {
                int ret = 0;
                var unionFind = new UnionFind();

                foreach (var path in pathSet)
                {
                    int cost = path.Key;
                    int vertex1 = path.Value.S;
                    int vertex2 = path.Value.T;

                    if (!unionFind.IsSameGroup(vertex1, vertex2))
                    {
                        unionFind.Unite(vertex1, vertex2);
                        ret += cost;
                    }
                }

                return ret;
            }
        }

        static void Main(string[] args)
        {
            var str = Console.ReadLine().Split();
            var V = Int32.Parse(str[0]);
            var E = Int32.Parse(str[1]);

            var kruskal = new Kruskal();

            for (int l = 0; l < E; l++)
            {
                str = Console.ReadLine().Split(V);
                var s = Int32.Parse(str[0]);
                var t = Int32.Parse(str[1]);
                var d = Int32.Parse(str[2]);
                kruskal.AddEdge(s, t, d);
            }

            var dist = kruskal.GetCost();
            Console.WriteLine(dist);
        }
    }
