using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;

namespace ConsoleApplication1
{
    class Program
    {
        public class UnionFind
        {
            private class Node
            {
                public Node Parent { get; set; }
                public int Rank { get; set; }
            }

            private Dictionary<object, Node> _dict = new Dictionary<object, Node>();

            private Node Root(object data)
            {
                if (!_dict.ContainsKey(data))
                {
                    var node = new Node();
                    _dict.Add(data, node);
                    return node;
                }
                else
                {
                    var node = _dict[data];
                    return Find(node);
                }
            }

            private Node Find(Node node)
            {
                if (node.Parent == null) return node;
                return node.Parent = Find(node.Parent);
            }

            public void Unite(IComparable x, IComparable y)
            {
                var xRoot = Root(x);
                var yRoot = Root(y);
                if (xRoot == yRoot) return;

                if (xRoot.Rank < yRoot.Rank)
                {
                    xRoot.Parent = yRoot;
                }
                else
                {
                    yRoot.Parent = xRoot;
                    if (xRoot.Rank == yRoot.Rank) xRoot.Rank++;
                }
            }

            public bool IsSameGroup(IComparable x, IComparable y)
            {
                return Root(x) == Root(y);
            }
        }

        public class ComparablePair<T, U> : IComparable where T : IComparable<T>
        {
            public readonly T Item1;
            public readonly U Item2;

            public int CompareTo(object obj)
            {
                ComparablePair<T, U> castedObj = (ComparablePair<T, U>)obj;
                return this.Item1.CompareTo(castedObj.Item1);
            }

            public ComparablePair(T t, U u)
            {
                Item1 = t;
                Item2 = u;
            }
        }

        public class Kruskal
        {
            SortedSet<ComparablePair<int, Tuple<int, int>>> pathSet = new SortedSet<ComparablePair<int, Tuple<int, int>>>();

            private int _maxIndex = 1;
            public Kruskal(int maxIndex)
            {
                _maxIndex = maxIndex;
            }

            public void AddPath(int s, int t, int cost)
            {
                var tuple = new Tuple<int, int>(s, t);
                pathSet.Add(new ComparablePair<int, Tuple<int, int>>(cost, tuple));
            }

            public int GetCost()
            {
                int ret = 0;
                var unionFind = new UnionFind();

                foreach (var path in pathSet)
                {
                    int cost = path.Item1;
                    int vertex1 = path.Item2.Item1;
                    int vertex2 = path.Item2.Item2;

                    if (!unionFind.IsSameGroup(vertex1, vertex2))
                    {
                        unionFind.Unite(vertex1, vertex2);
                        ret += cost;
                    }
                }

                return ret;
            }
        }

        static void Main(string[] args)
        {
            var str = Console.ReadLine().Split();
            var V = Int32.Parse(str[0]);
            var E = Int32.Parse(str[1]);

            var kruskal = new Kruskal(V);

            for (int l = 0; l < E; l++)
            {
                str = Console.ReadLine().Split();
                var s = Int32.Parse(str[0]);
                var t = Int32.Parse(str[1]);
                var d = Int32.Parse(str[2]);
                kruskal.AddPath(s, t, d);
            }

            var dist = kruskal.GetCost();
            Console.WriteLine(dist);
        }
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;

namespace ConsoleApplication1
{
    class Edge
    {
        internal int from, to, cost;

        public Edge(int from, int to, int cost)
        {
            this.from = from;
            this.to = to;
            this.cost = cost;
        }
    }

    class Union_Find
    {
        internal int[] parents, rank;

        public Union_Find(int n)
        {
            parents = Enumerable.Range(0, n).ToArray();
            rank = new int[n];
        }

        public int Find(int x)
        {
            if (parents[x] == x) return x;
            else return parents[x] = Find(parents[x]);
        }

        public void Unite(int x, int y)
        {
            x = Find(x);
            y = Find(y);

            if (x == y) return;

            if (rank[x] < rank[y])
            {
                parents[x] = y;
            }
            else
            {
                parents[y] = x;
                if (rank[x] == rank[y]) rank[x]++;
            }
        }

        public bool Same(int x, int y)
        {
            return Find(x) == Find(y);
        }
    }

    class Program
    {
        static void Main(string[] args)
        {
            string[] input = Console.ReadLine().Split(' ');
            int V = int.Parse(input[0]);
            int E = int.Parse(input[1]);

            List<Edge> edges = new List<Edge>();

            for (int i = 0; i < E; i++)
            {
                input = Console.ReadLine().Split(' ');
                int s = int.Parse(input[0]);
                int t = int.Parse(input[1]);
                int w = int.Parse(input[2]);
                edges.Add(new Edge(s, t, w));
            }

            Console.WriteLine(Kruskal(edges, V));
        }

        static int Kruskal(List<Edge> edges, int V)
        {
            edges.Sort((a, b) => a.cost - b.cost);
            Union_Find UF = new Union_Find(V);

            int totalCost = 0;
            int len = edges.Count;

            for (int i = 0; i < len; i++)
            {
                Edge e = edges[i];

                if (!UF.Same(e.from, e.to))
                {
                    UF.Unite(e.from, e.to);
                    totalCost += e.cost;
                }
            }
            return totalCost;
        }
    }
}

using System.Collections.Generic;
using System.Linq;
using System;

public class PriorityQueue<T> where T : IComparable
{
    private IComparer<T> _comparer = null;
    private int _type = 0;
    private T[] _heap;
    private int _sz = 0;
    private int _count = 0;
    /// <summary>
    /// Priority Queue with custom comparer
    /// </summary>
    public PriorityQueue(int maxSize, IComparer<T> comparer)
    {
        _heap = new T[maxSize];
        _comparer = comparer;
    }

    /// <summary>
    /// Priority queue
    /// </summary>
    /// <param name="maxSize">max size</param>
    /// <param name="type">0: asc, 1:desc</param>
    public PriorityQueue(int maxSize, int type = 0)
    {
        _heap = new T[maxSize];
        _type = type;
    }

    private int Compare(T x, T y)
    {
        if (_comparer != null) return _comparer.Compare(x, y);
        return _type == 0 ? x.CompareTo(y) : y.CompareTo(x);
    }
    public void Push(T x)
    {
        _count++;
        //node number
        var i = _sz++;
        while (i > 0)
        {
            //parent node number
            var p = (i - 1) / 2;

            if (Compare(_heap[p], x) <= 0) break;

            _heap[i] = _heap[p];
            i = p;
        }
        _heap[i] = x;
    }
    public T Pop()
    {
        _count--;
        T ret = _heap[0];
        T x = _heap[--_sz];

        int i = 0;
        while (i * 2 + 1 < _sz)
        {
            //children
            int a = i * 2 + 1;
            int b = i * 2 + 2;

            if (b < _sz && Compare(_heap[b], _heap[a]) < 0) a = b;

            if (Compare(_heap[a], x) >= 0) break;

            _heap[i] = _heap[a];
            i = a;
        }
        _heap[i] = x;
        return ret;
    }
    public int Count()
    {
        return _count;
    }
    public T Peek()
    {
        return _heap[0];
    }
    public bool Contains(T x)
    {
        for (int i = 0; i < _sz; i++) if (x.Equals(_heap[i])) return true;
        return false;
    }
    public void Clear()
    {
        while (this.Count() > 0) this.Pop();
    }
    public IEnumerator<T> GetEnumerator()
    {
        var ret = new List<T>();
        while (this.Count() > 0)
        {
            ret.Add(this.Pop());
        }
        foreach (var r in ret)
        {
            this.Push(r);
            yield return r;
        }
    }
    public T[] ToArray()
    {
        T[] array = new T[_sz];
        int i = 0;
        foreach (var r in this)
        {
            array[i++] = r;
        }
        return array;
    }
}

