    for(int i = 0; i < m; i++)//全ての辺
    {
      long[] edgesGet = Array.ConvertAll(Console.ReadLine().Split(' '),long.Parse);
      edges[i,0] = edgesGet[0];
      edges[i,1] = edgesGet[1];
      edges[i,2] = edgesGet[2];
    }
    long[,] edgesSub = MinimumAllTree(edges);//最小全域木の作成
    long answer = 0;
    for(int i = 0; i < n-1; i++) answer += edgesSub[i,2];

    Console.WriteLine(answer);
	}

  static long[,] MinimumAllTree(long[,] edgesSub)
  {//unionfindでまだ繋がっていない全ての頂点を繋ぎ辺の和が最小の最小全域木で新たに繋いだ辺を返す。
  //辺数をeとして、辺の長さ順にソートするのでO(eloge)。
  //辺は0-indexの無向で[始点、終点、長さ]
    List<long> listStart = new List<long>();
    List<long> listGoal = new List<long>();
    List<long> listLength = new List<long>();
    int e = edgesSub.GetLength(0);
    long[][] edges = new long[e][];
    for(int i = 0; i < e; i++)
    {
      edges[i] = new long[3];
      for(int j = 0; j < 3; j++) edges[i][j] = edgesSub[i,j];
    }
    Array.Sort(edges, (a, b) => a[2].CompareTo(b[2]));//辺の長さでソート

    for(int i = 0; i < e; i++)
    {
      if(whatParent(edges[i][0]) != whatParent(edges[i][1]))
      {
        listStart.Add(edges[i][0]);
        listGoal.Add(edges[i][1]);
        listLength.Add(edges[i][2]);
        parents[whatParent(edges[i][0])] = whatParent(edges[i][1]);//親を結合して統一。親が2人できることはない。
      }
    }

    int answerCount = listStart.Count();
    long[,] answer = new long[answerCount,3];
    for(int i = 0; i < answerCount; i++)
    {
      answer[i,0] = listStart[i];
      answer[i,1] = listGoal[i];
      answer[i,2] = listLength[i];
    }

    return answer;
  }

  static long whatParent(long child)
  {
    if(parents[child] == child) return child;
    else return parents[child] = whatParent(parents[child]);
  }

}

