    class Kruskal
    {
        public int TotalCost { get; private set; }
        private int capacity;
        private Heap<Pair2> edges;
        public Kruskal(int capacity)
        {
            edges = new Heap<Pair2>();
            this.capacity = capacity;
        }
        public void AddEdge(int from, int to, int cost)
        {
            edges.Push(new Pair2(to, from, cost));
        }
        public void Calculate()
        {
            var uf = new UnionFind(capacity);
            while (edges.Count > 0)
            {
                var item = edges.Pop();
                if (!uf.Same(item.To, item.From))
                {
                    uf.Unite(item.To, item.From);
                    TotalCost += item.Cost;
                }
            }
        }
        class UnionFind
        {
            private int[] graph;
            private int[] rank;
            public UnionFind(int capacity)
            {
                graph = new int[capacity];
                rank = new int[capacity];
                for (int i = 0; i < capacity; i++)
                {
                    graph[i] = i;
                    rank[i] = 0;
                }
            }

            public void Unite(int first, int second)
            {
                var rootX = graph[first];
                var rootY = graph[second];
                if (rootX == rootY)
                {
                    return;
                }
                if (rank[rootX] < rank[rootY])
                {
                    graph[rootX] = rootY;
                }
                else
                {
                    graph[rootY] = rootX;
                    if (rank[rootX] == rank[rootY])
                    {
                        rank[rootX]++;
                    }
                }
            }
            public bool Same(int first, int second)
            {
                return Root(first) == Root(second);
            }
            public int Root(int x)
            {
                if (graph[x] == x)
                {
                    return x;
                }
                else
                {
                    graph[x] = Root(graph[x]);
                    return graph[x];
                }
            }
        }

        struct Pair2 : IComparable<Pair2>
        {
            public int Cost { get; }
            public int To { get; }
            public int From { get; }
            public Pair2(int to, int from, int cost)
            {
                To = to;
                From = from;
                Cost = cost;
            }

            public int CompareTo(Pair2 other)
            {
                return Cost.CompareTo(other.Cost);
            }
        }
    }
    class Heap<T> where T : IComparable<T>
    {
        private readonly List<T> heapList;
        public Heap()
        {
            heapList = new List<T>();
        }
        public Heap(int capacity)
        {
            heapList = new List<T>(capacity);
        }
        public void Push(T item)
        {
            var index = heapList.Count;
            heapList.Add(item);
            while (true)
            {
                var parentInd = (index - 1) / 2;
                var parent = heapList[parentInd];
                if (parent.CompareTo(item) > 0)
                {
                    Exchange(parentInd, index);
                    index = parentInd;
                    continue;
                }
                break;
            }
        }
        public T Pop()
        {
            var lastInd = heapList.Count - 1;
            if (lastInd == 0)
            {
                var cur = heapList[0];
                heapList.RemoveAt(0);
                return cur;
            }
            else if (lastInd < 0)
            {
                throw new InvalidOperationException();
            }
            var ret = heapList[0];
            var msi = heapList[0] = heapList[lastInd];
            heapList.RemoveAt(lastInd--);
            var current = 0;
            while (true)
            {
                var child1 = current * 2 + 1;
                var child2 = current * 2 + 2;
                if (child1 > lastInd)
                {
                    return ret;
                }
                else if (child2 > lastInd)
                {
                    if (msi.CompareTo(heapList[child1]) > 0)
                    {
                        Exchange(current, child1);
                    }
                    return ret;
                }
                if (heapList[child1].CompareTo(heapList[child2]) > 0)
                {
                    if (msi.CompareTo(heapList[child2]) > 0)
                    {
                        Exchange(current, child2);
                        current = child2;
                        continue;
                    }
                }
                else
                {
                    if (msi.CompareTo(heapList[child1]) > 0)
                    {
                        Exchange(current, child1);
                        current = child1;
                        continue;
                    }
                }
                return ret;
            }

        }
        private void Exchange(int first, int second)
        {
            var sItem = heapList[second];
            heapList[second] = heapList[first];
            heapList[first] = sItem;
        }
        public int Count => heapList.Count;
    }


    private static int UpperBound<T>(this IEnumerable<T> list, T item) where T : IComparable<T> => UpperBound(list.ToList(), item);
    private static int LowerBound<T>(this IEnumerable<T> list, T item) where T : IComparable<T> => LowerBound(list.ToList(), item);

    private static int UpperBound<T>(this List<T> list, T item) where T : IComparable<T>
    {
        return list.BinarySearch(item, -1, list.Count, (first, second) => first.CompareTo(second) > 0);
    }

    private static int LowerBound<T>(this List<T> list, T item) where T : IComparable<T>
    {
        return list.BinarySearch(item, -1, list.Count, (first, second) => first.CompareTo(second) >= 0);
    }

    private static int BinarySearch<T>(this List<T> list, T item, int left, int right, Func<T, T, bool> isOkPredicate)
    {
        while (Math.Abs(right - left) > 1)
        {
            var mid = left + (right - left) / 2;
            if (isOkPredicate(list[mid], item))
            {
                right = mid;
            }
            else
            {
                left = mid;
            }
        }
        return right;
    }


