    public class Edge
    {
        public int source, target, cost;
        public Edge(int source, int target, int cost)
        {
            this.source = source;
            this.target = target;
            this.cost = cost;
        }
        public bool Equals(Edge a)
        {
            return source == a.source && target == a.target && cost == a.cost;
        }
    }
    public class UnionFind
    {
        int[] rank;
        int[] p;
        public UnionFind(int size)
        {
            rank = new int[size];
            p = new int[size];
            for (int i = 0; i < size; i++)
            {
                rank[i] = 0;
                p[i] = i;
            }
        }
        public void Unite(int x, int y)
        {
            x = FindSet(x);
            y = FindSet(y);
            if (rank[x] > rank[y]) p[y] = x;
            if (rank[x] < rank[y]) p[x] = y;
            if (rank[x] == rank[y])
            {
                p[x] = y;
                rank[y]++;
            }
        }
        public bool Same(int x, int y)
        {
            return FindSet(x) == FindSet(y);
        }
        public int FindSet(int x)
        {
            var H = new HashSet<int>();
            while (p[x] != x)
            {
                H.Add(x);
                x = p[x];
            }
            foreach (var h in H)
            {
                p[h] = x;
            }
            return x;
        }
    }
}

