            int res = 0;
            UnionFind U = new UnionFind(v); // UnionFind 初期化
            for (int i = 0; i < e; i++)
            {
                edge eg = edges[i];
                if (!U.same(eg.S, eg.T)) // 同じ集合に属していない(=繋げても閉路にならない)場合のみ、木に併合する
                {
                    U.unite(eg.S, eg.T);
                    res += eg.Cost;
                }
            }

            Console.WriteLine(res);
        }


        public class edge
        {
            public int S { get; set; }
            public int T { get; set; }
            public int Cost { get; set; }
        }

        //// ---- union find ----
        public class UnionFind
        {
            int[] par; // 親
            int[] rank; // 深さ

            // n要素で初期化
            public UnionFind(int n)
            {
                par = new int[n];
                rank = new int[n];

                for (int i = 0; i < n; i++)
                {
                    par[i] = i;
                    rank[i] = 0;
                }
            }

            // 集合を併合する
            public void unite(int x, int y)
            {
                x = find(x); // xの根
                y = find(y); // yの根
                if (x == y) return;

                par[y] = x;
            }

            // 根を調べる
            public int find(int n)
            {
                if (par[n] == n)
                {
                    return n;
                }
                else
                {
                    return par[n] = find(par[n]); // 経路圧縮
                }
            }

            // xとyが同じ集合に属するか否か
            public bool same(int x, int y)
            {
                return find(x) == find(y);
            }
        }
    }
