    {
        static public long[] Sarray() { return ReadLine().Trim().Split().Select(long.Parse).ToArray(); }
        static public List<long> Slist() { return ReadLine().Split().Select(long.Parse).ToList(); }


        //15.5最小全域木 kruskal
        static long kruskal(int N, List<Edge> edges)
        {
            int totalcost = 0;
            edges.Sort((l, r) => l.cost - r.cost);
            DisjointSet dest = new DisjointSet(N);
            for (var i = 0; i < edges.Count; ++i)
            {
                if (!dest.same(edges[i].source, edges[i].target))
                {
                    totalcost += edges[i].cost;
                    dest.unite(edges[i].source, edges[i].target);
                }
            }
            return totalcost;
        }

        static void Main(string[] args)
        {
            var VE = Sarray();
            var V = VE[0];
            var E = VE[1];

            var edges = new List<Edge>();
            for (var i = 0; i < E; ++i)
            {
                var stw = Sarray();
                edges.Add(new Edge((int)stw[0], (int)stw[1], (int)stw[2]));
            }
            WriteLine(kruskal((int)V,edges));
        }
        public struct Edge
        {
            public int source, target, cost;
            public Edge(int s,int t, int c)
            {
                source = s;
                target = t;
                cost = c;
            }
        }
        public class DisjointSet
        {
            int[] p, rank;
            public DisjointSet(int n)
            {
                p = new int[n];
                rank = new int[n];
                for (var i = 0; i < n; ++i)
                    makeSet(i);
            }
            public void makeSet(int x)
            {
                p[x] = x;
                rank[x] = 0;
            }
            public bool same(int x, int y)
            {
                return findSet(x) == findSet(y);
            }
            public void unite(int x, int y)
            {
                link(findSet(x), findSet(y));
            }
            void link(int x, int y)
            {
                if (rank[y] < rank[x])
                { p[y] = x; }
                else
                {
                    p[x] = y;
                    if (rank[x] == rank[y])
                        ++rank[y];
                }
            }
            int findSet(int x)
            {
                if (x != p[x])
                    p[x] = findSet(p[x]);
                return p[x];
            }
        }
    }
}

