class MST
  def initialize(nv)
    @adj = Array.new(nv) { Array.new }
    @nv = nv
  end

  def connect(a, b, w)
    @adj[a].push({ to: b, cost: w })
    @adj[b].push({ to: a, cost: w })
  end

  def calc
    que = PriorityQueue.new
    que.push(St.new(0, 0))
    visited = Array.new(@nv, false)
    sum = 0
    while que.length > 0
      cur = que.pop
      next if visited[cur.p]
      visited[cur.p] = true
      sum += cur.cost
      @adj[cur.p].each do |e|
        que.push(St.new(e[:to], e[:cost])) if !visited[e[:to]]
      end
    end
    sum
  end
end

