	for i := 0; i < e; i++ {
		S[i], T[i], W[i] = ReadInt(), ReadInt(), ReadInt()
	}

	L := EdgeList{}
	for i := 0; i < e; i++ {
		s, t, w := S[i], T[i], W[i]
		L = append(L, &Edge{key: w, from: s, to: t, cost: w})
		L = append(L, &Edge{key: w, from: t, to: s, cost: w})
	}
