type Edge struct {
	s, t, w int
}

func main() {
	V, E := ReadInt(), ReadInt()
	edges := make([]*Edge, E)
	for i := 0; i < E; i++ {
		edges[i] = &Edge{
			s: ReadInt(),
			t: ReadInt(),
			w: ReadInt(),
		}
	}
	sort.Slice(edges, func(i, j int) bool {
		return edges[i].w < edges[j].w
	})
	uf := MakeUnionFind(V)
	sum := 0
	for _, edge := range edges {
		if uf.Connected(edge.s, edge.t) {
			continue
		}
		uf.Unite(edge.s, edge.t)
		sum += edge.w
	}
	fmt.Println(sum)
}

type UnionFind []int

func MakeUnionFind(size int) UnionFind {
	parent := make([]int, size)
	for i := 0; i < size; i++ {
		parent[i] = i
	}
	return parent
}
func (uf UnionFind) Unite(x, y int) {
	if x, y = uf.Root(x), uf.Root(y); x != y {
		uf[x] = y
	}
}
func (uf UnionFind) Connected(x, y int) bool { return uf.Root(x) == uf.Root(y) }
func (uf UnionFind) Root(x int) int {
	if uf[x] == x {
		return x
	}
	uf[x] = uf.Root(uf[x])
	return uf[x]
}

