class Main {

    companion object {
        private lateinit var edgeList: Array<Edge>

        private val nodeList = arrayListOf<Node>()

        private var weightSum = 0

        fun init() {
            val (nodeNum, edgeNum) = readLine()!!.split(" ")


            edgeList = Array(edgeNum.toInt()) {
