                Edge(source.toInt(), target.toInt(), weight.toInt())
            }

            val sortManager = MergeSortManager()

            // そーと
            edgeList = sortManager.execute(edgeList)

            for (index in 1..nodeNum.toInt()) {
                nodeList.add(Node())
            }
        }


        fun execute() {

            var currentIndex = 0

            var unionNum = 0
            while (true) {
                val edge = edgeList.getOrNull(currentIndex) ?: break

                val sourceRootId = getRootNodeIndex(edge.source)
                val targetRootId = getRootNodeIndex(edge.target)

                // くっつける
                if (sourceRootId != targetRootId) {
                    unionNum++
                    weightSum += edge.weight
                    nodeList[sourceRootId].parent = targetRootId

                    if (unionNum == nodeList.size) {
                        break
                    }
                }

                currentIndex++
            }
        }

        fun display() {

            println(weightSum)
        }


        fun getRootNodeIndex(id: Int): Int {
