class MergeSortManager {

//    fun init() {
//
//        readLine()
//
//        inputs = readLine()!!.split(" ").map { it.toInt() }
//
//    }

    fun execute(inputs: Array<Edge>): Array<Edge> {
        return mergeSort(inputs)
    }

    /**
     * 配列をまーじそーと。
     */
    fun mergeSort(list: Array<Edge>): Array<Edge> {

        if (list.size <= 1) {
            return list
        }

        val mediumIndex = (list.size / 2.0).toInt()

        val sortList1 = if (mediumIndex == 1)
            Array(1) { list[0] }
//            arrayListOf(list[0])
//        else mergeSort(list.subList(0, mediumIndex))
        else mergeSort(list.copyOfRange(0, mediumIndex))


        val sortList2 = if (mediumIndex - list.size == 1)
//            arrayListOf(list[mediumIndex])
            Array(1) { list[mediumIndex] }
        else mergeSort(list.copyOfRange(mediumIndex, list.size))

        val orderList = arrayListOf<Edge>()

        var sortList1Index = 0
        var sortList2Index = 0
        while (orderList.size != (sortList1.size + sortList2.size)) {

            /**
             * 空の確認
             */
            if (sortList2.size == sortList2Index) {
                orderList.add(sortList1[sortList1Index])
                sortList1Index++
                continue
            } else if (sortList1.size == sortList1Index) {
                orderList.add(sortList2[sortList2Index])
                sortList2Index++
                continue
            }

            /**
             * 比較
             */
            if (sortList1[sortList1Index] < sortList2[sortList2Index]) {
                orderList.add(sortList1[sortList1Index])
                sortList1Index++
            } else {
                orderList.add(sortList2[sortList2Index])
                sortList2Index++
            }
        }

        return orderList.toTypedArray()
    }
}


