        self.E.append((weight, init, end))

    def min_spanning_tree(self):
        N, E = self.N, self.E
        weight = 0; edges = []
        n_edges = 0
        uf = UnionFind(N) # for judging connectivity
        E = sorted(E)
        for w, a, b in E:
            if uf.union(a, b):
                edges.append((a, b))
                n_edges += 1; weight += w
            if n_edges == N - 1: break
        return edges, weight

