    def __init__(self,size):
        self.rank = [None]*size
        self.p = [None]*size
        for i in range(size):
            self.make_set(i)
        return

    def make_set(self,x):
        self.p[x] = x
        self.rank[x] = 0
        return

    def same(self,x,y):
        return self.find_set(x) == self.find_set(y)

    def unite(self,x,y):
        self.link(self.find_set(x),self.find_set(y))
        return

