def kruskal(graph):
	V = len(graph)
	cluster = [[i] for i in xrange(V)]

	pq = []
	for i, node in enumerate(graph):
		for edge in node:
			heapq.heappush(pq, (edge.cost, i, edge.to))


	tree = []

	while len(pq) != 0:
		_edge = heapq.heappop(pq)

		_from = _edge[1]
		_to = _edge[2]
		cluster_from = get_belonged_cluster(cluster, _from)
		cluster_to = get_belonged_cluster(cluster, _to)
		# print cluster
		# print _edge
		# print cluster_from, cluster_to
		# print

		if cluster_from != cluster_to:
			tree.append(_edge[0])
			cluster[cluster_from].extend(cluster[cluster_to])
			cluster.pop(cluster_to)

	return tree





