        self.V = V
        self.E = edges

    # O(E*log(V))
    def kruskal(self):
        U = UnionFind(self.V)
        total = 0
        for e in self.E.getInOrderByASC():
            if not U.same(e.src, e.to):
                total += e.weight
                U.unite(e.src, e.to)
        return total


