#[derive(Debug, Clone)]
struct UnionFind {
    table: Vec<i32>,
    num: usize,
}
impl UnionFind {
    fn new(n: usize) -> UnionFind {
        UnionFind {
            table: vec![-1; n],
            num: n,
        }
    }
    fn root(&mut self, x: usize) -> usize {
        let mut r = x;
        if self.table[x] >= 0 {
            let t = self.table[x] as usize;
            r = self.root(t);
            self.table[x] = r as i32;
        }
        r
    }
    fn find(&mut self, x: usize, y: usize) -> bool {
        self.root(x) == self.root(y)
    }
    fn size(&mut self, x: usize) -> usize {
        let r = self.root(x);
        (-self.table[r]) as usize
    }
    fn union(&mut self, x: usize, y: usize) {
        let xr = self.root(x);
        let yr = self.root(y);
        if xr != yr {
            if self.size(xr) < self.size(yr) {
                self.table[yr] += self.table[xr];
                self.table[xr] = yr as i32;
            } else {
                self.table[xr] += self.table[yr];
                self.table[yr] = xr as i32;
            }
            self.num -= 1;
        }
    }
}

#[derive(Debug, Clone, Copy, PartialEq, PartialOrd, Ord, Eq)]
struct Edge {
    from: usize,
    to: usize,
    cost: i64,
}

// O(V^3)
fn mst_cost(mut edges: Vec<Edge>, n: usize) -> i64 {
    let mut res = 0;
    let mut uf = UnionFind::new(n);
    edges.sort_by(|x, y| x.cost.cmp(&y.cost));
    for e in edges {
        if !uf.find(e.from, e.to) {
            res += e.cost;
            uf.union(e.from, e.to);
        }
        if uf.num == 1 {
            break;
        }
    }
    res
}

fn solve() {
    let (v, e): (usize, usize) = (read::<usize>(), read::<usize>());
    let mut edges = vec![];
    for _ in 0..e {
        let edge = Edge {
            from: read(),
            to: read(),
            cost: read(),
        };
        edges.push(edge);
    }
    println!("{}", mst_cost(edges, v));
}

