    #[inline]
    fn cmp(&self, other: &Reverse<T>) -> Ordering {
        other.0.cmp(&self.0)
    }
}

fn solve(nv: usize, _ne: usize, e: &[(usize, usize, i32)]) -> i32 {
    let mut g = vec![BTreeMap::new(); nv];
    for &(s, t, w) in e.iter() {
        g[s].insert(t, w);
        g[t].insert(s, w);
    }
    let v = 0;
    let mut vis = vec![false; nv];
    vis[v] = true;
    let mut h = g[v].iter().map(|(&t, &w)| Reverse((w, v, t))).collect::<BinaryHeap<_>>();
    let mut e = Vec::new();
    while let Some(Reverse((w, s, t))) = h.pop() {
        if vis[s] && !vis[t] {
            e.push((s, t, w));
            vis[t] = true;
            for (&u, &w) in g[t].iter() {
                if !vis[u] {
                    h.push(Reverse((w, t, u)));
                }
            }
        }
    }
    e.iter().map(|&(_, _, w)| w).sum::<i32>()
}

fn main() {
    let mut buf = String::new();
    std::io::stdin().read_to_string(&mut buf).unwrap();
    let mut iter = buf.split_whitespace();
    let nv: usize = iter.next().unwrap().parse().unwrap();
    let ne: usize = iter.next().unwrap().parse().unwrap();
    let e = (0..ne)
        .map(|_| {
            let s: usize = iter.next().unwrap().parse().unwrap();
            let t: usize = iter.next().unwrap().parse().unwrap();
            let w: i32 = iter.next().unwrap().parse().unwrap();
            (s, t, w)
        })
        .collect::<Vec<_>>();
    let w = solve(nv, ne, &e);
    println!("{}", w);
}

